function legacy_getSceneNpcs(sceneName=state.scene){
 const base=[...(SCENES[sceneName]?.npcs||[]),...(SECONDARY_NPCS[sceneName]||[])].filter(n=>!(sceneName==='benifaio'&&n.id==='awelo'&&state.flags.blasWon));
 if(sceneName==='burger'&&state.flags.blasWon){
  base.push({id:'aweloSilla',who:'awelo',x:4,y:7,label:'El Rayo Amarillo'});
  base.push({id:'blasBH',who:'blas',x:6,y:5,label:'El Sensei'});
  base.push({id:'nachitoBH',who:'nachito',x:12,y:9,label:'El Alquimista'});
 }
 if(sceneName==='benifaio'){
  const chosen=state.player?.chosen||'marshall';
  const starters=[
   {id:'marshallNpc',who:'marshall',x:30,y:14,label:'Marshall'},
   {id:'nachito',who:'nachito',x:32,y:16,label:'Nachito'},
   {id:'plataNpc',who:'plata',x:34,y:24,label:'Plata'}
  ].filter(n=>n.who!==chosen);
  return [...base,...starters];
 }
 return base;
}
