function burgerGroupDialogue(script,onEnd){
 state.screen='dialog';let step=0;
 const cast=['blas','awelo','nachito','javi_cocinero'];
 for(const id of cast)meetFriend(id);
 function render(){
  const entry=script[step],who=entry[0],line=entry[1],p=getProfile(who);
  const castStrip=cast.map(id=>`<div class="cast-face ${id===who?'speaking':''}" title="${getProfile(id).name}">${portraitHtml(id)}<small>${id==='awelo'?'Awelo':id==='javi_cocinero'?'Javi':id==='nachito'?'Nachito':'Blas'}</small></div>`).join('');
  showModal(`<div class="eyebrow">ESCENA ESPECIAL · BURGER L’HORTA</div><div class="group-cast">${castStrip}</div><div class="dialog-person group-dialog">${portraitHtml(who)}<div class="dialog-copy"><div class="speaker-tag">${p.tag}</div><h2>${p.name}</h2><div class="dialog-step">${step+1} / ${script.length}</div><p>${line}</p></div></div>${buttons(`<button class="primary" id="nextGroup">${step===script.length-1?'CONTINUAR ✓':'SIGUIENTE →'}</button>`)}`,'dialog');
  $('nextGroup').onclick=()=>{step++;if(step<script.length)render();else{hideModal();state.screen='world';onEnd?.()}};
 }
 render();
}
