function drawTerrainEdges(scene,xs,xe,ys,ye){
 const hard=new Set(['plaza','stone','path','route']);
 for(let y=ys;y<ye;y++)for(let x=xs;x<xe;x++){
  const mat=sceneGround(scene,x,y)[0];if(!hard.has(mat))continue;
  let mask=0;
  if(y>0&&!hard.has(sceneGround(scene,x,y-1)[0]))mask|=1;
  if(x<SCENES[scene].w-1&&!hard.has(sceneGround(scene,x+1,y)[0]))mask|=2;
  if(y<SCENES[scene].h-1&&!hard.has(sceneGround(scene,x,y+1)[0]))mask|=4;
  if(x>0&&!hard.has(sceneGround(scene,x-1,y)[0]))mask|=8;
  if(mask){const i=asset('world_groundedge'+mask);if(i.complete&&i.naturalWidth)ctx.drawImage(i,x*TILE,y*TILE,TILE,TILE)}
 }
}
