 const hi=HI_RES_CHARACTERS.has(who), fw=hi?64:32, fh=hi?96:48;
 ctx.fillStyle='#244a4459';ctx.beginPath();ctx.ellipse(x,y-5,20,7,0,0,Math.PI*2);ctx.fill();
 if(img.complete&&img.naturalWidth){ctx.drawImage(img,col*fw,row*fh,fw,fh,dx,dy,64,96)}else{rect(x-15,y-57,30,46,'#253f35');rect(x-12,y-80,25,25,'#d2a27d')}
