function normalizeMon(p){
 p.status=p.status||'';p.sleep=p.sleep||0;p.pp=p.pp||{};
 const pool=availableMoves(p);if(!Array.isArray(p.moves)||!p.moves.length)p.moves=(typeof LEARNSETS35!=='undefined'&&LEARNSETS35[p.name]?learnsetMoves35(p):pool).slice(-4);
 for(const m of pool)if(!Number.isFinite(p.pp[m]))p.pp[m]=MOVES[m].pp;
 return p;
}
function normalizeExtras(){
 state.badges=Array.isArray(state.badges)?state.badges:[];state.box=Array.isArray(state.box)?state.box:[];
 state.money=Number.isFinite(state.money)?state.money:600;state.bag={...FRESH_BAG,...state.bag};
 state.party.forEach(normalizeMon);state.box.forEach(normalizeMon);
 state.flags=state.flags||{};
}
function validSave(o){
 if(!o||o.v!==1||!SCENES[o.scene]||!CHARS[o.player?.chosen]||!o.flags||typeof o.flags!=='object'||Array.isArray(o.flags))return false;
 const sc=SCENES[o.scene],p=o.player;
 if(!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<1||p.y<1||p.x>sc.w-1||p.y>sc.h-1)return false;
 if(!Array.isArray(o.party)||o.party.length>6||(o.flags.starter&&!o.party.length))return false;
 const good=m=>m&&SPECIES[m.name]&&Number.isInteger(m.lvl)&&m.lvl>0&&m.lvl<=100&&Number.isFinite(m.maxHp)&&m.maxHp>0&&m.maxHp<=1000&&Number.isFinite(m.hp)&&m.hp>=0&&m.hp<=m.maxHp&&Number.isFinite(m.xp)&&m.xp>=0&&m.xp<100000&&(!m.pp||Object.entries(m.pp).every(([k,v])=>MOVES[k]&&Number.isFinite(v)&&v>=0&&v<=Math.max(MOVES[k].pp,MOVES[k].legacyPP||0)))&&(!m.status||['veneno','sueño','tóxico','parálisis','quemadura','congelación'].includes(m.status))&&(!m.moves||Array.isArray(m.moves)&&m.moves.length>0&&m.moves.length<=4&&new Set(m.moves).size===m.moves.length&&m.moves.every(x=>availableMoves(m).includes(x)))&&(!m.toxicCount||Number.isInteger(m.toxicCount)&&m.toxicCount>=0&&m.toxicCount<=16);
 if(!o.party.every(good)||o.box&&(!Array.isArray(o.box)||o.box.length>300||!o.box.every(good)))return false;
 if(!Number.isInteger(o.balls)||o.balls<0||o.balls>9999)return false;
 if(o.money!==undefined&&(!Number.isFinite(o.money)||o.money<0||o.money>9999999))return false;
 if(o.bag&&(!Object.keys(o.bag).every(k=>k in FRESH_BAG)||!Object.values(o.bag).every(v=>Number.isInteger(v)&&v>=0&&v<=9999)))return false;
 if(o.badges&&(!Array.isArray(o.badges)||o.badges.some((v,i)=>v!==i)||o.badges.length>BADGES.length))return false;
 const scalar80=v=>typeof v==='boolean'||Number.isInteger(v)&&v>=0&&v<=10000;
 const record80=(v,depth=0)=>v&&typeof v==='object'&&!Array.isArray(v)&&depth<3&&Object.keys(v).length<=100&&Object.entries(v).every(([k,x])=>/^[a-zA-Z0-9_:-]{1,80}$/.test(k)&&!['__proto__','prototype','constructor'].includes(k)&&(scalar80(x)||record80(x,depth+1)));
 if(Object.entries(o.flags).some(([k,v])=>!scalar80(v)&&!(['reliquias70','caos70','v80_dimension404'].includes(k)&&record80(v))))return false;
 return ['journal','metFriends'].every(k=>!o[k]||Array.isArray(o[k])&&o[k].length<300&&o[k].every(x=>typeof x==='string'&&x.length<100));
}
