function choiceScreen(title,body,options){state.screen='menu';showModal(`<div class="eyebrow">HISTORIAS DEL JUEVES</div><h2>${title}</h2><p>${body}</p><div class="quiz-choices">${options.map((o,i)=>`<button class="${i===0?'primary':'secondary'}" id="opt${i}">${o[0]}</button>`).join('')}</div>${buttons('<button class="secondary" id="leaveChoice">VOLVER AL MAPA</button>')}`);options.forEach((o,i)=>$('opt'+i).onclick=o[1]);$('leaveChoice').onclick=backWorld;}
function gymChallenge(id){normalizeExtras();const g=GYMS[id];
 if(state.badges.includes(g.i)){dialog(id,['Tu medalla está firmada. Los jueves se defienden juntos.','Puedes seguir explorando los encargos y entrenar en las zonas de hierba.']);return}
 if(state.badges.length<g.i){dialog(id,[`Antes necesitas la medalla ${BADGES[g.i-1][0]}, de ${BADGES[g.i-1][2]}. La aventura tiene un orden; yo te espero.`]);return}
 if(!state.flags[g.flag]){dialog(id,[{sergio:'El acta aún no está lista. Alfaro está en la plaza de Silla. Tiene seis conversaciones, y se acuerda de por cuál vas.',blas:'Javi necesita ayuda con la mesa del jueves antes del combate. Examina la mesa del Burger.',plata:'Primero hay que leer los espacios. Acércate a mi pizarra en esta pista.',horte:'Primero, las diapositivas de la plaza de Sueca. Te prometo que solo son tres de las cuarenta y siete.',nachito:'Revisa las tres estaciones del laboratorio: etiquetas, estados y fórmula imposible.'}[id]]);if(id==='plata')plataPuzzle();return}
 choiceScreen('Medalla '+BADGES[g.i][0],`${getProfile(id).name}: «${g.intro}» · Equipo rival: ${g.team.map(x=>x[0]+' Nv. '+x[1]).join(', ')}. Tu equipo se cura antes del reto.`,[['¡Vamos a combatir!',()=>{backWorld();healAll();startBattle(g.team[0][0],g.team[0][1],false,'gym:'+id)}]]);
}
function plataPuzzle(hint=''){choiceScreen('La pizarra del Hombre de Recursos',hint||'Cinco compañeros, cinco espacios. Ya hay alguien con balón en el centro y dos abiertos en las esquinas. Para evitar que todos se amontonen, ¿dónde colocarías a los otros dos?',[
 ['Uno a cada lado, dejando libre el camino al aro',()=>{state.flags.spacesReady=true;save();dialog('plata',['A ver, es que… si ocupamos todos el mismo espacio, no hay recursos. Así sí.','Ahora podemos jugar. Y después, si quieres, miramos las 87 comparativas.'],()=>gymChallenge('plata'))}],
 ['Los dos junto al balón',()=>plataPuzzle('Pista: si cuatro ocupan el centro, ¿por dónde puede avanzar quien tiene el balón?')]
 ]);}
function actaTalk(){const lines=['Alfaro: nombre del solicitante: Sergio. Profesión: acabar esto y dormir.','Alfaro: motivo del permiso: reunión del jueves. No es una urgencia; es tradición.','Alfaro: responsable suplente: el Awelo. Sergio: «Pues peor me lo pones».','Alfaro: observaciones: la franquicia NBA sigue sin encontrar a PELLE.','Alfaro: falta una firma. Sergio: «Me da tiempo a una siesta entre sellos».','Alfaro: «Uy, se me escapó un pedo». Sergio: «¡A segunda! TAAHH». Acta terminada.'];const k=state.flags.actaTalks||0;
 if(k>=6){dialog('alfaro',['Acta preparada. El pabellón está al norte de la plaza. Sergio ya tiene permiso para combatir.']);return}
 dialog('alfaro',[`ACTA INFINITA · ${k+1} / 6`,lines[k]],()=>{state.flags.actaTalks=k+1;if(k===5){state.flags.actaReady=true;noteQuest('acta')}save();choiceScreen('El acta · '+(k+1)+'/6',k===5?'Ya está todo firmado. Entra al pabellón.':'Alfaro toma aire. Puedes seguir ahora o volver después; el progreso se guarda.',k===5?[['Ir a la plaza',backWorld]]:[['Seguir la conversación',actaTalk],['Pausa para respirar',backWorld]])});}
function slidePuzzle(hint=''){const k=state.flags.slideStep||0;if(k>=3){dialog('horte',['La explicación ya está. El ejemplo está dentro del refugio.','He preparado a Slowbro. Puedes venir cuando quieras.']);return}
 const cards=[['Diapositiva 1 · La que sobra','Para ayudar al equipo, una diapositiva habla de descansar y otra de escuchar. La tercera contiene 87 fotos de motos. ¿Cuál sobra?',['Las 87 motos','Escuchar'],0],['Diapositiva 2 · Transición eterna','La animación tarda cuarenta minutos. Horte no ha empezado con los ejemplos. ¿Qué botón salva la reunión?',['Saltar transición','Repetir desde el principio'],0],['Diapositiva 3 · Confía en el 5%','El 5% es un lema del grupo. ¿Cómo conseguimos que el reto sea justo?',['Dar pistas y permitir repetir','Decidir por azar si puedes pasar'],0]][k];
 choiceScreen(cards[0],hint||cards[1],cards[2].map((a,i)=>[a,()=>{if(i!==cards[3]){slidePuzzle('Horte sonríe: «Pista: tenemos que poder terminar la reunión esta noche».');return}state.flags.slideStep=k+1;if(k===2){state.flags.slidesReady=true;noteQuest('diapos')}save();dialog('horte',[k===2?'Has quedado hechizado, roaar. Tres diapositivas. Ni siquiera me ha dado tiempo a aburrirme.':'Correcto. Ahora viene la parte verdaderamente interesante.'],()=>slidePuzzle())}]));}
function npcTalk(n){normalizeExtras();meetFriend(n.who);
 if(n.id.startsWith('gym_')){gymChallenge(n.id.slice(4));return}
 if(n.id==='blasBH'&&state.flags.burgerGroupDone){gymChallenge('blas');return}
 if(n.id==='sillaGuide'){actaTalk();return}
 if(n.id==='horteSlides'){slidePuzzle();return}
 if(n.id==='permiso'){if(state.flags.permiso){dialog('funcionario',['La solicitud ya está sellada. Sergio tiene el permiso. Por una vez, ningún papel extra.']);return}state.flags.permiso=true;state.money+=200;noteQuest('permiso');dialog('funcionario',['Solicitud de permiso de los jueves: aprobada. He enviado una copia a Sergio.','Te entrega una gorra BH para el recuerdo y 200 monedas para los gastos.']);save();return}
 if(n.id==='plataQuest'){if(state.flags.tireDone){dialog('plata',['Hostia, muchas gracias. Aunque ahora estoy mirando otra moto y no sé si me servirá…']);return}if(state.flags.tirePicked){state.flags.tireDone=true;state.money+=300;if(!state.flags.expShare){state.flags.expShare=true;noteQuest('exp')}noteQuest('neumatico');save();dialog('plata',['A ver, es que… llevabas el neumático correcto. He comprobado las 87 comparativas.','Juanchino y yo compartimos el mismo Repartir Experiencia: si ya lo tienes, no hay un segundo. Toma 300 monedas por el recado.']);return}state.flags.tireQuest=true;save();dialog('plata',['Necesito un neumático tubeless. Está en Recambios, junto al taller de esta plaza.','He comparado diecisiete motos y ya sé cuál me convence. Bueno… ha salido otra opción.']);return}
 if(n.id==='tireShop'){if(!state.flags.tireQuest){dialog('concesionario',['Plata está al sur de la pista. Lleva tres meses decidiendo. Igual necesita un recambio.']);return}state.flags.tirePicked=true;save();dialog('concesionario',['Aquí está el neumático de Plata. No pesa mucho; lo que pesa son sus comparativas.','Vuelve con él. El recambio solo se entrega una vez.']);return}
 if(n.id==='surpriseGrau'){dialog('javi_grau',['Plata: «¿Pero tú de dónde has salido?».','Estaba por aquí. Si aún no has recuperado mi mapa, mira los carteles del sur de Albal.','Recordad, niños, hay que reciclar en casa.']);return}
 if(n.id.startsWith('heal')){healAll();dialog(n.who,[n.id==='healSilla'?'Hoy haré la siesta. Tu equipo puede descansar también. El permiso se recoge en la oficina.':'Descansamos, recuperamos PS y PP, y seguimos. Nadie llega a la Liga solo.','Equipo curado. También puedes usar el viaje entre plazas desde EQUIPO si ya has visitado el lugar.']);return}
 legacy_npcTalk(n);if(n.id==='cocinero'||n.id==='awelo')healAll();
}
function landmarkTalk(p){normalizeExtras();if(p.id==='portal'){const t=p.portal;if(!state.flags.starter){toast('Primero recoge tu Pokémon con Alfaro.');return}if(t.need&&state.badges.length<t.need){toast(`Este camino requiere ${t.need} medallas. Consulta tu objetivo.`);return}changeScene(t.to,t.spawn);markVisited();return}
 if(p.id==='mapBoard'){if(state.flags.mapDone){dialog('javi_grau',['El mapa está de vuelta. Benifaió al oeste, Silla al norte, L’Alqueria al este.','Recordad, niños, hay que reciclar en casa.']);return}choiceScreen('La ruta de la hamburguesa asequible','El Clan Cayetano ha cambiado dos carteles. En el mapa del Burger pone: «La mesa se comparte; el precio no cambia al llegar». ¿Qué cartel devuelve el mapa a Javi?',[
 ['Burger L’Horta · misma carta para toda la mesa',()=>{state.flags.mapDone=true;state.money+=250;state.balls+=3;noteQuest('mapa');save();dialog('javi_grau',['Antes tenía un mapa. Era bastante más rápido. Ahora, otra vez.','El Clan Cayetano se queda sin cartel falso. +250 monedas y tres Poké Balls.']);}],['Tarifa secreta: preguntar al llegar',()=>dialog('javi_grau',['Eso no es una pista, es otra trampa del cartel. Puedes volver a intentarlo.'])]]);return}
 if(p.id==='catTrail'){if(state.flags.catDone){dialog('horte',['La mochila del gato vuelve a estar conmigo. Ahora puedo perder otras cosas.']);return}choiceScreen('La mochila del gato','Hay huellas junto a un trozo de tela, y un cascabel suena tras el banco del refugio. ¿Qué haces?',[
 ['Seguir las huellas y mirar detrás del banco',()=>{state.flags.catDone=true;state.bag.potion+=3;noteQuest('gato');save();dialog('horte',['No estaba esperando visitas. Pero estaba preparado para recibirlas.','La mochila es la mía, la del gato. Tres pociones por ayudarme. Confía en el 5%.']);}],['Buscar en las 87 comparativas de Plata',()=>dialog('horte',['De esa investigación no sale nadie esta semana. Mira las huellas.'])]]);return}
 legacy_landmarkTalk(p);
}
function markVisited(){if(state.flags.starter){state.flags['visited_'+state.scene]=true;save()}}
const baseChangeScene=changeScene;changeScene=function(n,spawn){baseChangeScene(n,spawn);markVisited()};
function terrainRule(scene,x,y){if(NEW_TOWNS.includes(scene)){const square=insideOval(x,y,17,16,8,6);const road=Math.abs(y-16)<2||Math.abs(x-16)<2&&y>8;return [square?'plaza':road?'path':x>24&&y>18?'meadow':'grass',Math.floor(rand(x,y,4)*4)]}if(scene.startsWith('gym_'))return ['interior_lab',Math.floor(rand(x,y)*3)];return legacy_terrainRule(scene,x,y)}
function drawTownProps(s){if(!NEW_TOWNS.includes(state.scene)){legacy_drawTownProps(s);return}for(let x=1;x<s.w-1;x+=2){drawTree(x*TILE,2*TILE);drawTree(x*TILE,25*TILE)}for(let y=4;y<24;y+=3){drawTree(TILE,y*TILE);if(Math.abs(y-16)>2)drawTree(32*TILE,y*TILE)}drawFountain(17*TILE,16*TILE);for(const x of [10,22]){drawBench(x*TILE,18*TILE);drawLamp(x*TILE,12*TILE)}for(let x=25;x<31;x++)for(let y=20;y<23;y++)drawGrass(x*TILE,y*TILE);drawPlanter(13*TILE,20*TILE,3);
 if(state.scene==='sueca'){ctx.fillStyle='#f6d896';ctx.font='24px sans-serif';ctx.fillText('🐾',27*TILE,15*TILE)}
}
const oldBuilding=drawBuilding;drawBuilding=function(b){if(b.type!=='gym'){oldBuilding(b);return}const x=b.x*TILE,y=b.y*TILE,w=b.w*TILE,h=b.h*TILE;const color={silla:'#4d7592',alqueria:'#b4663f',sueca:'#477859'}[state.scene];rect(x+9,y+h-25,w,38,'#153b3144');rect(x+8,y+64,w-16,h-64,'#ede3c9');rect(x,y+15,w,65,color);rect(x+12,y+24,w-24,7,'#efd98b');for(const xx of [30,w-80]){rect(x+xx,y+104,50,83,'#315a67');rect(x+xx+6,y+110,38,32,'#9bd3cf');rect(x+xx+6,y+148,38,32,'#79acae')}rect(x+w/2-30,y+h-65,60,65,'#29484a');rect(x+w/2-4,y+h-60,8,55,'#f0cf7a');ctx.font='bold 18px sans-serif';ctx.fillStyle='#fff8dc';ctx.textAlign='center';ctx.fillText(b.label,x+w/2,y+62);ctx.textAlign='left';};
function drawGymFloor(){ if(state.scene.startsWith('gym_')){const g=GYMS[state.scene.slice(4)];rect(4*TILE,7*TILE,12*TILE,4*TILE,'#234b4b44');ctx.strokeStyle='#f6df9a';ctx.lineWidth=4;ctx.strokeRect(4*TILE,7*TILE,12*TILE,4*TILE);for(const x of [1,17]){rect(x*TILE,3*TILE,2*TILE,8*TILE,'#56786b');for(let y=4;y<11;y++)rect(x*TILE+5,y*TILE,2*TILE-10,8,'#9fbb9e')}for(const x of [5,14]){drawMiniBall(x*TILE,4*TILE);drawLamp(x*TILE,3*TILE)}ctx.beginPath();ctx.arc(10*TILE,9*TILE,48,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff1c5';ctx.font='bold 20px sans-serif';ctx.textAlign='center';ctx.fillText('MEDALLA '+BADGES[g.i][0].toUpperCase(),10*TILE,2*TILE);ctx.textAlign='left';}
}
function renderWorld(){legacy_renderWorld();const sc=SCENES[state.scene];const cx=clamp(camera.x,0,Math.max(0,sc.w*TILE-W));let cy=clamp(camera.y,0,Math.max(0,sc.h*TILE-H));if(sc.h*TILE<H)cy=(sc.h*TILE-H)/2;ctx.save();ctx.translate(-Math.floor(cx),-Math.floor(cy));

 for(const p of PORTALS[state.scene]||[]){const xx=p.x*TILE,yy=p.y*TILE;ctx.fillStyle='#e8ce76';ctx.globalAlpha=.65+.25*Math.sin(elapsed*3);ctx.beginPath();ctx.ellipse(xx,yy,23,10,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.font='bold 12px sans-serif';ctx.textAlign='center';const width=ctx.measureText(p.label).width+16;rect(xx-width/2,yy-38,width,23,'#163d43ee');ctx.fillStyle='#fff2c5';ctx.fillText(p.label,xx,yy-22);ctx.textAlign='left';}
 // Small drifting leaves, camera-space only: no per-frame DOM nodes or image allocations.
 if(!['lab','burger'].includes(state.scene)&&!state.scene.startsWith('gym_')){ctx.fillStyle='#f8e6a488';for(let i=0;i<9;i++){const x=((elapsed*12+i*187)%(sc.w*TILE)),y=((elapsed*9+i*119)%(sc.h*TILE));ctx.fillRect(x,y,5,3)}}ctx.restore();}
// Directional atlas 2.0. Old sheets stay in assets as a fallback.
const ATLAS_FRIENDS={alfaro:0,sergio:1,horte:2,blas:3};
const ATLAS_FRAMES=[[[80, 38, 168, 308], [91, 355, 149, 292], [88, 655, 144, 292], [80, 955, 159, 291]], [[387, 39, 162, 307], [392, 355, 146, 295], [391, 657, 148, 292], [384, 955, 161, 291]], [[665, 39, 181, 307], [666, 355, 184, 295], [657, 657, 182, 293], [668, 955, 164, 291]], [[974, 40, 181, 306], [982, 355, 183, 295], [963, 654, 172, 296], [969, 954, 165, 292]]];
const legacyDrawCharacter=drawCharacter;
drawCharacter=function(who,x,y,dir,anim=0){
 if(!(who in ATLAS_FRIENDS)){legacyDrawCharacter(who,x,y,dir,anim);return}
 const im=asset('friends_atlas20');if(!im.complete||!im.naturalWidth){legacyDrawCharacter(who,x,y,dir,anim);return}
 const f=ATLAS_FRAMES[ATLAS_FRIENDS[who]][dir],bob=anim?Math.sin(elapsed*5)*1.5:0;const dh=90,dw=dh*f[2]/f[3];
 ctx.fillStyle='#244a4459';ctx.beginPath();ctx.ellipse(x,y-5,19,6,0,0,Math.PI*2);ctx.fill();
 ctx.drawImage(im,...f,x-dw/2,y-93+bob,dw,dh);
};
let audioOn=false,audioContext=null;
function beep(freq=520,dur=.08){if(!audioOn)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+dur);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+dur)}catch{}}
function pulse(id){const el=$(id);el.classList.remove('hit-flash');void el.offsetWidth;el.classList.add('hit-flash');beep(270,.07)}
function activeMon(){return state.party[battle?.active||0]}
function later(fn,ms=650){const token=battle;setTimeout(()=>{if(battle===token&&token)fn()},ms)}
function startBattle(n,l,wild=true,trainerId='blas'){resetJoy27();if(state.screen!=='world'||!state.party.some(p=>p.hp>0))return;normalizeExtras();const gymId=trainerId.startsWith('gym:')?trainerId.slice(4):null;const team=gymId?GYMS[gymId].team:[[n,l]];state.screen='battle';heldKeys.clear();joystick.x=joystick.y=0;battle={enemy:createMon(team[0][0],team[0][1]),roster:team,index:0,active:state.party.findIndex(p=>p.hp>0),wild,trainerId,gymId,locked:false,xp:0,log:wild?`¡${n} salvaje! Debilítalo antes de lanzar una Poké Ball.`:`${getProfile(gymId||trainerId).name} envía a ${team[0][0]}.`,arena:false};setupGymEnemy();markSeen29(battle.enemy.name);battleUI.classList.remove('hidden');battleUI.classList.add('battle-enter');later(()=>battleUI.classList.remove('battle-enter'),450);updateBattle();}
function updateBattle(){if(!battle)return;const ours=activeMon(),enemy=battle.enemy;
 for(const [side,p] of [['enemy',enemy],['our',ours]]){$(side+'Name').textContent=p.name.toUpperCase()+(p.status?' · '+p.status.toUpperCase():'');$(side+'Lvl').textContent='Nv. '+p.lvl+' · '+(SPECIES[p.name].types||[SPECIES[p.name].type]).join('/');$(side+'Pic').src='assets/mon22_'+p.name.toLowerCase()+(side==='our'?'_back':'_front')+'.png';$(side+'HP').style.width=clamp(100*p.hp/p.maxHp,0,100)+'%';$(side+'HP').style.background=p.hp/p.maxHp<.25?'#e56f62':p.hp/p.maxHp<.5?'#e5c26a':''}
 $('ourHPText').textContent=ours.hp+'/'+ours.maxHp+' PS';$('battleText').textContent=battle.log;const acts=$('battleActions');acts.innerHTML='';const add=(label,fn,disabled=false)=>{const b=document.createElement('button');b.textContent=label;b.disabled=battle.locked||disabled;b.onclick=fn;acts.append(b)};
 const moves=movesFor(ours);for(let i=0;i<moves.length;i++){const m=moves[i];add(`${i+1} · ${m} · ${MOVES[m].type} · ${ours.pp[m]} PP`,()=>attack(i),ours.pp[m]<=0)}
 add('C · ◉ POKÉ BALL ×'+state.balls,throwBall,!battle.wild);add('R · ↩ HUIR',runAway,!battle.wild);
 add('CAMBIAR POKÉMON',()=>battlePicker('switch'));add('MOCHILA · B',()=>battlePicker('bag'));if(!moves.some(m=>ours.pp[m]>0))add('FORCEJEO',()=>attack(9));
}
function multiplier20(t,enemy){const type=SPECIES[enemy.name].type;const chart={Agua:{Fuego:2,Roca:2,Agua:.5,Planta:.5,Dragón:.5},Fuego:{Planta:2,Agua:.5,Fuego:.5,Roca:.5,Dragón:.5},Planta:{Agua:2,Roca:2,Fuego:.5,Planta:.5,Volador:.5,Dragón:.5},Eléctrico:{Agua:2,Volador:2,Planta:.5,Eléctrico:.5,Dragón:.5},Tierra:{Eléctrico:2,Fuego:2,Roca:2,Volador:0,Planta:.5},Roca:{Fuego:2,Volador:2},Volador:{Planta:2,Roca:.5,Eléctrico:.5},Psíquico:{Siniestro:0,Psíquico:.5},Siniestro:{Psíquico:2,Fantasma:2,Siniestro:.5},Normal:{Roca:.5,Fantasma:0},Veneno:{Planta:2,Roca:.5,Fantasma:.5},Dragón:{Dragón:2}};let x=chart[t]?.[type]??1;
 // Secondary typings relevant to the included campaign.
 if(t==='Tierra'&&['Dragonite','Charizard'].includes(enemy.name))x=0;
 if(t==='Agua'&&enemy.name==='Geodude')x=4;
 if(t==='Planta'&&enemy.name==='Geodude')x=4;
 return x;
}
function useMove(att,def,name,isOurs){const m=MOVES[name];if(att.status==='sueño'&&att.sleep>0){att.sleep--;if(att.sleep===0)att.status='';return att.name+' está dormido.'}if(name!=='Forcejeo')att.pp[name]=Math.max(0,att.pp[name]-1);
 if((isOurs?battle.arenaOurs:battle.arenaEnemy)&&Math.random()<.2)return att.name+' no encuentra el objetivo por la arena.';
 if(m.effect==='arena'){if(isOurs)battle.arenaEnemy=true;else battle.arenaOurs=true;return att.name+' levantó arena: precisión reducida durante este combate.'}
 if(m.effect==='toxico'){if((SPECIES[def.name].types||[]).includes('Veneno'))return def.name+' es inmune a Tóxico.';if(def.status)return def.name+' ya tiene un estado alterado.';if(Math.random()>.9)return 'Tóxico falló.';def.status='tóxico';def.toxicCount=0;return att.name+' usó Tóxico. El daño aumentará cada turno.';}
 if(m.effect==='sueño'){if(def.status)return def.name+' ya tiene un estado alterado.';if(Math.random()<.65){def.status='sueño';def.sleep=2;return att.name+' usó Hipnosis. '+def.name+' se durmió.'}return 'Hipnosis falló.'}
 const mult=multiplier(m.type,def),stab=(SPECIES[att.name].types||[SPECIES[att.name].type]).includes(m.type)?1.2:1;const crit=Math.random()<.06?1.5:1;
 const oldHp=def.hp;const dmg=mult===0?0:Math.max(1,Math.round((m.power+SPECIES[att.name].atk*.35+att.lvl*.4)*(.52+Math.random()*.14)*mult*stab*crit));def.hp=Math.max(0,def.hp-dmg);if(m.effect==='veneno'&&mult>0&&Math.random()<.3&&!def.status&&!(SPECIES[def.name].types||[SPECIES[def.name].type]).includes('Veneno')){def.status='veneno'}
 if(m.effect==='drain'&&dmg>0)att.hp=Math.min(att.maxHp,att.hp+Math.max(1,Math.floor(Math.min(dmg,oldHp)/2)));
 pulse(isOurs?'enemyPic':'ourPic');return `${att.name} usó ${name}: −${dmg} PS.${mult>1?' ¡Muy eficaz!':mult===0?' No tiene efecto.':mult<1?' Poco eficaz.':''}${crit>1?' ¡Crítico!':''}`;
}
function poisonTick(p){if(p.hp<=0)return '';let d=0;if(p.status==='veneno')d=Math.max(1,Math.floor(p.maxHp/10));else if(p.status==='tóxico'){p.toxicCount=Math.min(16,(p.toxicCount||0)+1);d=Math.max(1,Math.floor(p.maxHp*p.toxicCount/16))}if(!d)return '';p.hp=Math.max(0,p.hp-d);return ` ${p.name} pierde ${d} PS por ${p.status}.`}
