function battlePicker(mode,forced=false){if(!battle||battle.locked||battle.forced&&!forced)return;const ours=activeMon();const acts=$('battleActions');acts.innerHTML='';const add=(label,fn,off=false)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;b.disabled=off;acts.append(b)};
 if(mode==='switch'){battle.log=forced?'Elige un compañero para continuar.':'Cambiar consume el turno.';state.party.forEach((p,i)=>add(`${p.name} · ${p.hp}/${p.maxHp} PS`,()=>{if(battle.locked)return;const old=activeMon();old.toxicCount=0;old.sleep=old.sleep||0;battle.forced=false;battle.arenaOurs=false;battle.active=i;battle.log='¡Adelante, '+p.name+'!';if(forced){updateBattle();save()}else{battle.locked=true;updateBattle();later(enemyTurn)}},p.hp<=0||i===battle.active));}
 else{battle.log='Usar un objeto consume el turno. Elige objeto y Pokémon.';Object.keys(FRESH_BAG).forEach(item=>add(ITEM_NAMES[item]+' ×'+state.bag[item],()=>{acts.innerHTML='';state.party.forEach((p,i)=>add(p.name+' · '+p.hp+'/'+p.maxHp,()=>{if(!battle||battle.locked)return;if(!useItem(item,i)){battle.log='Ese objeto no ayuda a ese Pokémon.';updateBattle();return}battle.locked=true;updateBattle();later(enemyTurn)}));add('VOLVER',()=>battlePicker('bag'));},state.bag[item]<=0));}
 if(!forced)add('VOLVER AL COMBATE',updateBattle);$('battleText').textContent=battle.log;
}
