LORE_POINTS.gym_nachito=[{id:'lab1',x:5.5,y:10.5,label:'Estación 1 · etiquetas'},{id:'lab2',x:12.5,y:10.5,label:'Estación 2 · estados'},{id:'lab3',x:20.5,y:10.5,label:'Estación 3 · fórmula'}];
CANON_LORE.nachito.futuro='Picassent, prueba de tres estaciones, MT Tóxico y quinta medalla disponibles. Reuniclus sigue reservado al lore.';
function labStation(n,hint=''){const mask=state.flags.labMask||0;
 if(n===1){choiceScreen('Estación 1 · Lee la etiqueta',hint||'Una simulación muestra VENENO. PS bajan al final del turno. Elige el objeto que cura ese estado; no se gastará nada de tu mochila real.',[['Antídoto',()=>{state.flags.labMask=mask|1;save();updateObjective();dialog('nachito',['Correcto. Una Poción recupera PS, pero no elimina el veneno. El Antídoto sí.','La estación de estados está en el centro de la sala.'])}],['Poción',()=>labStation(1,'La barra de PS mejora, pero el icono de veneno sigue ahí. Necesitas tratar el estado.')],['Revivir',()=>labStation(1,'No está debilitado. Lee la etiqueta: VENENO.')]]);return}
 if(n===2){choiceScreen('Estación 2 · Veneno grave',hint||'La simulación marca TÓXICO: el daño crece cada turno (1/16, 2/16, 3/16…). ¿Qué afirmación es correcta?',[
 ['El Antídoto lo cura; cambiar reinicia el contador, pero no cura',()=>{state.flags.labMask=mask|2;save();updateObjective();dialog('nachito',['Exacto. No confundas reiniciar el daño con curar el estado.','Qué maravilla táctica. Ya sé que llevo veinte minutos. Todavía no he llegado a mi parte favorita.'])}],['Cambiar de Pokémon elimina Tóxico para siempre',()=>labStation(2,'El estado viaja con el Pokémon. Cambiar reinicia el contador; necesita un Antídoto o descanso para curarse.')]
 ]);return}
 if((mask&3)!==3){dialog('nachito',['Antes de preparar la fórmula, lee las etiquetas de las estaciones 1 y 2. No hace falta adivinar.']);return}labFormula();}
function labFormula(hint=''){if(state.flags.labReady){dialog('nachito',['La fórmula está controlada. Tu MT Tóxico ya está anotada en Equipo.','El combate del Vesubio te espera en el norte de la sala.']);return}
 const step=state.flags.labStep||0;const symbols=['Hoja','Luna','Estrella'];choiceScreen('La fórmula imposible · '+step+'/3',hint||'El pergamino dice: «La hoja abre el ensayo, la luna lo calma y la estrella lo cierra». Ordena los tres sellos mágicos. Es un experimento de fantasía.',symbols.map((name,i)=>[name,()=>{if(i!==step){state.flags.labStep=0;save();labFormula('El matraz hace «plof». Puedes repetir: Hoja → Luna → Estrella. Las otras estaciones siguen completadas.');return}state.flags.labStep=step+1;save();if(step<2){labFormula();return}state.flags.labMask=7;state.flags.labReady=true;if(!state.flags.toxicTM){state.flags.toxicTM=true;state.bag.antidote+=2;noteQuest('formula')}save();dialog('nachito',['BRASIL nanananananana. ¡La fórmula está completa!','MT Tóxico y dos Antídotos. Puedes enseñar la MT desde Equipo a un Pokémon compatible.','Javi: «Mi camiseta sigue verde». Nachito: «No es humo. Es una hipótesis con demasiada confianza».'],()=>{updateObjective();toast('Laboratorio resuelto · MT Tóxico disponible')})}]))}
const npcTalk20=npcTalk;npcTalk=function(n){if(n.id==='nachitoSchool'){meetFriend('nachito');dialog('nachito',['Bienvenido a mi escuela. Reuniclus es mi compañero elegido en el Libro de Reservas; Jynx es mi alternativa de Kanto. Hoy Drowzee, Electabuzz y Gengar me ayudan en el laboratorio.','Si me dejáis cinco minutos os explico los estados alterados. Marshall: «Has dicho cinco minutos hace veinte».','Entra al laboratorio, junto al estanque. Hay tres estaciones con pistas y puedes resolverlas sin gastar objetos.']);return}if(n.id==='labJavi'){meetFriend(n.who);dialog(n.who,[state.flags.labReady?'La fórmula funciona. Mi camiseta sigue verde, pero eso ya lo arreglaré yo.':'Si vas a ayudar, empieza por leer las etiquetas. Mi camiseta lleva cinco minutos verde.','Para recuperar PS y PP, mi servicio de descanso está fuera, en la plaza.']);return}if(n.id==='fairMarshall'){meetFriend(n.who);if(state.flags.fairDone){dialog(n.who,['Rober tiene la demostración controlada. Yo me quedo con la pizarra.']);return}state.flags.fairAsked=true;save();dialog(n.who,['Nachito busca a alguien que quiera ayudar con la feria. Yo puedo presentar, pero que el control de la demostración lo lleve Rober.','Está junto a la escuela. Pregúntale; nadie tiene que aceptar por obligación.']);return}if(n.id==='fairRober'){meetFriend(n.who);if(!state.flags.fairAsked){dialog(n.who,['Antes de abrir la feria necesitamos saber quién hace qué. Habla con Marshall en la plaza.']);return}if(state.flags.fairDone){dialog(n.who,['La feria está organizada. Los premios ya están entregados.']);return}choiceScreen('Una pareja de equipo para la feria','Rober: «Puedo ayudar con la demostración si Nachito deja las explicaciones en cinco minutos».',[['Proponer el equipo y repartir las tareas',()=>{state.flags.fairDone=true;state.money+=350;noteQuest('feria');save();dialog('rober',['Trato hecho. Yo reviso la demostración, Marshall presenta y Nachito explica. Javi vuelve a la cocina.','+350 monedas por coordinar la feria. Nadie es el premio: el premio es que esto funcione.'])}]]);return}npcTalk20(n)};
const landmark20=landmarkTalk;landmarkTalk=function(p){if(/^lab[123]$/.test(p.id)){labStation(+p.id.slice(3));return}landmark20(p)};
const objective20=updateObjective;updateObjective=function(){objective20();if(state.badges.length===4){const mask=state.flags.labMask||0;$('objective').textContent=state.flags.labReady?'Reta a Nachito en el laboratorio de Picassent':state.scene==='gym_nachito'?`Laboratorio: ${((mask&1)?1:0)+((mask&2)?1:0)}/2 lecciones · prepara la fórmula en la estación 3`:'Desde Sueca, ve al este hacia Picassent · quinta medalla'}};
const step20=handleStep;handleStep=function(){if(state.scene!=='picassent'){step20();return}state.steps++;if(state.steps%6===0)save();if(state.player.x>26&&state.player.y>13&&state.player.y<19&&Math.random()<.09){const list=['Drowzee','Electabuzz','Eevee','Gengar'];startBattle(list[Math.floor(Math.random()*list.length)],24+Math.floor(Math.random()*3),true)}};
const terrain20=terrainRule;terrainRule=function(scene,x,y){if(scene==='picassent'){if(y>=20&&y<=22&&x>2&&x<35)return ['stone',0];if(Math.abs(y-16)<2||Math.abs(x-15)<2&&y>9)return ['path',Math.floor(rand(x,y,9)*4)];if(x>26&&y>13&&y<19)return ['meadow',Math.floor(rand(x,y,5)*4)];return [insideOval(x,y,15,15,7,4)?'plaza':'grass',Math.floor(rand(x,y)*4)]}return terrain20(scene,x,y)};
const collision20=collision;collision=function(x,y){if(state.scene==='picassent'&&y>=20&&y<23&&x>3&&x<35&&!(x>=17&&x<20))return true;return collision20(x,y)};
const props20=drawTownProps;drawTownProps=function(s){if(state.scene!=='picassent'){props20(s);return}for(let x=2;x<37;x+=3){drawTree(x*TILE,2*TILE);drawTree(x*TILE,27*TILE)}for(let y=4;y<25;y+=4){if(y<15||y>19)drawTree(TILE,y*TILE);drawTree(36*TILE,y*TILE)}rect(3*TILE,20*TILE,32*TILE,3*TILE,'#4b9fa6');ctx.fillStyle='#b5e6dc';for(let i=0;i<20;i++){const x=(3+i*1.6)*TILE,y=(20.5+(i%3)*.7)*TILE;ctx.fillRect(x+Math.sin(elapsed*2+i)*8,y,24,3)}rect(17*TILE,20*TILE,3*TILE,3*TILE,'#c49e70');for(let y=20;y<23;y+=.3)rect(17*TILE,y*TILE,3*TILE,3,'#805b48');drawBench(7*TILE,18*TILE);drawBench(22*TILE,16*TILE);for(const x of [7,23])drawLamp(x*TILE,13*TILE);for(let x=27;x<35;x++)for(let y=14;y<19;y++)drawGrass(x*TILE,y*TILE);drawPlanter(22*TILE,8*TILE,2)};
const building20=drawBuilding;drawBuilding=function(b){if(b.type!=='alchemy'){building20(b);return}const x=b.x*TILE,y=b.y*TILE,w=b.w*TILE,h=b.h*TILE;rect(x+8,y+62,w-16,h-60,'#d9e4cb');rect(x,y+20,w,72,'#315f68');for(let i=0;i<6;i++){rect(x+16+i*92,y+34,80,45,'#80c1ba');rect(x+20+i*92,y+38,72,7,'#c8eee1')}for(const xx of [25,w-105]){rect(x+xx,y+132,80,105,'#467e80');rect(x+xx+7,y+139,66,88,'#a5dbbd');rect(x+xx+39,y+137,4,90,'#315f68')}rect(x+w/2-35,y+h-75,70,75,'#254f57');rect(x+w/2-3,y+h-68,6,64,'#eed18b');ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillStyle='#eef8d3';ctx.fillText('ESCUELA DEL ALQUIMISTA',x+w/2,y+116);ctx.textAlign='left';drawMiniBall(x+w/2,y+175)};
const floor20=drawGymFloor;drawGymFloor=function(){if(state.scene!=='gym_nachito'){floor20();return}rect(0,0,26*TILE,2*TILE,'#315b63');ctx.fillStyle='#f0e0a5';ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillText('VESUBIO · LA FÓRMULA IMPOSIBLE',13*TILE,1.3*TILE);ctx.textAlign='left';for(const [i,x] of [5.5,12.5,20.5].entries()){const y=9.5*TILE;rect(x*TILE-65,y-30,130,40,'#916d51');rect(x*TILE-70,y-40,140,14,'#c6b390');const ready=!!((state.flags.labMask||0)&(1<<i));ctx.fillStyle=ready?'#93d596':'#cfc689';ctx.beginPath();ctx.moveTo(x*TILE-9,y-95);ctx.lineTo(x*TILE+9,y-95);ctx.lineTo(x*TILE+9,y-78);ctx.lineTo(x*TILE+24,y-48);ctx.lineTo(x*TILE-24,y-48);ctx.lineTo(x*TILE-9,y-78);ctx.closePath();ctx.fill();ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillStyle='#294f55';ctx.fillText((i+1)+' · '+(ready?'LISTO':['ETIQUETAS','ESTADOS','FÓRMULA'][i]),x*TILE,y+35);ctx.textAlign='left';}if(!state.flags.labReady){ctx.fillStyle='#85bd8755';for(let i=0;i<6;i++){const y=(7.5-(elapsed*.5+i*.4)%3)*TILE;ctx.beginPath();ctx.arc(20.5*TILE+Math.sin(elapsed+i)*25,y,10+i*2,0,Math.PI*2);ctx.fill()}}};
const menu20=openTeam;openTeam=function(){if(['battle','starter','title','dialog'].includes(state.screen))return;menu20();if(state.screen!=='menu'||!state.flags.toxicTM)return;const b=document.createElement('button');b.className='secondary';b.textContent='MT TÓXICO';b.id='toxic21';b.onclick=()=>choiceScreen('MT Tóxico','Compatible con las especies disponibles del equipo. Al enseñarla, equípala desde Movimientos. No se recargan PP al cambiar ataques.',state.party.map(p=>[p.name,()=>{p.tmToxic=true;normalizeMon(p);save();openTeam()}]));modalContent.querySelector('.modal-actions')?.append(b)};
const map20=mapMenu;mapMenu=function(){const towns=[['benifaio','Benifaió',[20,19]],['silla','Silla · Acta',[17,21]],['albal','Albal · Del Mes',[16,15]],['alqueria','L’Alqueria · Calentón',[17,19]],['sueca','Sueca · Kiwi',[17,19]],['picassent','Picassent · Vesubio',[15,13]]];choiceScreen('Mapa de La Previa','Benifaió → norte: Silla. Hacia el este: Albal → L’Alqueria → Sueca → Picassent. Viaja a plazas ya visitadas.',towns.map(([id,name,spawn])=>[name+(state.flags['visited_'+id]||id===state.scene?' · visitado':' · por descubrir'),()=>{if(!state.flags['visited_'+id]&&id!==state.scene){toast('Primero debes llegar caminando.');return}backWorld();changeScene(id,spawn)}]));};


