const character20=drawCharacter;drawCharacter=function(who,x,y,dir,anim=0){if(who!=='nachito'||!['picassent','gym_nachito'].includes(state.scene)){character20(who,x,y,dir,anim);return}const im=asset('nachito_alquimista_atlas21');if(!im.complete||!im.naturalWidth){character20(who,x,y,dir,anim);return}const f=NACHITO_FRAMES21[dir],h=90,w=h*f[2]/f[3];ctx.fillStyle='#244a4459';ctx.beginPath();ctx.ellipse(x,y-5,19,6,0,0,Math.PI*2);ctx.fill();ctx.drawImage(im,...f,x-w/2,y-93+(anim?Math.sin(elapsed*4):0),w,h)};
