function paintPlace23(key,d){const c=$('place23_'+key),im=asset(d.asset);if(!c)return;const render=()=>{if(!im.naturalWidth)return;const g=c.getContext('2d'),[x,y,w,h]=d.rect,scale=Math.min((c.width-12)/w,(c.height-12)/h);g.clearRect(0,0,c.width,c.height);g.imageSmoothingEnabled=false;g.drawImage(im,x,y,w,h,(c.width-w*scale)/2,c.height-6-h*scale,w*scale,h*scale)};if(im.complete)render();else im.addEventListener?.('load',render,{once:true});}
