/* 2.9 · Classic side START menu, evolution ceremony and actual trailing companion. */
const companion29={scene:null,trail:[],x:0,y:0,dir:0,anim:0,lastX:0,lastY:0},COMPANION_GAP29=11;
function resetFollower29(){const p=state.player,offset=[[0,-.82],[.82,0],[-.82,0],[0,.82]][p.dir||0]||[0,-.82];companion29.scene=state.scene;companion29.trail=[];for(let i=0;i<COMPANION_GAP29;i++)companion29.trail.push({x:p.x+offset[0]*(1-i/COMPANION_GAP29),y:p.y+offset[1]*(1-i/COMPANION_GAP29)});companion29.x=p.x+offset[0];companion29.y=p.y+offset[1];companion29.lastX=p.x;companion29.lastY=p.y;companion29.anim=0;companion29.dir=p.dir||0;}
function updateFollower29(dt){if(companion29.scene!==state.scene||!companion29.trail.length)resetFollower29();if(!state.flags.starter||!state.party.length)return;
 const p=state.player,d=Math.hypot(p.x-companion29.lastX,p.y-companion29.lastY);if(d>.075){const pieces=Math.max(1,Math.ceil(d/.10));for(let i=1;i<=pieces;i++)companion29.trail.push({x:companion29.lastX+(p.x-companion29.lastX)*i/pieces,y:companion29.lastY+(p.y-companion29.lastY)*i/pieces});companion29.trail=companion29.trail.slice(-70);companion29.lastX=p.x;companion29.lastY=p.y;}
 const goal=companion29.trail[Math.max(0,companion29.trail.length-COMPANION_GAP29)],dx=goal.x-companion29.x,dy=goal.y-companion29.y,dist=Math.hypot(dx,dy);if(dist>4){resetFollower29();return;}const step=Math.min(dist,dt*4.6);if(dist>.04){companion29.x+=dx/dist*step;companion29.y+=dy/dist*step;companion29.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?2:1):(dy>0?0:3);companion29.anim+=dt*7;}else companion29.anim=0;}
function getFollower29(){if(!state.flags.starter||!state.party.length||state.flags.hideFollower29)return null;if(companion29.scene!==state.scene)resetFollower29();return {...companion29,name:state.party[0].name};}
function markSeen29(name){if(name&&SPECIES[name]&&state.flags.starter)state.flags['seen29_'+name]=true;}
function closeStart29(){if(state.screen!=='start')return;document.getElementById('startMenu29').classList.add('hidden');document.getElementById('startShade29').classList.add('hidden');state.screen='world';heldKeys.clear();resetJoy27();}
function openStart29(){if(state.screen==='start'){closeStart29();return;}if(state.screen!=='world')return;resetJoy27();heldKeys.clear();state.screen='start';const e=$('startMenu29');e.classList.remove('hidden');$('startShade29').classList.remove('hidden');$('startTitle29').textContent=(CHARS[state.player.chosen]?.name||'Entrenador').toUpperCase();$('startBadgeCount29').textContent=state.badges.length+' / 8 MEDALLAS';$('startParty29').textContent=state.party.length+' / 6';$('startMoney29').textContent=state.money+' ₽';const buttons=e.querySelectorAll('[data-start29]');buttons.forEach(x=>x.onclick=()=>startAction29(x.dataset.start29));buttons[0]?.focus?.();}
function startAction29(id){if(state.screen!=='start')return;closeStart29();if(id==='close')return;if(id==='dex')return pokedex29();if(id==='party')return openTeam();if(id==='bag')return bagMenu();if(id==='map')return mapMenu();if(id==='journal'){openTeam();$('journal20')?.click();return;}if(id==='save'){save();toast('¡Partida guardada! Exporta el código antes de cambiar de navegador.');return;}if(id==='options')return options29();}
function pokedex29(){state.screen='menu';const owned=new Set([...state.party,...state.box].map(p=>p.name)),seen=Object.keys(SPECIES).filter(n=>state.flags['seen29_'+n]||owned.has(n));showModal(`<div class="eyebrow">PROFESOR ALFARO · REGISTRO POKÉDEX</div><h2>Pokédex de La Previa</h2><p class="subtle">${owned.size} capturados · ${seen.length} avistados · ${Object.keys(SPECIES).length} especies disponibles. La Pokédex registra nuevos encuentros desde esta edición.</p><div class="pokedex-grid29">${Object.keys(SPECIES).map((n,i)=>`<div class="pokedex-entry29 ${owned.has(n)?'caught29':seen.includes(n)?'seen29':'unknown29'}"><span class="dex-number29">N.º ${String(i+1).padStart(3,'0')}</span><img src="assets/mon22_${n.toLowerCase()}_front.png" alt="${seen.includes(n)?n:'Pokémon desconocido'}"><b>${seen.includes(n)?n:'???'}</b><small>${owned.has(n)?'● Capturado':seen.includes(n)?'◌ Avistado':'Sin descubrir'}</small></div>`).join('')}</div>${buttons('<button id="dexClose29" class="primary">VOLVER AL MAPA</button>')}`);$('dexClose29').onclick=backWorld;}
function options29(){state.screen='menu';showModal(`<div class="eyebrow">CONFIGURACIÓN · LA PREVIA</div><h2>Opciones</h2><p>Personaliza cómo se siente tu aventura.</p><div class="quiz-choices"><button id="optSound29" class="secondary">Sonido: ${audioOn?'activado':'desactivado'}</button><button id="optCompanion29" class="secondary">Pokémon acompañante: ${state.flags.hideFollower29?'oculto':'visible'}</button><button id="optSave29" class="secondary">Guardar ahora</button></div>${buttons('<button id="optClose29" class="primary">VOLVER AL MAPA</button>')}`);$('optSound29').onclick=()=>{audioOn=!audioOn;options29()};$('optCompanion29').onclick=()=>{state.flags.hideFollower29=!state.flags.hideFollower29;resetFollower29();save();options29()};$('optSave29').onclick=()=>{save();toast('Partida guardada.')};$('optClose29').onclick=backWorld;}
let evoContinue29=null,evoToken29=0;
function playEvolutions29(evolutions,onComplete){const token=++evoToken29;let i=0;const layer=$('evolution29');const next=()=>{if(token!==evoToken29)return;if(i>=evolutions.length){layer.className='evolution-layer29 hidden';state.screen='world';evoContinue29=null;onComplete();return;}
 const pair=evolutions[i++];state.screen='evolution';heldKeys.clear();resetJoy27();layer.className='evolution-layer29 evo-intro29';$('evoNameOld29').textContent=pair.old.toUpperCase();$('evoNameNew29').textContent=pair.name.toUpperCase();$('evoOld29').src='assets/mon22_'+pair.old.toLowerCase()+'_front.png';$('evoNew29').src='assets/mon22_'+pair.name.toLowerCase()+'_front.png';$('evoHeading29').textContent='¡¿QUÉ?!';$('evoText29').textContent='Tu '+pair.old+' está evolucionando…';$('evoButton29').classList.add('hidden');$('evoButton29').onclick=null;evoContinue29=null;beep(520,.17);
 setTimeout(()=>{if(token!==evoToken29)return;layer.className='evolution-layer29 evo-charge29';$('evoHeading29').textContent='¡EVOLUCIÓN!';beep(680,.2)},900);
 setTimeout(()=>{if(token!==evoToken29)return;layer.className='evolution-layer29 evo-morph29';beep(860,.24)},2250);
 setTimeout(()=>{if(token!==evoToken29)return;layer.className='evolution-layer29 evo-reveal29';$('evoHeading29').textContent='¡ENHORABUENA!';$('evoText29').textContent='¡'+pair.old+' ha evolucionado a '+pair.name+'!';beep(1046,.32)},3600);
 setTimeout(()=>{if(token!==evoToken29)return;$('evoButton29').classList.remove('hidden');evoContinue29=()=>{evoContinue29=null;next()};$('evoButton29').onclick=()=>evoContinue29?.()},4750);
 };next();}


