function routeNear30(id,x,y,width=2.35){const d=ROUTE_WORLDS30[id];return closeToLine(x,y,d.main,width)||d.branches.some(b=>closeToLine(x,y,b,1.7))||d.clearings.some(([cx,cy,rx,ry])=>insideOval(x,y,cx,cy,rx,ry));}
const originalTerrain30=terrainRule;
terrainRule=function(scene,x,y){
 if(scene==='refugio_ruta')return ['interior_burger',Math.floor(rand(x,y,12)*3)];
 const d=ROUTE_WORLDS30[scene];if(!d)return originalTerrain30(scene,x,y);
 if(scene==='ruta3'&&x>=23&&x<=26&&y>2&&y<27&&!(y>=17&&y<=19))return ['stone',1];
 const walk=routeNear30(scene,x,y),pave=d.clearings.some(([cx,cy,rx,ry])=>insideOval(x,y,cx,cy,rx*.9,ry*.8));
 if(pave)return ['stone',Math.floor(rand(x,y,29)*4)];
 if(walk)return ['route',Math.floor(rand(x,y,39)*5)];
 const v=rand(x,y,19);return [v>.74?'grass':'meadow',Math.floor(rand(x,y,25)*(v>.74?6:5))];
};
for(const id of Object.keys(ROUTE_WORLDS30))delete terrainCache[id];
const originalCollision30=collision;
collision=function(x,y){if(originalCollision30(x,y))return true;
 if(state.scene==='refugio_ruta')return x<1.2||x>15.8||y<2.4||y>11.8;
 if(state.scene==='ruta3'&&x>=23&&x<27&&y>2&&y<27&&!(y>=17&&y<20))return true;
 return false;
};
