function orangeTree30(x,y){drawTree(x,y);for(const [ox,oy] of [[6,-20],[26,-10],[46,-27],[62,-5],[34,-31]]){rect(x+ox,y+oy,7,7,'#ae5826');rect(x+ox+1,y+oy-1,5,6,'#fbb354');rect(x+ox+2,y+oy,2,2,'#ffdc80')}}
function flower30(x,y,t=0){ctx.fillStyle='#3e8258';ctx.fillRect(x-2,y-5,4,11);ctx.fillStyle=t?'#f4cf78':'#f3a6bb';for(const [a,b] of [[-5,-7],[4,-7],[-1,-11],[-1,-3]])ctx.fillRect(x+a,y+b,5,5);ctx.fillStyle='#fff5ca';ctx.fillRect(x-1,y-7,4,4)}
function trailProps30(id){const d=ROUTE_WORLDS30[id],w=SCENES[id].w,h=SCENES[id].h;const isRock=id==='ruta2',isRiver=id==='ruta3',isCoast=id==='ruta4';
 // Tile-aligned outer forest, hills and orchard groves; keep the navigable spline clear.
 for(let y=2;y<h-1;y+=2)for(let x=2;x<w-1;x+=2){const score=rand(x,y,71);if(routeNear30(id,x,y,3.3))continue;if(score>.61&&!(isRock||isCoast))drawTree(x*TILE,y*TILE,2);else if(isRock&&score>.75)orangeTree30(x*TILE,y*TILE);else if(isRock&&score>.59)boulder30((x+.5)*TILE,(y+.7)*TILE,.95);else if(score>.75&&isCoast)drawBush(x*TILE,y*TILE);}
 // Sightlines, local character and optional gathering areas.
 if(id==='ruta'){
   drawSign(3*TILE,14*TILE,'BENI ←');drawSign(39*TILE,14*TILE,'ALBAL →');
   drawPond09(19*TILE,4*TILE);drawFenceH(19*TILE,4*TILE,3);
   drawBench(14*TILE,8*TILE);drawLamp(15*TILE,7*TILE);drawBench(30*TILE,19*TILE);
   drawSign(26*TILE,8.2*TILE,'REFUGI');
   drawFenceH(8*TILE,18*TILE,3);drawPlanter(8*TILE,18*TILE,2);
 }else if(isRock){
   drawSign(3*TILE,16*TILE,'ALBAL ←');drawSign(44*TILE,16*TILE,'PISTA →');
   for(const [x,y] of [[17,4],[29,4],[34,7],[37,20],[5,23]])boulder30(x*TILE,y*TILE,1.45);
   drawBench(29*TILE,22*TILE);drawFenceH(28*TILE,23*TILE,3);
   for(let x=10;x<17;x+=2)orangeTree30(x*TILE,4*TILE);
 }else if(isRiver){
   for(let y=2;y<27;y++){if(y>=17&&y<20)continue;for(let x=23;x<27;x++){rect(x*TILE,y*TILE,TILE,TILE,((x+y)%2)?'#54a7a8':'#49969e');rect(x*TILE+6,y*TILE+Math.sin(elapsed*2+y)*4,29,3,'#9ee0ce')}}
   rect(23*TILE,17*TILE,4*TILE,3*TILE,'#996e4e');for(let y=17;y<20;y++)rect(23*TILE,y*TILE+18,4*TILE,5,'#d4ab71');
   drawSign(3*TILE,16*TILE,'L’ALQ ←');drawSign(44*TILE,16*TILE,'SUECA →');drawBench(18*TILE,22*TILE);drawFenceH(19*TILE,15*TILE,3);
 }else if(isCoast){
   for(let x=3;x<48;x++){if(x>15&&x<23){for(let y=26;y<29;y++)rect(x*TILE,y*TILE,TILE,TILE,'#e8cfa1');}else for(let y=26;y<29;y++){rect(x*TILE,y*TILE,TILE,TILE,(x+y)%3?'#5ca9ad':'#60b6b6');rect(x*TILE+8,y*TILE+12,22,3,'#c6e6cf')}}
   drawSign(3*TILE,16*TILE,'SUECA ←');drawSign(47*TILE,16*TILE,'PICAS →');drawBench(18*TILE,22*TILE);
   drawFenceH(16*TILE,24*TILE,4);
 }
 for(let i=0;i<60;i++){const x=2+Math.floor(rand(i,5,86)*(w-4)),y=2+Math.floor(rand(i,9,94)*(h-4));if(!routeNear30(id,x,y,1.6)&&!(isRiver&&x>=23&&x<=26)&&rand(i,14,74)>.38)flower30((x+.3)*TILE,(y+.64)*TILE,i%2)}
}
const previousProps30=drawTownProps;
