 const x=Math.floor(state.player.x),y=Math.floor(state.player.y),name=state.scene;
 if(!routeNear30(name,x,y,1.5)&&Math.random()<.095){const list=name==='ruta2'?['Geodude','Eevee','Pidgey']:name==='ruta3'?['Psyduck','Bulbasaur','Rattata']:name==='ruta4'?['Slowbro','Electabuzz','Pidgey']:['Pidgey','Rattata'];startBattle(list[Math.floor(Math.random()*list.length)],name==='ruta2'?11:name==='ruta3'?16:name==='ruta4'?21:4,true)}
