const beforeLandmark31=landmarkTalk;
landmarkTalk=function(p){
 if(p.id==='caveHint31'){dialog(null,['El altar tiene un mensaje: «Primero fluye el río, después brilla el sol y al final crece el árbol».','Pulsa las tres piedras en ese orden. Puedes volver a probar si te equivocas.']);return;}
 const order=['runeB31','runeA31','runeC31'];if(order.includes(p.id)){
  if(state.flags.puzzle31_done){dialog(null,['Las tres piedras brillan con una luz dorada. El secreto de la cueva ya es tuyo.']);return;}
  const stage=state.flags.runeStep31||0;
  if(p.id!==order[stage]){state.flags.runeStep31=0;save();dialog(null,['La piedra se ilumina y se apaga. El mecanismo vuelve a empezar.','La inscripción habla del río, del sol y del árbol.']);return;}
  state.flags.runeStep31=stage+1;
  if(stage===2){state.flags.puzzle31_done=true;normalizeExtras();state.balls+=3;state.bag.potion+=1;noteQuest('cueva31');save();dialog(null,['¡Las tres piedras resuenan! Un compartimento secreto se abre en la roca.','Has encontrado 3 Poké Balls y una poción. ¡La exploración ha tenido premio!']);}
  else{save();dialog(null,[stage===0?'La piedra del río desprende una luz azul. 1 / 3.':'La piedra del sol brilla con fuerza. 2 / 3.','Sigue el orden que marca la inscripción.']);}return;
 }
 if(p.id==='cabinBook31'){dialog(null,['Cuaderno de excursiones de Raquel: «No todos los caminos se hicieron para llegar rápido».','Pasa la página: hay un dibujo del puente del río y otro de una cueva de naranjos.']);return;}
 if(p.id==='marjalPostcard31'){if(!state.flags.marjalPostcard31){state.flags.marjalPostcard31=true;state.money+=150;save();dialog(null,['Un pequeño mirador se abre entre juncos. Las garzas levantan el vuelo sobre el agua.','Encuentras 150 ₽ junto a una postal escrita por Óscar.']);}else dialog(null,['La marjal está tranquila. Se oyen aves entre los juncos.']);return;}
 const isAlbum=ALBUM_STOPS31.some(a=>a.id===p.id);
 if(isAlbum)markAlbum31(p.id);
 return beforeLandmark31(p);
};
