 const links=REGION_EDGES31.map(([a,b])=>{const v=REGION_NODES31.find(n=>n.id===a),w=REGION_NODES31.find(n=>n.id===b);return `<path d="M${v.x} ${v.y} L${w.x} ${w.y}" stroke="#a7c1aa" stroke-width="13" stroke-linecap="round" stroke-dasharray="16 12"/>`}).join('');
 const bubbles=REGION_NODES31.map(n=>`<g transform="translate(${n.x},${n.y})"><circle r="${n.id===current?23:n.spawn?18:14}" stroke="${n.id===current?'#ffe69a':'#f2efcd'}" stroke-width="5" fill="${n.id===current?'#e29a60':n.spawn?'#5b9a91':'#9ab39d'}"/><text y="${n.y<95?-27:38}" text-anchor="middle" fill="#f7f2da" font-size="19" font-weight="900" stroke="#183b36" stroke-width="5" paint-order="stroke">${n.label}</text>${n.id===current?'<text y="6" text-anchor="middle" fill="#fff3ce" font-size="19">★</text>':''}</g>`).join('');
