function drawRouteMinimap31(){const route=ROUTE_WORLDS30[state.scene];if(!route||!minimapVisible31||state.screen!=='world')return;
 const mx=W-191,my=66,mw=180,mh=118;ctx.save();ctx.fillStyle='#153d3acc';ctx.fillRect(mx,my,mw,mh);
 ctx.strokeStyle='#f3d995';ctx.lineWidth=2;ctx.strokeRect(mx+1,my+1,mw-2,mh-2);
 ctx.textAlign='left';ctx.font='bold 11px monospace';ctx.fillStyle='#f8e8bf';ctx.fillText('RUTA · MAPA LOCAL',mx+9,my+15);
 const off=mx+11,top=my+27,sx=(mw-22)/(route.w-1),sy=(mh-39)/(route.h-1);
 ctx.lineCap='round';for(const path of [route.main,...route.branches]){ctx.beginPath();path.forEach(([x,y],i)=>i?ctx.lineTo(off+x*sx,top+y*sy):ctx.moveTo(off+x*sx,top+y*sy));ctx.strokeStyle=path===route.main?'#e7dfaa':'#adbca4';ctx.lineWidth=path===route.main?5:3;ctx.stroke()}
 for(const po of PORTALS[state.scene]||[]){if(!['cova31','caseta31'].includes(po.to))continue;ctx.fillStyle='#efc567';ctx.fillRect(off+po.x*sx-3,top+po.y*sy-3,6,6)}
 const px=off+state.player.x*sx,py=top+state.player.y*sy;ctx.fillStyle='#fff1b5';ctx.beginPath();ctx.arc(px,py,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b55941';ctx.lineWidth=2;ctx.stroke();ctx.restore();}
const beforeRender31=renderWorld;
renderWorld=function(){beforeRender31();drawRouteMinimap31()};
