getSceneNpcs=function(scene=state.scene){const npcs=originalVillageNpc32(scene);if(!['benifaio','albal','silla','alqueria','sueca'].includes(scene))return npcs;
 return npcs.map(n=>{const p=PATROLS32[n.id];if(!p)return n;const seed=n.x*.79+n.y*.32,m=elapsed*p[2]+seed;
 const vx=Math.sin(m)*p[0],vy=Math.cos(m*.8)*p[1];
 return {...n,x:n.x+vx,y:n.y+vy,walkAnim32:Math.abs(Math.cos(m))>.18?elapsed*7:0,dir32:Math.cos(m)*p[0]<0?1:2};});
};
