function drawVillageRoom32(r){const w=r.w*TILE,h=r.h*TILE;
 const palette={home:['#815a4f','#eed6a8','#f2e2bc'],store:['#4a7b74','#e7e5c9','#f2edd9'],office:['#637b7b','#c5d9c9','#e8ebd8'],workshop:['#51666b','#bdc3b8','#d8d4bc'],library:['#735e77','#ddcbaa','#f2e4bf']}[r.kind];
 rect(0,0,w,h,palette[0]);rect(TILE,2*TILE,(r.w-2)*TILE,10*TILE,palette[1]);
 for(let y=3;y<12;y++)for(let x=2;x<15;x++)if((x+y)%2)rect(x*TILE,y*TILE,TILE,TILE,palette[2]);
 rect(TILE,1*TILE,15*TILE,2*TILE,palette[0]);rect(TILE,3*TILE,15*TILE,11,'#f5d29a');
 // windows and wall art
 for(const x of [2,13]){rect(x*TILE,2.1*TILE,2*TILE,1.15*TILE,'#a5c9d0');rect((x+.9)*TILE,2.1*TILE,8,56,'#f5e2aa');rect(x*TILE,2.66*TILE,2*TILE,7,'#f5e2aa');}
 rect(8*TILE,11*TILE,2*TILE,17,'#896247');drawSign(7.6*TILE,10*TILE,'SALIDA');
 const props={home:[['table',4,7],['bench',3,9],['bench',12,9],['ball',13,6]],store:[['shelf',2,4],['shelf',12,4],['counter',6,6],['ball',13,8]],office:[['counter',6,6],['shelf',2,4],['papers',12,7]],workshop:[['counter',6,6],['shelf',2,4],['tools',12,7]],library:[['shelf',2,4],['shelf',12,4],['table',5,8],['papers',11,8]]}[r.kind];
 for(const [type,x,y] of props){let xx=x*TILE,yy=y*TILE;if(type==='table')drawTable(xx,yy);else if(type==='bench')drawBench(xx,yy);else if(type==='ball')drawMiniBall(xx,yy);else if(type==='shelf'){rect(xx,yy,2*TILE,3*TILE,'#735742');for(let k=0;k<3;k++){rect(xx+8,yy+k*TILE+7,2*TILE-16,8,'#d4aa68');for(let j=0;j<4;j++)rect(xx+10+j*19,yy+k*TILE+14,12,27,['#8b5e8d','#8aaa85','#dd936f','#6f9dba'][(j+k)%4]);}}else if(type==='counter'){rect(xx,yy,5*TILE,1.1*TILE,'#856548');rect(xx,yy,5*TILE,13,'#f2d7a0')}else if(type==='papers'){rect(xx,yy,70,48,'#f0e4c4');rect(xx+8,yy+11,52,4,'#4b787e');rect(xx+8,yy+23,42,4,'#4b787e');}else if(type==='tools'){rect(xx,yy,76,38,'#536b70');rect(xx+9,yy+7,58,8,'#e5c77b');}}
 // Entrance is directly on the player-accessible floor; no obstructing furniture.
 ctx.textAlign='center';ctx.fillStyle='#fbefcf';ctx.font='bold 14px monospace';ctx.fillText(r.kind==='store'?'TIENDA':r.kind==='library'?'ARCHIVO':r.kind==='workshop'?'TALLER':r.kind==='office'?'REGISTRO':'LA PREVIA',8.5*TILE,1.9*TILE);ctx.textAlign='left';
}
