 const logo=asset('vinted33_badge');if(logo.complete&&logo.naturalWidth)ctx.drawImage(logo,7.1*TILE,1.47*TILE,44,44);
 rect(5.6*TILE,1.37*TILE,5.8*TILE,39,'#078d91');ctx.fillStyle='#ffffff';ctx.textAlign='center';ctx.font='bold 20px sans-serif';ctx.fillText('vinted',8.5*TILE,1.94*TILE);ctx.textAlign='left';
 // second-hand racks, hangers, mirrors, cardboard parcels
