 if(effect==='percent'||effect==='reveal')return '<div class="cine-bigprop34">−5 %</div>';
 if(effect==='basket'||effect==='tactics'||effect==='board')return '<div class="cine-board34"><i>○ ↗ ○</i><i>↑ 42 QUICK ↘</i><i>○ → ●</i></div>';
 if(effect==='epitaph')return '<div class="cine-gravestone34">RESTING<br>PISSED<br><small>BORJA FIESTAS</small></div>';
