 return `<div class="cine-actor34"><img src="${cineSprite34(who)}" alt="Sprite de ${getProfile(who).name}" onerror="this.style.display='none'"><span>${getProfile(who).name}</span></div>`+more.map(x=>`<div class="cine-sideactor34"><img src="${cineSprite34(x)}" alt="${getProfile(x).name}"></div>`).join('');
