function learnsetMoves35(p){const list=LEARNSETS35[p.name]||[];return [...new Set(list.filter(([l])=>l<=p.lvl).map(([,m])=>m))];}
const oldAvailable35=availableMoves;
availableMoves=function(p){return [...new Set([...oldAvailable35(p),...learnsetMoves35(p)])]};
const oldCreate35=createMon;
createMon=function(name,lvl){const p=oldCreate35(name,lvl),list=learnsetMoves35(p);if(list.length){p.moves=list.slice(-4);for(const m of list)if(!Number.isFinite(p.pp[m]))p.pp[m]=MOVES[m].pp;}return p;};
function learnLevel35(p,level,events=[]){
 const table=LEARNSETS35[p.name]||[];
 for(const [when,move] of table){if(when!==level||p.moves.includes(move))continue;
  if(!Number.isFinite(p.pp[move]))p.pp[move]=MOVES[move].pp;
  if(p.moves.length>=4){const forgotten=p.moves.shift();events.push(`${p.name} olvidó ${forgotten}…`);}
  p.moves.push(move);events.push(`¡${p.name} aprendió ${move} al nivel ${level}!`);
 }
 return p;
}
