  if(!t)continue;b.classList.add('move-button41');b.style.setProperty('--move-color41',BATTLE_TYPES41[t]||'#e4ddc9');b.setAttribute('aria-label',`${move}, tipo ${t}, ${label.split(' · ').at(-1)}`);
