// Prefer meaningful attacks without giving opponents perfect knowledge or unfair statistics.
function chooseEnemyMove41(enemy,ours,options){if(!options.length)return 'Forcejeo';
 const scored=options.map(m=>{const def=MOVES[m];if(!def)return {m,score:0};const damage=(def.power||0)*multiplier(def.type,ours);
 let score=damage+Math.random()*8;if(def.effect==='sueño'&&!ours.status)score=18+Math.random()*7;
 if(def.effect==='toxico'&&!ours.status)score=15+Math.random()*7;
 if((def.effect==='sueño'||def.effect==='toxico')&&ours.status)score=-10;
 if(def.effect==='arena')score=enemy.hp>enemy.maxHp*.65?11:-4;
 return {m,score};});
 scored.sort((a,b)=>b.score-a.score);return scored[0].m;
}
