 for(const o of room.props)if(['computer','dex','tubes','machine'].includes(o.type)){let x=o.x*24+4,y=o.y*24+o.h*24-4;px50(x,y,2,2,Math.sin(elapsed*3+o.x)>0?'#c5eda1':'#619d8a')}
