function unstick50(){if(!ROOMS50[state.scene]||!collision(state.player.x,state.player.y))return false;let p=state.player;for(let r=.5;r<18;r+=.5)for(let a=0;a<24;a++){let x=p.x+Math.cos(a*Math.PI/12)*r,y=p.y+Math.sin(a*Math.PI/12)*r;if(!collision(x,y)){p.x=x;p.y=y;resetFollower29();return true}}p.x=8.5;p.y=11.5;return true}
