const getSceneNpcsBefore57=getSceneNpcs;
getSceneNpcs=function(scene=state.scene){
 const npcs=getSceneNpcsBefore57(scene);
 if(scene!=='albal')return npcs;
 return npcs.map(n=>{
  if(n.id!=='patri56')return n;
  const t=Math.max(0,Number.isFinite(elapsed)?elapsed*.85:0);
  const route=[[18,18],[21,17.2],[23,19.1],[20,20.2],[17.4,19.1]];
  const idx=Math.floor(t)%route.length,next=(idx+1)%route.length;
  const frac=t-Math.floor(t),ax=route[idx][0],ay=route[idx][1],bx=route[next][0],by=route[next][1];
  const x=ax+(bx-ax)*frac,y=ay+(by-ay)*frac;
  const dir=Math.abs(bx-ax)>Math.abs(by-ay)?(bx>ax?2:1):(by>ay?0:3);
  return {...n,x,y,walkAnim32:elapsed*10,dir32:dir};
 });
};

