 for(let i=0;i<22;i++){const x=(i*73+elapsed*38)% (W+120)-60; const y=H*.46+Math.sin(elapsed*1.3+i)*90; const r=30+((i*17)%55); ctx.fillStyle=i%2?'rgba(245,245,235,.20)':'rgba(160,235,255,.16)'; ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill();}
 ctx.restore();
 // scanlines and haze
