 ctx.restore();
 // intermittent blur flash across whole picture
 if(blurPulse>.74){ctx.save();ctx.globalAlpha=.11;ctx.filter='blur(8px)';ctx.drawImage(canvas,0,0);ctx.restore();}
 // speed streaks
 ctx.strokeStyle='rgba(255,255,245,.10)'; ctx.lineWidth=2; for(let i=0;i<16;i++){const y=(i*41+elapsed*480)%H; ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y-12-Math.sin(elapsed*4+i)*7); ctx.stroke();}
 // subtitles/video overlay
