const DEX69=KANTO69.pokemon, BY69=Object.fromEntries(DEX69.map(p=>[p.name,p])), ID69=Object.fromEntries(DEX69.map(p=>[p.id,p]));
const MOVE69=Object.fromEntries(KANTO69.moves.map(m=>[m.name,m])), MID69=Object.fromEntries(KANTO69.moves.map(m=>[m.id,m]));
