const PARENTS69={};for(const p of DEX69)for(const e of p.evolutions)PARENTS69[e.to]=p.name;
// Assign in national order so old galleries and other readers also get correct numbering.
for(const key of Object.keys(SPECIES))delete SPECIES[key];
