function sillaPresentacion520(){
 let idx=0;state.screen='dialog';
 const finish=()=>{backWorld();sillaAdvance520(4);state.flags.sillaReady520=true;noteQuest('sillaFranquicia520');save();toast('¡Se abre el gimnasio de Sergio!');};
 const render=()=>{
  const b=CINE522_BEATS[idx],act=b.act;
  const speaker=b.who==='pantalla'?'PANTALLA DE FICHAJES':b.who==='narrador'?'NARRADOR':(b.who==='jl'?'JOSÉ LÁZARO':getProfile(b.who).name.toUpperCase());
  const actors=['awelo','sergio','jl','cristian','frank'].map((who,k)=>{
   const f=who==='sergio'?'character_sergio':who==='awelo'?'character_awelo':'character_'+who+'_520';
   const cl=(who===b.who?'active':'')+(act==='quarrel'&&['jl','cristian'].includes(who)?' arguing':'')+(act==='leave'&&who==='sergio'?' exiting':'');
   return `<div class="pc522-person pc522-${who} ${cl}" style="--k:${k}"><div class="pc522-personsprite" style="background-image:url('${media22(f+'.png')}')"></div><span>${who==='jl'?'JL':who.toUpperCase()}</span></div>`;
  }).join('');
  const result=(act==='fail'||['explode','excuse','quarrel','frank','leave','ending'].includes(act));
  const screen=result?'<b>✖ FICHAJE RECHAZADO</b><small>PELLE NO HA ACEPTADO LA OFERTA</small>':'<b>PELLE</b><small>FICHAJE DEL SIGLO</small>';
  showModal(`<div class="pc522-meta">SILLA · CAPÍTULO I <span>${idx+1} / ${CINE522_BEATS.length}</span></div><h2 class="pc522-heading">LA FRANQUICIA DE LOS INÚTILES</h2>
   <div class="pc522-screenplay ${act}"><div class="pc522-roof">PRESENTACIÓN OFICIAL C.B. SILLA</div><div class="pc522-stands"><i></i><i></i><i></i><i></i><i></i></div><div class="pc522-display ${result?'rejected':''}">${screen}</div><div class="pc522-dais"></div><div class="pc522-people">${actors}</div><div class="pc522-lights"></div>${act==='explode'?'<div class="pc522-smoke">💢</div>':''}</div>
   <div class="pc522-dialog"><b>${speaker}</b><p>${b.line}</p></div>${buttons(`<button class="primary" id="nextDialog">${idx===CINE522_BEATS.length-1?'ABRIR EL GIMNASIO':'SIGUIENTE →'}</button><button class="secondary" id="sillaSkip520">SALTAR ESCENA</button>`)}`,'dialog');
  $('nextDialog').onclick=()=>{if(!dialogCanAdvance())return;if(++idx>=CINE522_BEATS.length)finish();else render();};
  $('sillaSkip520').onclick=()=>{if(!dialogCanAdvance())return;finish();};
 };
 render();
}
