winBattle=function(){
 if(battle&&battle.trainerId?.startsWith('bd524:')){
  const who=battle.trainerId.slice(6),t=BD524_TRAINERS[who];
  if(t&&!state.flags[t.flag]){
   state.flags[t.flag]=true;state.money+=t.reward;noteQuest('npc524_bd');
   if(Object.values(BD524_TRAINERS).every(a=>state.flags[a.flag])){
    if(!state.flags.npc524_threeDone){state.flags.npc524_threeDone=true;state.balls+=3;noteQuest('npc524_all');}
   }
  }
  // Guard against legacy battle logic that awards the Blas flag on any trainer victory.
  battle.wild=true;
 }
 return bd524PrevWin();
};
// Animate 5.23 friends and 5.24 players on their standing patrols with four-frame feet and body motion.
const bd524PrevDraw=drawCharacter;
drawCharacter=function(who,x,y,dir=0,anim=0){
 if(NPC524_IDS.includes(who)){
  // Change stance briefly, without altering collision or actual map positions.
  const phase=Math.floor(elapsed*2.2+(who.length*0.83))%8;
  const f=(phase<=3)?phase:0;
  return bd524PrevDraw(who,x,y,dir,f||anim);
 }
 return bd524PrevDraw(who,x,y,dir,anim);
};
let bd524Alert=null,bd524LastTrigger=-100;
function bd524CanSpot(t){
 if(state.screen!=='world'||elapsed-bd524LastTrigger<4||state.flags[t.flag]||!state.flags.starter||!state.party.some(p=>p.hp>0))return false;
 const n=SCENES[t.scene].npcs.find(n=>n.id==='npc524_'+t.who);
 if(!n||state.scene!==t.scene)return false;
 // Orthogonal line-of-sight, standard Pokémon trainer mechanic.
 const px=state.player.x,py=state.player.y,nx=n.x+.5,ny=n.y+.5;
 const dx=px-nx,dy=py-ny,dist=Math.hypot(dx,dy);
 if(dist<1.45||dist>3.3)return false;
 if(Math.min(Math.abs(dx),Math.abs(dy))>.45)return false;
 // Don't see through walls.
 for(let f=.75;f<dist-.70;f+=.45){let tx=nx+dx*f/dist,ty=ny+dy*f/dist;if(collision(tx,ty))return false;}
 return n;
}
const BD524_SIGHT=[{who:'bd_32',scene:'ruta2',...BD524_TRAINERS.bd_32},{who:'bd_97',scene:'alqueria',...BD524_TRAINERS.bd_97},{who:'bd_24',scene:'alqueria',...BD524_TRAINERS.bd_24}];
const bd524PrevUpdate=update;
update=function(dt){
 if(bd524Alert){
  elapsed+=dt;bd524Alert.age+=dt;
  const a=bd524Alert,n=a.n;
  if(a.age>.35&&a.age<1.10){
   const px=state.player.x,py=state.player.y,dx=px-n.x-.5,dy=py-n.y-.5,dist=Math.hypot(dx,dy);
   if(dist>1.55){const step=Math.min(dt*2,dist-1.55);n.x+=dx/dist*step;n.y+=dy/dist*step;n.walkAnim32=(n.walkAnim32||0)+dt*8;}
  }
  if(a.age>1.16){
   bd524Alert=null;state.screen='world';
   dialog(a.t.who,a.t.pre,()=>{backWorld();startBattle(a.t.mon,a.t.level,false,'bd524:'+a.t.who)});
  }
  return;
 }
 bd524PrevUpdate(dt);
 if(state.screen!=='world')return;
 for(const t of BD524_SIGHT){const n=bd524CanSpot(t);
  if(n){bd524LastTrigger=elapsed;state.screen='bdAlert524';bd524Alert={n,t,age:0};heldKeys.clear();joystick.x=joystick.y=0;break;}
 }
};
const bd524PrevRender=renderWorld;
renderWorld=function(){
 bd524PrevRender();
 if(bd524Alert&&state.scene===bd524Alert.t.scene){
  const sc=SCENES[state.scene],cx=clamp(camera.x,0,Math.max(0,sc.w*TILE-W)),cy=sc.h*TILE<H?(sc.h*TILE-H)/2:clamp(camera.y,0,Math.max(0,sc.h*TILE-H));
  const n=bd524Alert.n,x=(n.x+.5)*TILE-cx,y=(n.y+.5)*TILE-cy-110-Math.sin(elapsed*9)*4;
  ctx.fillStyle='#fff9d1';ctx.fillRect(x-14,y-22,28,28);ctx.strokeStyle='#bc4938';ctx.lineWidth=2;ctx.strokeRect(x-14,y-22,28,28);
  ctx.font='bold 26px monospace';ctx.textAlign='center';ctx.fillStyle='#dc3430';ctx.fillText('!',x,y+1);ctx.textAlign='left';
 }
};
