function npc525CanMove(p,tx,ty){
 const scene=SCENES[p.scene];if(!scene||state.scene!==p.scene)return false;
 if(tx<2||ty<3||tx>=scene.w-2||ty>=scene.h-2)return false;
 if(Math.abs(tx-p.originX)>p.radius||Math.abs(ty-p.originY)>p.radius)return false;
 if(Math.hypot(state.player.x-(tx+.5),state.player.y-(ty+.5))<2.5)return false;
 // Collision already checks scenery, other NPCs, route boundaries and buildings.
 if(collision(tx+.5,ty+.5))return false;
 for(const portal of PORTALS[p.scene]||[])if(Math.hypot(portal.x-(tx+.5),portal.y-(ty+.5))<2.3)return false;
 return true;
}
function npc525UpdatePatrols(dt){
 if(state.screen!=='world')return;
 for(const p of npc525Patrols){if(p.scene!==state.scene)continue;
  const n=p.n;
  if(p.trip){
   p.step=Math.min(1,p.step+dt*2.0);
   const eased=p.step*p.step*(3-2*p.step);
   n.x=p.trip.x0+(p.trip.x1-p.trip.x0)*eased;
   n.y=p.trip.y0+(p.trip.y1-p.trip.y0)*eased;
   n.walkAnim32+=dt*8;
   if(p.step>=1){n.x=p.trip.x1;n.y=p.trip.y1;p.trip=null;p.clock=p.pause+(p.radius*.17);}
   continue;
  }
  // NPCs stop to talk when the player is close. Never wander off during a dialogue.
  if(Math.hypot(state.player.x-n.x-.5,state.player.y-n.y-.5)<3){p.clock=Math.max(p.clock,.6);continue;}
  p.clock-=dt;if(p.clock>0)continue;
  const x=Math.round(n.x),y=Math.round(n.y);
  const dirs=[[1,0,2],[-1,0,1],[0,1,0],[0,-1,3]];
  const offset=Math.floor(rand(x,y,Math.floor(elapsed/7)+p.originX)*4);
  const ordered=[...dirs.slice(offset),...dirs.slice(0,offset)];
  const chosen=ordered.find(([dx,dy])=>npc525CanMove(p,x+dx,y+dy));
  if(!chosen){p.clock=1.4;continue;}
  p.trip={x0:n.x,y0:n.y,x1:x+chosen[0],y1:y+chosen[1]};
  p.step=0;n.dir32=chosen[2];
 }
}
