function npc525ContextLine(id,tick,lines){
 if(id==='npc523_calomarde523_silla'&&state.badges?.includes(0))return '¡A Sergio le has ganado tú!';
 if(id==='sillaFrank520'&&state.badges?.includes(1))return '¡Ya has conocido a Blas!';
 if(id==='npc523_uki523_alqueria'&&state.badges?.includes(2))return '¡Plata por fin se ha calmado!';
 if(id==='npc524_bd_09'&&state.flags.npc524_threeDone)return '¡Nos has barrido a los tres!';
 if(id==='npc523_kun523_sueca'&&state.badges?.includes(3))return '¡Ahora me llaman el Awelo campeón!';
 return lines[tick%lines.length];
}
function npc525BubbleAt(n,txt,cx,cy,color='#eef8eb'){
 if(!n||!txt)return;
 const x=(n.x+.5)*TILE-cx,y=(n.y+.5)*TILE-cy-118;
 if(x<-130||x>W+130||y<-80||y>H+40)return;
 ctx.save();ctx.font='bold 12px monospace';ctx.textAlign='center';
 const shown=txt.length>34?txt.slice(0,32)+'…':txt;
 const w=Math.min(260,Math.max(94,ctx.measureText(shown).width+18));
 ctx.fillStyle='#142d37e8';ctx.fillRect(x-w/2-2,y-21,w+4,26);
 ctx.fillStyle=color;ctx.fillRect(x-w/2,y-19,w,22);
 ctx.fillStyle='#102d34';ctx.fillText(shown,x,y-4);
 ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x-6,y+3);ctx.lineTo(x,y+12);ctx.lineTo(x+6,y+3);ctx.fill();
 ctx.restore();
}
function npc525AmbientOverlays(){
 if(state.screen!=='world')return;
 const scene=SCENES[state.scene],cx=clamp(camera.x,0,Math.max(0,scene.w*TILE-W)),cy=scene.h*TILE<H?(scene.h*TILE-H)/2:clamp(camera.y,0,Math.max(0,scene.h*TILE-H));
 const tick=Math.floor(elapsed/3.8),allNpcs=getSceneNpcs();
 // One small exchange at most, if two NPCs are truly close enough to converse.
 let chatting=false;
 for(const c of NPC525_BANTER){if(c.scene!==state.scene)continue;
  const a=allNpcs.find(n=>n.id===c.a),b=allNpcs.find(n=>n.id===c.b);
  if(!a||!b||Math.hypot(a.x-b.x,a.y-b.y)>9)continue;
  if(Math.min(Math.hypot(a.x+.5-state.player.x,a.y+.5-state.player.y),Math.hypot(b.x+.5-state.player.x,b.y+.5-state.player.y))>6)continue;
  npc525BubbleAt(tick%2===0?a:b,c.lines[tick%c.lines.length],cx,cy,'#fff1ca');chatting=true;break;
 }
 if(!chatting){
  for(const [id,lines] of Object.entries(NPC525_MONOLOGUES)){
   const n=allNpcs.find(x=>x.id===id);
   if(!n||Math.hypot(n.x+.5-state.player.x,n.y+.5-state.player.y)>4.5)continue;
   // One ambient line every several seconds; no toast or dialogue modal.
   if((tick+id.length)%3!==0)continue;
   npc525BubbleAt(n,npc525ContextLine(id,tick,lines),cx,cy);break;
  }
 }
 // Sparks of life along the trails: no obstacles, animations or asset allocations.
 if(!['ruta','ruta2','ruta3','ruta4','alqueria','silla','albal','sueca'].includes(state.scene))return;
 ctx.save();ctx.globalAlpha=.7;
 for(let i=0;i<7;i++){
  const px=(i*347+76+Math.sin(elapsed*.65+i)*22)%(scene.w*TILE),py=(i*163+91+Math.sin(elapsed*1.15+i*1.8)*15)%(scene.h*TILE);
  const sx=px-cx,sy=py-cy;if(sx<0||sy<0||sx>W||sy>H)continue;
  ctx.fillStyle=i%3?'#f3df85':'#d7f1e5';ctx.fillRect(sx,sy,3+(i%2),2);
 }
 ctx.restore();
}
