function burger528DrawActor(c,who,x,y,dir,step,scale=1){
 const img=sprite(who);if(!img.complete||!img.naturalWidth)return;
 const hi=HI_RES_CHARACTERS.has(who),fw=hi?64:32,fh=hi?96:48;
 // A small stepping cycle and an expressive bob, without stretching the atlases.
 c.imageSmoothingEnabled=false;
 const col=[0,1,0,3][Math.floor(step)%4],row=dir;
 const w=64*scale,h=96*scale;
 c.fillStyle='#15292d77';c.beginPath();c.ellipse(x,y,20,5,0,0,Math.PI*2);c.fill();
 c.drawImage(img,col*fw,row*fh,fw,fh,x-w/2,y-h,w,h);
}
function burger528DrawFilm(canvas,index,clock){
 const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;
 const backdrop=asset('burger_cine_528');
 if(backdrop.complete&&backdrop.naturalWidth)c.drawImage(backdrop,0,0,640,300);
 else{c.fillStyle='#455b58';c.fillRect(0,0,640,300)}
 const reveal=index>=3,blowup=index>=4&&index<=6;
 // A clear dramatic arc: the unidentified visitor steps out of shadow.
 const roberSlide=reveal?Math.max(528,610-Math.min(clock,1.5)*56):675;
 const positions={JAVI:103,IRENE:205,PATRI:289,BLAS:blowup?443:406,ROBER:reveal?Math.min(528,roberSlide):690};
 const talker=burger527CineLines[index][0];
 for(const actor of burger528Actors){
  const x=positions[actor.name];if(x>650)continue;
  const active=talker===actor.name||(talker==='???'&&actor.name==='ROBER');
  let y=236+(active?Math.sin(clock*7)*2:0),dir=0;
  if(actor.name==='ROBER'&&index===3)dir=1;
  if(actor.name==='BLAS'&&blowup)dir=2;
  burger528DrawActor(c,actor.who,x,y,dir,active?clock*5:clock*.8,actor.name==='ROBER'?1.05:1);
  if(active){
   c.fillStyle='#f4d78d';c.fillRect(x-23,115,46,15);
   c.fillStyle='#233b40';c.font='bold 9px monospace';c.textAlign='center';c.fillText(index===3&&actor.name==='ROBER'?'???':actor.name,x,126);
  }
 }
 // Counter in foreground adds depth and hides lower legs naturally.
 c.fillStyle='#263c3c';c.fillRect(18,246,604,49);
 c.fillStyle='#d3a36b';c.fillRect(18,246,604,9);
 c.fillStyle='#a77549';c.fillRect(25,255,590,35);
 for(let x=32;x<607;x+=80){c.fillStyle='#664e3c';c.fillRect(x,261,2,27);c.fillStyle='#e2b983';c.fillRect(x+5,260,44,2)}
 // Trays, jar and burger-of-the-month on top of the counter.
 c.fillStyle='#e9d6a4';c.fillRect(260,238,102,6);
 c.fillStyle='#a56c40';c.fillRect(289,230,43,9);c.fillStyle='#86aa65';c.fillRect(286,226,49,4);c.fillStyle='#e6bb6c';c.fillRect(289,217,42,9);c.fillStyle='#e8d08a';c.fillRect(297,214,3,2);
 c.fillStyle='#b67d5b';c.fillRect(82,237,17,8);c.fillStyle='#e6d3ad';c.fillRect(85,229,11,8);
 if(reveal){
  c.fillStyle='#6e1624';c.globalAlpha=.13+.09*Math.sin(clock*5);c.fillRect(0,0,640,246);c.globalAlpha=1;
  c.fillStyle='#5d2530';c.fillRect(406,83,208,20);
  c.fillStyle='#ffe2c0';c.font='bold 12px monospace';c.textAlign='center';c.fillText('CIERRE S. L.',509,97);
 }
 if(index>=6){c.fillStyle='#35735c';c.fillRect(215,132,210,20);c.fillStyle='#fff0c5';c.font='bold 12px monospace';c.textAlign='center';c.fillText('OFERTA RECHAZADA',320,146)}
 if(index===4||index===6){
  const sh=Math.sin(clock*18)*2;
  c.fillStyle='#fff4c4';c.fillRect(391+sh,107,5,12);c.fillRect(391+sh,122,5,4);
 }
}
// Preserve exact story beats, skipping and state persistence of the original 5.27.
burger527Cinematic=function(){
 let i=0;const id=++burger528FilmToken;state.screen='dialog';
 const finish=()=>{
  burger528FilmToken++;hideModal();state.screen='world';burger527Set(5);
  state.flags.burger527CineSeen=true;noteQuest('burger527_cierre');save();
  toast('Rober se marcha. ¡Cuéntaselo a Blas!');
 };
 function showFrame(){
  const [who,line]=burger527CineLines[i],last=i===burger527CineLines.length-1;
  showModal(`<section class="burger528-cinema" aria-label="La oferta que nadie pidió"><div class="eyebrow">CAPÍTULO II · ALBAL · ESCENA ${i+1}/${burger527CineLines.length}</div><h2>LA OFERTA QUE NADIE PIDIÓ</h2><canvas id="burger528Canvas" width="640" height="300" role="img" aria-label="Javi, Irene, Patri, Blas y Rober en la cocina del Burger L’Horta"></canvas><div class="burger528-voice"><strong>${who}</strong><p>${line}</p></div><div class="modal-actions"><button class="primary" id="burger528Next">${last?'TERMINAR':'SIGUIENTE →'}</button><button class="secondary" id="burger528Skip">SALTAR ESCENA</button></div></section>`,'dialog');
  $('burger528Next').onclick=()=>{if(++i<burger527CineLines.length)showFrame();else finish()};
  $('burger528Skip').onclick=finish;
  const canvas=$('burger528Canvas'),frameAt=i,started=performance.now();
  // One active animation stream, cancelled implicitly on each dialogue advance.
  const tick=(now)=>{
   if(id!==burger528FilmToken||frameAt!==i||!canvas.isConnected)return;
   burger528DrawFilm(canvas,frameAt,(now-started)/1000);
   requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
 }
 showFrame();
};
