 c.fillStyle='#fff5d8';c.fillRect(176,230,17,14);
 c.fillStyle='#b6bac2';c.fillRect(177,231,15,2);
 if(blast){
  for(let n=0;n<3;n++){
   const y=84+n*17;const shift=Math.sin(clock*15+n)*4;
   c.fillStyle='#fbe09a';c.fillRect(424+shift+n*9,y,4,12);
  }
 }
 if(index>=8){
  c.fillStyle='#264f47';c.fillRect(196,132,248,20);
  c.fillStyle='#ffedbf';c.textAlign='center';c.font='bold 12px monospace';c.fillText('MEDALLA DEL MES · CONSEGUIDA',320,146);
 }
