function burger529Outro(){
 let step=0;const token=++burger529FilmToken;
 state.screen='dialog';
 const finish=()=>{
  if(token!==burger529FilmToken)return;
  burger529FilmToken++;hideModal();state.screen='world';
  state.flags.burger529OutroSeen=true;
  state.flags.burger529BurgerFest=true;
  save();updateObjective();toast('¡La medalla es tuya! El Burger no se vende.');
 };
 function showStep(){
  if(token!==burger529FilmToken)return;
  const line=BURGER529_DIALOGUE[step];
  showModal(`<section class="burger529-cinema" aria-label="La bronca del Sensei"><div class="eyebrow">ALBAL · FINAL DEL SEGUNDO GIMNASIO · ${step+1}/${BURGER529_DIALOGUE.length}</div><h2>EL SENSEI NO SABE PERDER</h2><canvas id="burger529Canvas" width="640" height="300" aria-label="Blas regaña al personal del Burger"></canvas><div class="burger529-voice"><strong>${line.who}</strong><p>${line.line}</p></div><div class="modal-actions"><button class="primary" id="nextDialog">${step===BURGER529_DIALOGUE.length-1?'TERMINAR ✓':'SIGUIENTE →'}</button><button class="secondary" id="burger529Skip">SALTAR ESCENA</button></div></section>`,'dialog');
  $('nextDialog').onclick=()=>{if(++step<BURGER529_DIALOGUE.length)showStep();else finish()};
  $('burger529Skip').onclick=finish;
  const canvas=$('burger529Canvas'),frameStep=step,started=performance.now();
  const render=(t)=>{
   if(burger529FilmToken!==token||frameStep!==step||!canvas.isConnected)return;
   burger529DrawScene(canvas,frameStep,(t-started)/1000);
   requestAnimationFrame(render);
  };
  requestAnimationFrame(render);
 }
 showStep();
}
// The engine's original victory dialog remains intact, including XP, reward,
// level-ups and evolutions; the outro begins when that dialog closes.
dialog=function(who,lines,onEnd=()=>{}){
 const isNewBlasWin=burger529PendingVictory&&who==='blas'&&Array.isArray(lines)&&String(lines[0]).startsWith('¡Victoria!')&&state.badges.includes(1);
 if(isNewBlasWin){
  burger529PendingVictory=false;
  return burger529OriginalDialog(who,lines,()=>{onEnd();burger529Outro()});
 }
 return burger529OriginalDialog(who,lines,onEnd);
};
winBattle=function(){
 const isBlas=!!battle&&battle.gymId==='blas'&&!state.badges.includes(1)&&!state.flags.burger529OutroSeen;
 if(isBlas)burger529PendingVictory=true;
 return burger529OriginalWin();
};
