defeatEnemy=function(){
 const second=!!battle&&battle.gymId==='blas'&&battle.index===0&&battle.roster.length>1;
 const result=burger529OriginalDefeat();
 if(second&&battle&&battle.gymId==='blas'&&battle.index===1){
  battle.log='Blas: «¡NO AWELO NO! ¡QUE SALGA UMBREON Y SE ACABE ESTA TONTERÍA!»';
  updateBattle();
  const p=document.createElement('div');p.className='burger529-umbreon-banner';
  p.textContent='¡EL SENSEI SE ENFADA! · UMBREON';
  battleUI.appendChild(p);
  setTimeout(()=>p.remove(),1150);
 }
 return result;
};
