npcTalk=function(n){
 if(!n)return burger529OriginalNpc(n);
 if(n.id==='burger527Blas'&&state.badges.includes(1)){
  return choiceScreen('Blas · Después de la medalla','«¡NO AWELO NO! La próxima vez os cobro por el espectáculo».',[
   ['Hablar con Blas',()=>burger529OriginalNpc(n)],
   ['Volver a ver la bronca',()=>burger529Outro()]
  ]);
 }
 if(state.flags.burger529OutroSeen){
  if(n.id==='burger527Javi')return dialog('javi_cocinero',['El Sensei ha perdido un combate y nos ha echado la bronca a todos. ¡A mí, que estaba haciendo hamburguesas!','Al menos la hamburguesa prohibida es la estrella del menú.']);
  if(n.id==='npc526_patriBurger')return dialog('patri',['La medalla será tuya, pero todavía tengo seis mesas esperando.','Como Blas vuelva a gritarle a una Poké Ball, le paso la cuenta de los clientes.']);
  if(n.id==='npc523_irene523_burger')return dialog('irene523',['Menuda bronca ha montado Blas. Y yo solo estaba repasando el pedido de las trescientas hamburguesas.','Eso sí: ¡bien jugado!']);
  if(n.id==='frankBurger520')return dialog('frank',['Intenté darle un abrazo a Blas. Me dijo que no.','Volveré el jueves... quizá para entonces ya se le ha pasado.']);
 }
 return burger529OriginalNpc(n);
};
