for(const f of PLATA530_FOCI){if(!LORE_POINTS[f.scene])LORE_POINTS[f.scene]=[];if(!LORE_POINTS[f.scene].some(p=>p.id===f.id))LORE_POINTS[f.scene].push({...f});}
QUEST_NOTES.plata530_inicio=['El calentón histórico del Plata','Charizard ha provocado una emergencia en L’Alqueria. Marshall ha propuesto defender el fuego en zona.'];
