GYMS.plata.team=[['Psyduck',17],['Dragonite',19],['Charizard',20]];
SCENES.alqueria.name='L’ALQUERIA · EL CALENTÓN HISTÓRICO';
SCENES.gym_plata.name='L’ALQUERIA · PABELLÓN EN EMERGENCIA';
function plata530Phase(){return state.badges?.includes(2)?5:Math.max(0,Math.min(4,Number(state.flags.plata530Phase)||0));}
function plata530Advance(next){if(plata530Phase()>=next)return;state.flags.plata530Phase=next;if(next>=4)state.flags.plata530Ready=true;save();updateObjective();}
function plata530DrawActor(g,who,x,y,clock,large=115){
 const f=frame22(who,0,Math.floor(clock*4)%4,'gym_plata');
 if(!f?.rect||!f.image.complete||!f.image.naturalWidth){g.fillStyle='#eab974';g.fillRect(x-19,y-72,38,68);return;}
 const h=large,w=h*f.rect[2]/f.rect[3],bob=Math.sin(clock*4+x)*1.5;
 g.fillStyle='#18333b77';g.beginPath();g.ellipse(x,y,Math.max(17,w*.34),7,0,0,Math.PI*2);g.fill();
 g.drawImage(f.image,...f.rect,x-w/2,y-h+bob,w,h);
}
function plata530DrawMovie(canvas,step,clock,ending){
 const g=canvas.getContext('2d');g.imageSmoothingEnabled=false;
 const w=640,h=300;g.clearRect(0,0,w,h);g.fillStyle='#20343b';g.fillRect(0,0,w,h);
 // Scoreboard, inner sports hall and protected playing surface.
 g.fillStyle='#31515a';g.fillRect(0,0,w,95);
 for(let i=0;i<7;i++){g.fillStyle=i%2?'#3c656a':'#29484f';g.fillRect(i*92,0,86,84)}
 g.fillStyle='#172d35';g.fillRect(229,11,184,52);g.strokeStyle='#edc773';g.lineWidth=3;g.strokeRect(229,11,184,52);
 g.font='bold 16px monospace';g.fillStyle='#ffe0a2';g.textAlign='center';g.fillText(ending?'PLATA · 0  /  LA PREVIA · 1':'EMERGENCIA · L’ALQUERIA',321,34);
 g.font='10px monospace';g.fillText(ending?'MEDALLA CALENTÓN':'AVISO: DESALOJAR LA PISTA',321,51);
 g.fillStyle='#326354';g.fillRect(0,95,w,205);
 for(let j=0;j<13;j++){g.fillStyle=j%2?'#356b56':'#38715a';g.fillRect(0,98+j*16,w,1)}
 g.strokeStyle='#eee6c2';g.lineWidth=3;g.strokeRect(28,124,w-56,154);
 g.beginPath();g.arc(320,201,47,0,Math.PI*2);g.moveTo(320,125);g.lineTo(320,278);g.stroke();
 // The fire grows during the opening; embers fade after the final victory.
 if(!ending){for(let i=0;i<31;i++){const x=33+((i*43)%574),y=267-(i%4)*11-Math.abs(Math.sin(clock*3+i))*19;
  const sz=3+i%4;g.fillStyle=i%3===0?'#ffdf82':'#fa7847';g.fillRect(Math.round(x),Math.round(y),sz,sz*2);
 }}
 const active=(ending?PLATA530_END:PLATA530_CHAPTER)[step][0];
 plata530DrawActor(g,'marshall',133,257,clock+(active==='MARSHALL'?2:0));
 plata530DrawActor(g,'plata',326,253,clock+(active==='PLATA'?2:0),128);
 plata530DrawActor(g,'jesus',514,255,clock+(active==='JESÚS'?2:0),110);
 // Charizard is the central visual, never replaces Plata's actual trainer sprite.
 const c=asset('mon22_charizard_front');
 if(c.complete&&c.naturalWidth&&(!ending||step<2)){
  const fire=1+Math.sin(clock*5)*.025;
  g.save();g.translate(435,169);g.scale(fire,fire);g.drawImage(c,-53,-65,106,106);g.restore();
 }
 if(active==='UKI'){const u=frame22('uki523',0,Math.floor(clock*5)%4,'alqueria');if(u?.image.complete&&u.image.naturalWidth)g.drawImage(u.image,...u.rect,40,156,65,98)}
 g.fillStyle='#ffdd9a';g.font='bold 11px monospace';g.textAlign='left';g.fillText('L’ALQUERIA · VALENCIA BASKET',20,292);
}
let plata530FilmToken=0;
function plata530Cinematic(ending=false){
 // The original Charizard cinematic may be active during QA/skip; never leave it over the epilogue.
 if(ending&&typeof cineCurrent34!=='undefined'&&cineCurrent34)cineEnd34();
 if(ending&&$('cine34'))$('cine34').classList.add('hidden');
 const lines=ending?PLATA530_END:PLATA530_CHAPTER;
 let index=0,token=++plata530FilmToken;
 state.screen='dialog';heldKeys.clear();joystick.x=joystick.y=0;
 const finish=()=>{if(token!==plata530FilmToken)return;plata530FilmToken++;hideModal();state.screen='world';
  if(ending){state.flags.plata530OutroSeen=true;state.flags.plata530FireGone=true;SCENES.gym_plata.name='L’ALQUERIA · MEDALLA CALENTÓN';if(state.scene==='gym_plata')$('areaTag').textContent=SCENES.gym_plata.name;}
  else{state.flags.plata530IntroSeen=true;plata530Advance(1);noteQuest('plata530_inicio');}
  save();updateObjective();toast(ending?'¡L’Alqueria está a salvo!': 'Busca la alarma junto a la plaza.');};
 function show(){if(token!==plata530FilmToken)return;const [who,text]=lines[index];
  showModal(`<section class="plata530-cinema"><div class="eyebrow">CAPÍTULO III · L’ALQUERIA · ${index+1}/${lines.length}</div><h2>${ending?'L’ALQUERIA VUELVE A RESPIRAR':PLATA530_TITLE}</h2><canvas id="plata530Canvas" width="640" height="300" aria-label="Cinemática animada de Plata, Marshall, Jesús, Uki y Charizard"></canvas><div class="plata530-subtitle"><strong>${who}</strong><p>${text}</p></div><div class="modal-actions"><button class="primary" id="plata530Next">${index===lines.length-1?'TERMINAR':'SIGUIENTE →'}</button><button class="secondary" id="plata530Skip">SALTAR ESCENA</button></div></section>`,'dialog');
  $('plata530Next').onclick=()=>{if(++index<lines.length)show();else finish()};$('plata530Skip').onclick=finish;
  const c=$('plata530Canvas'),oldIndex=index,begin=performance.now();
  const tick=now=>{if(token!==plata530FilmToken||oldIndex!==index||!c.isConnected)return;plata530DrawMovie(c,oldIndex,(now-begin)/1000,ending);requestAnimationFrame(tick)};requestAnimationFrame(tick);
 }
 show();
}
function plata530TalkMarshall(){
 if(!state.badges.includes(1))return dialog('marshall',['Antes de entrar a L’Alqueria, consigue las medallas de Silla y Albal. Plata te espera después.']);
 if(state.badges.includes(2))return choiceScreen('L’Alqueria, después del calentón','«¡L’Alqueria vuelve a estar bien! Ni me hagáis hablar de la defensa en zona contra el fuego».',[['Recordar el desastre de Charizard',()=>plata530Cinematic(false)],['Curar a mi equipo',()=>{backWorld();healAll();toast('Equipo recuperado.');}],['Seguir explorando',backWorld]]);
 const p=plata530Phase();
 if(p===0)return plata530Cinematic(false);
 if(p===1)return dialog('marshall',['La alarma sigue sin sonar. Está al este de la plaza.','No te preocupes, tengo a cinco chavales preparados para hacer zona 2-3...']);
 if(p===2)return dialog('marshall',['Uki ha evacuado a los canteranos. Ve a la pista exterior.','Ojo con la zona: el fuego no defiende en individual.']);
 if(p===3)return dialog('marshall',['Las salidas están despejadas. Entra al pabellón y busca el equipo de emergencia junto a la pista.']);
 return dialog('marshall',['Lo has conseguido. ¡Y sin incendiar otra pizarra!','Ahora entra a desafiar a Plata. No me preguntes dónde ha guardado a Charizard.'],()=>healAll());
}
function plata530Landmark(p){
 const phase=plata530Phase();
 if(!state.badges.includes(1))return dialog(null,['El pabellón abrirá su aventura tras ganar la Medalla Del Mes de Albal.']);
 if(state.badges.includes(2))return dialog(null,['Se han apagado las alarmas. Solo quedan unas marcas chamuscadas en el suelo.']);
 if(phase===0)return dialog('marshall',['¡Primero habla conmigo en la plaza! El pabellón se nos está viniendo encima.']);
 if(p.id==='plata530Panel'){
  if(phase>1)return dialog(null,['ALARMA ACTIVADA · Un sonido agudo recorre L’Alqueria. Los jugadores ya han salido.']);
  state.flags.plata530Alarma=true;plata530Advance(2);noteQuest('plata530_alarma');
  return dialog('uki523',['¡Bien! Ya suena la alarma y los canteranos están fuera.','Ahora despeja la pista exterior. Marshall está poniendo a los chavales en una zona que no tiene ningún sentido.']);
 }
 if(p.id==='plata530Cancha'){
  if(phase<2)return dialog('jesus',['Primero activa la alarma de incendios.']);
  if(phase>2)return dialog(null,['La pista está despejada. Se puede evacuar sin obstáculos.']);
  return choiceScreen('¿DEFENSA EN ZONA CONTRA EL FUEGO?', 'Marshall pretende organizar a los canteranos en zona 2-3 mientras las llamas se acercan a la pista. ¿Qué harías?',[
   ['Despejar accesos y sacar a todo el mundo',()=>{backWorld();state.flags.plata530Evacuado=true;plata530Advance(3);noteQuest('plata530_pista');dialog('jesus',['¡ASÍ SÍ! ¡Todo el mundo fuera y sin hacer tonterías!','Marshall, deja la pizarra. Esto no se arregla con una defensa en zona.','Entra al pabellón y recoge el equipo de emergencia.']);}],
   ['Hacer un 2-3 y que Charizard ataque la línea de fondo',()=>dialog('marshall',['¡VALE, VALE! Concedo que la zona contra las llamas no funciona.','Lo sensato es evacuar a los chavales. Vuelve a intentarlo.'])]
  ]);
 }
 if(p.id==='plata530Equipo'){
  if(phase<3)return dialog('jesus',['Antes hay que asegurar la pista exterior y avisar a todos.','Busca a Marshall y la alarma en la plaza.']);
  if(phase>3)return dialog(null,['EXTINTORES RECOGIDOS · La cantera está a salvo. Plata espera junto al aro.']);
  state.flags.plata530Extintor=true;plata530Advance(4);noteQuest('plata530_equipo');
  return dialog('plata',['Hostia, bien hecho. Al menos alguien ha reaccionado sin montar una reunión.','¿Que yo he provocado todo esto? ¡ESTABA EXPLICANDO EL RECURSO NÚMERO 87!','Ahora ven al centro de la pista. A ver si también puedes pararme en un combate.']);
 }
}
const plata530OldNpc=npcTalk;
npcTalk=function(n){
 if(n?.id==='healAlqueria')return plata530TalkMarshall();
 if(n?.id==='plataQuest'&&!state.badges.includes(2)&&state.badges.includes(1))return dialog('plata',['Estoy en mitad de un entrenamiento con Charizard... y ahora todo huele a quemado.','Marshall está en la plaza y sabe qué hacer. O eso dice.']);
 if(n?.id==='gym_plata'&&!state.badges.includes(2))return gymChallenge('plata');
 if(n?.id==='npc523_uki523_alqueria'&&!state.badges.includes(2)&&plata530Phase()>0)return dialog('uki523',plata530Phase()<=2?['He sacado a los canteranos. No te entretengas: primero la alarma y la pista.']:['La cantera está a salvo. ¡Ahora ve a por Plata!']);
 if(n?.id==='npc526_jesusGym'&&!state.badges.includes(2)&&plata530Phase()>0&&plata530Phase()<4)return dialog('jesus',['No bloquees los accesos. Los ejercicios de los canteranos tendrán que esperar.','Marshall está intentando hacer una zona contra el fuego. No me lo puedo creer.']);
 return plata530OldNpc(n);
};
const plata530OldLore=landmarkTalk;
landmarkTalk=function(p){if(PLATA530_FOCI.some(f=>f.id===p?.id))return plata530Landmark(p);
 if(p?.id==='plataBoard52'&&!state.badges.includes(2))return dialog('plata',['La pizarra de los 87 recursos está chamuscada.','Primero evita que el pabellón termine ardiendo. Luego hablamos de táctica.']);
 return plata530OldLore(p)};
const plata530OldGym=gymChallenge;
gymChallenge=function(id){
 if(id!=='plata')return plata530OldGym(id);
 if(state.badges.includes(2))return choiceScreen('Plata · Medalla Calentón','«La medalla es tuya. Y pienso dejar a Charizard dentro de su Poké Ball una temporada»',[['Volver a ver cómo termina el calentón',()=>plata530Cinematic(true)],['Salir del pabellón',backWorld]]);
 if(!state.badges.includes(1))return dialog('plata',['Primero ve al Burger L’Horta y consigue la segunda medalla.']);
 if(plata530Phase()<4)return dialog('plata',['¿Un combate? ¡PERO SI ESTÁ ARDIENDO EL PABELLÓN!','Habla con Marshall en la plaza, activa la alarma, despeja la pista y recoge el equipo de emergencia.']);
 const g=GYMS.plata;
 state.screen='menu';
 showModal(`<section class="plata530-challenge"><div class="eyebrow">TERCER GIMNASIO · L’ALQUERIA</div><h2>PLATA · EL HOMBRE DE RECURSOS</h2><p>«A ver, que estaba muy tranquilo... hasta ahora»</p><div class="plata530-lineup"><span>PSYDUCK · NV. 17</span><span>DRAGONITE · NV. 19</span><span>CHARIZARD · NV. 20</span></div><p><b>Tu equipo se curará antes del combate.</b> Cuando a Plata solo le quede Charizard, empieza el verdadero calentón.</p><div class="modal-actions"><button class="primary" id="plata530Fight">¡A COMBATIR!</button><button class="secondary" id="plata530Cancel">AHORA NO</button></div></section>`);
 $('plata530Fight').onclick=()=>{backWorld();healAll();startBattle(g.team[0][0],g.team[0][1],false,'gym:plata')};
 $('plata530Cancel').onclick=backWorld;
};
const plata530OldObjective=updateObjective;
updateObjective=function(){plata530OldObjective();if(!state.flags?.starter||!state.badges?.includes(1)||state.badges?.includes(2))return;
 const steps=['Busca a Marshall en la plaza de L’Alqueria.','Activa la alarma junto al pabellón.','Despeja las pistas exteriores con Jesús y Uki.','Entra al pabellón y recoge el equipo de emergencia.','Reta a Plata en el centro del pabellón.'];
 $('objective').textContent='CAPÍTULO III · '+steps[plata530Phase()];
};
const plata530OldWorld=renderWorld;
renderWorld=function(){plata530OldWorld();
 if(state.screen!=='world'||(state.scene!=='alqueria'&&state.scene!=='gym_plata')||!state.badges?.includes(1)||state.badges?.includes(2))return;
 const phase=plata530Phase();if(phase===0||phase>=4)return;
 const s=SCENES[state.scene];let fit=1,cx=0,cy=0;
 if(state.scene==='gym_plata'){({fit,cx,cy}=roomView50(s));}
 else{({cx,cy}=outsideView53(s));}
 ctx.save();ctx.scale(fit,fit);ctx.translate(-Math.floor(cx),-Math.floor(cy));
 const centers=state.scene==='gym_plata'?[[15.3,6.7],[5.7,7]]:[[16,9.1],[18,17.2]];
 for(let j=0;j<centers.length;j++){const [tx,ty]=centers[j],x=tx*TILE,y=ty*TILE;
  for(let i=0;i<15;i++){const rise=(elapsed*(26+i%5*4)+i*19)%110,off=Math.sin(elapsed*1.6+i*2.2)*14;
   ctx.fillStyle=i%3?'#a9a7a280':'#e8b2877f';ctx.fillRect(x+off+(i%5)*8-21,y-rise,7+(i%3)*4,7+(i%3)*5);
  }
  ctx.fillStyle='#ec9756';ctx.globalAlpha=.32+.12*Math.sin(elapsed*5+j);ctx.fillRect(x-12,y-5,22,7);ctx.globalAlpha=1;
 }
 ctx.restore();
};
