winBattle=function(){if(battle?.gymId==='plata'&&!state.badges.includes(2)&&!state.flags.plata530OutroSeen)plata530VictoryPending=true;return plata530PreviousWin();};
const plata530PreviousDialog=dialog;
dialog=function(who,lines,onEnd=()=>{}){
 const final=plata530VictoryPending&&who==='plata'&&Array.isArray(lines)&&String(lines[0]).startsWith('¡Victoria!')&&state.badges.includes(2);
 if(final){plata530VictoryPending=false;return plata530PreviousDialog(who,lines,()=>{onEnd();plata530Cinematic(true);});}
 return plata530PreviousDialog(who,lines,onEnd);
};
