function sueca531Cinema(kind='intro'){
 const lines=kind==='intro'?SUECA531_INTRO:kind==='match'?SUECA531_MATCH_END:SUECA531_AFTER;
 let ix=0,token=++sueca531FilmToken;state.screen='dialog';heldKeys.clear();joystick.x=joystick.y=0;
 const finish=()=>{if(token!==sueca531FilmToken)return;sueca531FilmToken++;hideModal();state.screen='world';
  if(kind==='intro'){state.flags.sueca531IntroSeen=true;noteQuest('sueca531');}
  if(kind==='post'){state.flags.sueca531OutroSeen=true;}
  save();updateObjective();};
 const show=()=>{if(token!==sueca531FilmToken)return;
  const [who,line]=lines[ix];showModal(`<section class="sueca531-film"><div class="eyebrow">CAPÍTULO IV · SUECA · ${ix+1}/${lines.length}</div><h2>${kind==='intro'?'EL PARTIDO QUE NADIE QUERÍA VER':kind==='match'?'EL MILAGRO DEL PUTO 5 %':'UNA MEDALLA INESPERADA'}</h2><canvas width="640" height="300" id="sueca531Canvas" aria-label="Cinemática animada del partido de Horte contra Sueca"></canvas><div class="sueca531-sub"><strong>${who}</strong><p>${line}</p></div><div class="modal-actions"><button id="sueca531Next" class="primary">${ix===lines.length-1?'TERMINAR':'SIGUIENTE →'}</button><button id="sueca531Skip" class="secondary">SALTAR</button></div></section>`,'dialog');
  $('sueca531Next').onclick=()=>{if(++ix<lines.length)show();else finish()};$('sueca531Skip').onclick=finish;
  const c=$('sueca531Canvas'),start=performance.now(),cur=ix;const tick=now=>{if(token!==sueca531FilmToken||ix!==cur||!c.isConnected)return;sueca531DrawMovie(c,ix,(now-start)/1000,kind);requestAnimationFrame(tick)};requestAnimationFrame(tick);
 };show();
}
function sueca531Match(){
 if(!state.badges.includes(2))return dialog('horte',['Para venir a remontar primero consigue las tres medallas anteriores, campeón.']);
 if(!state.flags.sueca531IntroSeen)return sueca531Cinema('intro');
 if(state.flags.sueca531Ready)return choiceScreen('Sueca · 54-50','La remontada ya es historia. El capitán sigue protestando y Horte continúa llamándoles culorrotos.',[['Ver otra vez el milagro',()=>sueca531Cinema('match')],['Ir al gimnasio',backWorld]]);
 const ix=sueca531Round(),r=SUECA531_ROUNDS[ix];if(!r)return;
 state.screen='menu';showModal(`<section class="sueca531-match"><div class="eyebrow">PARTIDO CONTRA SUECA · ${ix+1}/3</div><h2>${r.name}</h2><div class="sueca531-score"><span>SUECA</span><strong>${r.score.split(' · ')[1]} : ${r.score.split(' · ')[0]}</strong><span>HORTE</span></div><p>${r.text}</p><div class="sueca531-choices">${r.options.map((v,i)=>`<button id="sueca531Opt${i}" class="${i===0?'primary':'secondary'}">${v}</button>`).join('')}</div><button id="sueca531Pause" class="secondary">VOLVER AL PUEBLO</button></section>`,'menu');
 r.options.forEach((v,i)=>$('sueca531Opt'+i).onclick=()=>{
  if(i!==r.answer)return dialog('horte',['¡¡NO AWELO NO!! ¡Que aquí solo nos queda un 5 % de opciones!','Vuelve al marcador y piensa cómo aprovechar esta nueva estupidez del reglamento.']);
  state.flags.sueca531Round=ix+1;save();if(ix===2){sueca531Advance();return sueca531Cinema('match');}
  return dialog('horte',[r.result,'¡Vamos! El árbitro está volviendo a cambiar las normas. Regresa al marcador.']);
 });$('sueca531Pause').onclick=backWorld;
}
function sueca531HorteTalk(){
 if(state.badges.includes(3))return choiceScreen('Horte · El 5 %','«¡Yo ya te he dado la medalla! ¡Y no pienso cambiar las reglas otra vez!»', [['Recordar el partido imposible',()=>sueca531Cinema('match')],['Ver el final del gimnasio',()=>sueca531Cinema('post')],['Seguir explorando',backWorld]]);
 if(!state.badges.includes(2))return dialog('horte',['Primero vence a Plata. Necesitamos un equipo preparado para este partido.']);
 if(!state.flags.sueca531IntroSeen)return sueca531Cinema('intro');
 if(!state.flags.sueca531Ready)return dialog('horte',['¡¡VAMOS PERDIENDO DE 43!! ¡Pero confía en el puto 5 %!','Ve al marcador de la pista y ayúdame con la remontada.']);
 return dialog('horte',['¡¡CULORROTOS!! ¡¡¡QUE HEMOS REMONTADO!!!','Ahora entra al gimnasio. Slowbro está preparado para enseñarte lo que cuesta una medalla.']);
}
