const F532_W=32,F532_H=23;
const f532Wall=(x,y)=>{
 const tx=Math.floor(x),ty=Math.floor(y);
 if(tx<2||ty<2||tx>=F532_W-2||ty>=F532_H-2)return true;
 if((tx===10||tx===21)&&ty>=3&&ty<=17&&![5,10,15].includes(ty))return true;
 if(ty===10&&tx>=4&&tx<=28&&![7,16,26].includes(tx))return true;
 return false;
};
