const f532OldCollision=collision;
collision=function(x,y){if(state.scene==='festivern532'&&f532Wall(x,y))return true;return f532OldCollision(x,y)};
const f532OldTown=drawTownProps;
drawTownProps=function(s){if(state.scene!=='festivern532'){f532OldTown(s);return}
 const t=elapsed;
 // Purple glass and shifting false walls. Tiles have matching collision geometry.
 for(let x=2;x<30;x++)for(let y=2;y<21;y++){
  const wave=Math.sin(t*1.7+x*.65+y*.8);
  if(f532Wall(x,y)){rect(x*TILE,y*TILE,TILE,TILE,((x+y)%2?'#55348c':'#422979'));rect(x*TILE+5,y*TILE+4,TILE-10,9,'#9a6cdc');rect(x*TILE+8,y*TILE+18,TILE-16,5,'#c984e7');}
  else if((x+y*3)%11===0){ctx.fillStyle=wave>0?'#f4d483aa':'#7cdadba6';ctx.beginPath();ctx.arc((x+.5)*TILE,(y+.5)*TILE,7+wave*3,0,Math.PI*2);ctx.fill();}
 }
 for(let i=0;i<26;i++){const x=(3+i*7)%28+2,y=(3+i*11)%18+3;if(f532Wall(x,y))continue;const a=elapsed*1.6+i*1.7;ctx.fillStyle=['#fbd48699','#a2ffcd99','#dc96efaa'][i%3];ctx.fillRect((x+.5)*TILE+Math.sin(a)*14,(y+.5)*TILE+Math.cos(a)*14,4,4)}
 ctx.font='bold 24px monospace';ctx.textAlign='center';ctx.fillStyle='#f7db85';ctx.fillText('FESTIVERN · 7 DIMENSIONES',16*TILE,2*TILE+8);ctx.textAlign='left';
};
// Distinct palette, silhouette and halo per clone, without replacing the main Nachito sprite.
const f532OldCharacter=drawCharacter;
drawCharacter=function(who,x,y,dir,anim=0){if(!String(who).startsWith('fest532_echo'))return f532OldCharacter(who,x,y,dir,anim);
 const i=Number(who.slice(12))||0,e=F532_ECHOES[i]||F532_ECHOES[0];
 ctx.save();ctx.filter=`hue-rotate(${i*44}deg) saturate(${1.05+i*.08})`;f532OldCharacter('nachito',x,y,dir,anim);ctx.filter='none';ctx.globalAlpha=.8;ctx.strokeStyle=e.color;ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(x,y-93+Math.sin(elapsed*2+i)*5,17+i%3*2,9,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle=e.color;ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText((i+1)+'/7',x,y-109);ctx.textAlign='left';ctx.restore();
};
