const f532OldObj=updateObjective;
function f532EchoCount(){return F532_ECHOES.filter((_,i)=>(Number(state.flags.fest532Mask)||0)&(1<<i)).length}
updateObjective=function(){f532OldObj();if(!state.flags?.starter||!state.badges.includes(3)||state.badges.includes(4))return;
 $('objective').textContent=!state.flags.fest532IntroSeen?'CAPÍTULO V · Habla con Nachito en Picassent.':!state.flags.fest532Ready?`FESTIVERN · Reúne siete versiones de Nachito (${f532EchoCount()}/7). Entra en el portal del laboratorio.`:'CAPÍTULO V · Alquimista Supremo. Reta a Nachito en el laboratorio.';
};
function f532Reward(){if(state.flags.fest532Ready)return;state.flags.fest532Ready=true;state.flags.labReady=true;state.flags.labMask=7;state.flags.labStep=3;
 if(!state.flags.toxicTM){state.flags.toxicTM=true;state.bag.antidote=(state.bag.antidote||0)+2;noteQuest('formula')}
 noteQuest('fest532');save();updateObjective();}
function f532CloneTalk(i,hint=''){const e=F532_ECHOES[i],mask=Number(state.flags.fest532Mask)||0;if(mask&(1<<i))return dialog('nachito',[`${e.name}: «Ya me has encontrado. ¡Deja de dar vueltas, coño!»`]);
 choiceScreen(e.name+' · Dimensión '+(i+1),hint||e.phrase+' '+e.question,e.choices.map((c,k)=>[c,()=>{
  if(k!==e.answer)return f532CloneTalk(i,'El clon se ríe: «Esa respuesta nos deja aquí hasta el Festivern siguiente». '+e.question);
  state.flags.fest532Mask=mask|(1<<i);save();updateObjective();
  dialog('nachito',[`${e.name}: «Vale, tú eres de los nuestros. ¡Ya somos ${f532EchoCount()}/7!»`,i===6?'¡El Ronaldo de saldo desaparece con un regate!':'El eco se transforma en una chispa y vuelve al matraz.'],()=>{if(f532EchoCount()===7){f532Reward();f532Cinema('transform')}});
 }]));
}
let f532FilmSerial=0,f532FrameSerial=0;
const F532_FILMS={
 intro:[['El laboratorio de Picassent','Nachito mete la Piedra de Cristal en una máquina con siete matraces.'],['Primera reacción','Una nube verde invade el techo. Marshall ve humo y sale corriendo.'],['El gran petardazo','¡BOOOOM! Las luces parpadean y siete Nachitos aparecen en siete dimensiones.'],['Nachito, el de verdad','«¡BRASIL NANANANANANA! ¡ME HE MULTIPLICADO, HOSTIA!»'],['El portal','Entra al laboratorio y busca la puerta violeta. Reúne los siete ecos para volver.']],
 transform:[['Las siete dimensiones','Los siete ecos giran alrededor de la Piedra de Cristal.'],['Umbreon, Químico, Vaper...','La gorra de Brasil flota, los matraces brillan y el Ronaldo de saldo da el último regate.'],['EL ALQUIMISTA SUPREMO','Nachito levita sobre una nube psicodélica. «¡CONFÍO EN EL 100 %, POR UNA VEZ!»'],['Laboratorio recuperado','«La próxima vez hacemos un experimento normal. Es decir, probablemente no».'],['De vuelta al combate','¡La Medalla Vesubio espera en el laboratorio!']],
 post:[['Quinta medalla','Drowzee y Electabuzz han caído. Gengar es derrotado.'],['Nachito','«Me he multiplicado siete veces y aún así me habéis ganado. Qué puta vergüenza».'],['Marshall','«Yo solo venía a buscarte. Tengo la sensación de que llevamos aquí tres días».'],['Nachito','«BRASIL NANANANANANA. La próxima vez invoco ocho».'],['El libro de reservas','La quinta página regresa a La Previa. Próximo destino: Turís.']]
};
function f532Cinema(mode='intro'){
 const scenes=F532_FILMS[mode]||F532_FILMS.intro;let at=0;const serial=++f532FilmSerial;state.screen='menu';
 function finish(){++f532FilmSerial;++f532FrameSerial;if(mode==='intro')state.flags.fest532IntroSeen=true;if(mode==='post')state.flags.fest532OutroSeen=true;save();backWorld();if(mode==='transform'&&state.scene==='festivern532')changeScene('gym_nachito',[13,11]);updateObjective()}
 function scene(){if(serial!==f532FilmSerial)return;const frameId=++f532FrameSerial;
 showModal(`<section class="fest532-film"><div class="eyebrow">CAPÍTULO V · ${mode==='intro'?'EXPLOSIÓN':mode==='transform'?'TRANSFORMACIÓN':'FINAL'} · ${at+1}/${scenes.length}</div><h2>${scenes[at][0]}</h2><canvas id="fest532Frame" width="640" height="280"></canvas><div class="fest532-sub"><strong>${scenes[at][0]}</strong><p>${scenes[at][1]}</p></div><div class="modal-actions"><button class="primary" id="fest532Next">${at+1===scenes.length?'TERMINAR':'SIGUIENTE ▶'}</button><button class="secondary" id="fest532Skip">SALTAR CINEMÁTICA</button></div></section>`,'menu');
 $('fest532Next').onclick=()=>{if(at<scenes.length-1){at++;scene()}else finish()};$('fest532Skip').onclick=finish;let ticks=0;
 const draw=()=>{if(serial!==f532FilmSerial||frameId!==f532FrameSerial||!$('fest532Frame'))return;const c=$('fest532Frame'),g=c.getContext('2d');if(!g)return;ticks++;const t=ticks/30;
 const grad=g.createLinearGradient(0,0,640,280);grad.addColorStop(0,mode==='post'?'#25445d':'#432b66');grad.addColorStop(1,mode==='transform'?'#ab5fd1':'#1a3442');g.fillStyle=grad;g.fillRect(0,0,640,280);
 g.fillStyle='#241d46';g.fillRect(0,229,640,51);g.strokeStyle='#bfa8df';g.lineWidth=3;for(let x=0;x<640;x+=40){g.beginPath();g.moveTo(x,229);g.lineTo(x+18,280);g.stroke()}
 const img=asset('nachito_alquimista_atlas21');if(img?.complete&&img.naturalWidth){const src=[196,9,327,605],h=180+(mode==='transform'?Math.sin(t*4)*12:0);g.drawImage(img,...src,266,230-h,105,h)}else{g.fillStyle='#3fd47c';g.fillRect(288,110,65,116);}
 for(let i=0;i<24;i++){const a=i*2.399+t*(mode==='transform'?2:1.1),r=30+(i%6)*19;g.globalAlpha=.4+.5*Math.abs(Math.sin(a));g.fillStyle=['#eddb68','#82e3fd','#f38ddf','#87ffa7'][i%4];g.fillRect(320+Math.cos(a)*r,132+Math.sin(a)*r*.65,5+(i%3)*2,5+(i%3)*2)}g.globalAlpha=1;
 if(mode==='transform'){for(let i=0;i<7;i++){const a=t*1.4+i*6.283/7;g.fillStyle=F532_ECHOES[i].color;g.beginPath();g.arc(320+Math.cos(a)*175,136+Math.sin(a)*86,11,0,7);g.fill()}}
 if(mode==='intro'&&at>=2){g.fillStyle='#f8e38b';g.font='bold 54px monospace';g.textAlign='center';g.fillText('¡BOOM!',320,64)}
 if(mode==='post'){g.fillStyle='#f3d988';g.font='bold 30px monospace';g.textAlign='center';g.fillText('MEDALLA VESUBIO',320,46)}
 requestAnimationFrame(draw)};requestAnimationFrame(draw);
 }scene();
}
const f532OldNpcTalk=npcTalk;
npcTalk=function(n){if(n?.id==='nachitoSchool'&&!state.badges.includes(4)&&state.badges.includes(3)){
  if(!state.flags.fest532IntroSeen)return f532Cinema('intro');
  return dialog('nachito',[state.flags.fest532Ready?'La Piedra de Cristal vuelve a estar quieta. Por fin. ¡Ven a luchar por la quinta medalla!':'¡Hay siete Nachitos dentro del portal del laboratorio! El de la gorra dice que es el auténtico, pero eso lo decimos todos.','Busca el portal violeta dentro de mi laboratorio.']);
 }
 if(n?.id?.startsWith('fest532_')){const i=F532_ECHOES.findIndex(e=>'fest532_'+e.id===n.id);if(i>=0)return f532CloneTalk(i)}
 if(n?.id==='gym_nachito'&&state.badges.includes(4))return choiceScreen('Nachito · El Alquimista','La quinta medalla está conseguida. ¿Quieres recordar la locura?', [['Volver a ver la explosión',()=>f532Cinema('intro')],['Ver la transformación',()=>f532Cinema('transform')],['Ver el epílogo',()=>f532Cinema('post')],['Salir',backWorld]]);
 return f532OldNpcTalk(n);
};
const f532OldLandmark=landmarkTalk;
