const T533_SCENES={
 intro:[['Las hazañas del siglo','En Turís aseguran que el líder derrotó a Mewtwo de un puñetazo. Nadie encuentra testigos… pero todo el mundo lo ha visto.'],['La canasta imposible','Calvito jura que encestó desde otro pueblo. Carlos Megáfono ya ha impreso camisetas.'],['La regla no escrita','Árbitro: «Aquí gana quien dice que ha ganado más convencido».'],['La leyenda te espera','El gimnasio abre sus puertas. Entra y comprueba qué hay de cierto en tanto cuento.']],
 denial:[['Resultado oficial','¡Has derrotado al equipo del líder! El marcador dice VICTORIA DEL JUGADOR.'],['El Gitano de Turís','«Pero si he ganado yo».'],['Espectador 1','«Ostras, si dice que ha ganado él, es que ha ganado él».'],['Espectador 2','«Yo lo he visto ganar clarísimamente».'],['Árbitro','«Pues victoria del Gitano de Turís. La medalla queda retenida».'],['La propuesta','Líder: «Si quieres la medalla, tráeme la chatarra que hay por aquí. Luego hablamos».']],
 ending:[['La chatarra sagrada','Has reunido cuatro piezas de chatarra del gimnasio.'],['El líder examina el montón','«Buen material. ¿Y el partido? Bueno, yo gané, eso está claro».'],['La sexta medalla','Te entrega la Medalla Chatarra, casi de mala gana.'],['El público','«¡Otra victoria legendaria del Gitano de Turís!» Nadie ha mirado el marcador.'],['El camino continúa','Seis medallas conseguidas. Próxima aventura: la fiesta y el descanso del Awelo en Zaragoza.']]
};
