   for(let i=0;i<11;i++){let x=40+i*57;g.fillStyle=['#ebaf70','#a2bfde','#f0daa3'][i%3];g.fillRect(x,93+Math.sin(t*3+i)*4,30,36);g.fillStyle=['#815c48','#483e37'][i%2];g.fillRect(x+4,83+Math.sin(t*3+i)*4,23,15)}
   // Drawing from the in-game NPC atlas, not an unrelated image.
   let spriteImg=sprite('gitano523');if(spriteImg?.complete&&spriteImg.naturalWidth){let fw=spriteImg.naturalWidth/4,fh=spriteImg.naturalHeight/4;g.drawImage(spriteImg,0,0,fw,fh,255,98+Math.sin(t*2)*3,130,160)}
   else {g.fillStyle='#4c3432';g.fillRect(268,114,105,132);g.fillStyle='#d6a37b';g.fillRect(290,88,64,67)}
   g.fillStyle='#eae5b0';g.font='bold 22px monospace';g.textAlign='center';g.fillText(kind==='denial'?'PERO SI HE GANADO YO':kind==='ending'?'MEDALLA CHATARRA':'LA LEYENDA DE TURÍS',320,26);g.textAlign='left';
