// Una pestaña suspendida puede cancelar una cadena de animación. Rescatamos
// sólo un combate realmente bloqueado durante demasiado tiempo, sin duplicar
// turnos ni tocar el resultado del combate.
let lastBattle542=null,lockedStart542=0,lockWarn542=false;
const updateBefore542=update;
update=function(dt){updateBefore542(dt);
 if(!battle||state.screen!=='battle'){lastBattle542=null;lockedStart542=0;lockWarn542=false;return}
 if(battle!==lastBattle542){lastBattle542=battle;lockedStart542=0;lockWarn542=false;return}
 if(!battle.locked){lockedStart542=0;lockWarn542=false;return}
 if(!lockedStart542)lockedStart542=performance.now();
 if(performance.now()-lockedStart542>7500&&!lockWarn542&&!battle.forced){
  lockWarn542=true;lockedStart542=performance.now();
  // Es una recuperación de interfaz de emergencia: no se ejecuta un turno
  // extra ni se vuelve a descontar PP.
  battle.locked=false;battle.ui54={mode:'moves'};
  if(typeof setBattleLog54==='function')setBattleLog54((battle.log||'')+' · Ya puedes elegir un movimiento.');
  updateBattle();
 }
};
