try{v551Effects=localStorage.getItem(v551Preference)!=='off'}catch{}
const v551MarkerSpeak=asset('ui551_hablar');
const v551MarkerDoor=asset('ui551_puerta');
const v551Sparkle=asset('fx551_destello');
const v551PreviousRenderWorld=renderWorld;
renderWorld=function(){
 v551PreviousRenderWorld();
 if(state.screen!=='world')return;
 const sc=SCENES[state.scene];if(!sc)return;
 let cx=clamp(camera.x,0,Math.max(0,sc.w*TILE-W));
 let cy=clamp(camera.y,0,Math.max(0,sc.h*TILE-H));
 if(sc.h*TILE<H)cy=(sc.h*TILE-H)/2;
 if(sc.w*TILE<W)cx=(sc.w*TILE-W)/2;
 ctx.save();ctx.imageSmoothingEnabled=false;
 if(v551Effects){
  // Tiny animated sparkle at prominent town landmarks. Drawn in screen space,
  // so collision / logical map and save data never change.
  const effects={benifaio:[[20.6,14.1],[20.3,15.4]],albal:[[15.7,11.6]],silla:[[10.3,13.5]]};
  const positions=effects[state.scene]||[];
  if(v551Sparkle.complete&&v551Sparkle.naturalWidth===96){
   for(let i=0;i<positions.length;i++){
    const [x,y]=positions[i],sx=x*TILE-cx,sy=y*TILE-cy;
    if(sx<-25||sx>W+25||sy<-25||sy>H+25)continue;
    const col=Math.floor(elapsed*3.3+i*2)%4;
    ctx.globalAlpha=.30+.18*Math.sin(elapsed*1.9+i);
    ctx.drawImage(v551Sparkle,col*24,0,24,24,Math.floor(sx)-12,Math.floor(sy)-16,24,24);
   }
   ctx.globalAlpha=1;
  }
 }
 // Context indicator only when action is in reach, not a permanent quest arrow.
 let target=null;
 try{target=getNearby()}catch{}
 if(target){
   const isNpc=target.kind==='npc',isDoor=target.kind==='door',isLore=target.kind==='lore';
   const mark=isDoor?v551MarkerDoor:v551MarkerSpeak;
   let px=state.player.x,py=state.player.y;
   if(isNpc){px=target.npc.x+.5;py=target.npc.y-1.1}
   else if(isLore&&target.point?.x!==undefined){px=target.point.x;py=target.point.y-.65}
   else{py-=1.25}
   let sx=px*TILE-cx,sy=py*TILE-cy;
   sy-=2*Math.sin(elapsed*3);
   if(mark.complete&&mark.naturalWidth&&sx>22&&sx<W-22&&sy>26&&sy<H-32){
    ctx.globalAlpha=.88;
    ctx.drawImage(mark,Math.floor(sx-14),Math.floor(sy-22),28,30);
   }
 }
 ctx.restore();
};
