 const id=p?.id||'';
 if(id.startsWith('fest555Cable')){const idx=FEST555_CABLES.findIndex(c=>c.id===id);if(idx>=0)return f555CollectCable(idx)}
 if(id==='fest555Mixer')return f555Mixer();
