 const ball=$('v556Ball'),label=$('v556Score');
 const pos=now=>(1-Math.cos((now-launch)*Math.PI/720))/2;
 const shoot=(assist=false)=>{
  if(token!==v556ShotSerial)return;
  const p=pos(performance.now());const good=assist||window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches||(p>.34&&p<.66);
  shot++;if(good)made++;label.textContent=`${good?'¡CANASTA!':'¡Al aro!'} · ${made}/3 acertadas · ${shot}/3 tiros`;
  if(shot===3)return conclude();
  launch=performance.now();
 };
 $('v556Shoot').onclick=()=>shoot(false);
 $('v556Assist').onclick=()=>shoot(true);
 $('v556Quit').onclick=()=>{v556ShotSerial++;backWorld()};
 const tick=now=>{if(token!==v556ShotSerial||!ball.isConnected)return;latest=pos(now);ball.style.left=(latest*100)+'%';requestAnimationFrame(tick)};
 requestAnimationFrame(tick);
