/* Pokémon Edición La Previa 5.57 · Circuito de los Siete
 * Módulo optativo: solo añade revanchas post-medalla y un pasaporte.
 * Sin cambios en mapas, medallas, colisiones, niveles de los líderes iniciales ni guardado v:1.
 */
const PREVIA557_VERSION='5.57';
const V557_LEADERS=[
 {id:'sergio',place:'Silla',title:'El Temporero',hint:'Vuelve al pabellón de Silla. Sergio asegura que había pedido una siesta, no otra batalla.'},
 {id:'blas',place:'Burger L’Horta',title:'El Sensei',hint:'Busca a Blas en el gimnasio del Burger L’Horta. Ha apuntado tu nombre en una lista de correcciones.'},
 {id:'plata',place:'L’Alqueria',title:'El Hombre de Recursos',hint:'Pásate por la pista de L’Alqueria. Plata ha preparado otra de sus comparativas.'},
 {id:'horte',place:'Sueca',title:'El del 5 %',hint:'El santuario de Horte está en Sueca. Insiste en que esta vez su probabilidad de ganar es del 5 %.'},
 {id:'nachito',place:'Picassent',title:'El Alquimista',hint:'Regresa al laboratorio de Picassent. Si huele a Brasil, vas por buen camino.'},
 {id:'turis',place:'Turís',title:'El Limonero',hint:'El gimnasio de Turís continúa anunciando 9999 victorias. Alguien tendrá que revisar esa cifra.'},
 {id:'awelo',place:'Zaragoza',title:'El Rayo Amarillo',hint:'En Zaragoza, busca al Awelo en su gimnasio. No prometas que llegarás pronto.'}
];
QUEST_NOTES.v557_circuit=['Circuito de los Siete','Volviste a enfrentarte con los siete líderes de La Previa. La octava medalla sigue pendiente.'];
QUEST_NOTES.v557_fest=['El pase de backstage','El Circuito de los Siete acabó con un pase de backstage para volver a celebrar el Festivern.'];
const v557Has=id=>Boolean(state.flags?.['v557_'+id]);
const v557Count=()=>V557_LEADERS.filter(l=>v557Has('won_'+l.id)).length;
function v557WinReward(id){
 if(v557Has('won_'+id))return false;
 state.flags['v557_won_'+id]=true;
 state.money=Math.max(0,Number(state.money)||0)+150;
 if(v557Count()===7&&!v557Has('complete')){
   state.flags.v557_complete=true;
   state.money+=800;
   state.bag.revive=(Number(state.bag.revive)||0)+2;
   state.flags.v557_backstage=true;
   noteQuest('v557_circuit');noteQuest('v557_fest');
 }
 save();updateObjective();return true;
}
function v557Passport(){
 const earned=v557Count(),finished=v557Has('complete');
 state.screen='menu';heldKeys.clear();joystick.x=joystick.y=0;
 const rows=V557_LEADERS.map((l,i)=>{
   const ok=state.badges.includes(i),done=v557Has('won_'+l.id);
   return `<div class="v557-leader ${done?'earned':''}"><b>${done?'✦':ok?'◇':'·'} ${i+1}. ${l.place}</b><small>${l.title}</small><span>${done?'REVANCHA SUPERADA':ok?'Medalla conseguida · pendiente de revancha':'Medalla todavía pendiente'}</span></div>`;
 }).join('');
 const next=V557_LEADERS.find((l,i)=>state.badges.includes(i)&&!v557Has('won_'+l.id));
 showModal(`<section class="v557-passport"><div class="eyebrow">CUADERNO DE VIAJE · EDICIÓN 5.57</div><h2>Pasaporte de revanchas</h2><p><b>${earned}/7 gimnasios</b> superados en el circuito. Cada combate se desbloquea después de obtener su medalla original.</p><div class="v557-progress" role="progressbar" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${earned}" aria-label="Revanchas superadas"><i style="width:${earned*100/7}%"></i></div><div class="v557-grid">${rows}</div><p class="v557-hint">${finished?'¡Circuito completado! Pase de backstage desbloqueado. Puedes celebrarlo en el Festivern.':next?next.hint:'Consigue tu siguiente medalla de la historia para descubrir más revanchas.'}</p><div class="modal-actions"><button class="primary" id="v557Exit">VOLVER AL JUEGO</button>${finished?'<button class="secondary" id="v557Final">VER HOMENAJE</button>':''}</div></section>`,'menu');
 $('v557Exit').onclick=backWorld;
 if(finished)$('v557Final').onclick=v557Epilogue;
}
function v557Epilogue(){
 if(!v557Has('complete'))return v557Passport();
 const festive=Boolean(state.flags.fest555Final);
 return choiceScreen('LA PREVIA · CIRCUITO DE LOS SIETE',
  'Siete gimnasios. Siete líderes vencidos dos veces. Marshall encuentra una excusa para sacar el altavoz, Blas se queja del horario y el Awelo pide que terminemos antes de empezar. '+(festive?'Nachito recuerda el Festivern y grita «BRASIL NANANANANA».':'El pase de backstage espera una futura visita al Festivern.')+' El octavo gimnasio permanece como misterio.',[
    ['Revisar pasaporte',v557Passport],
    ['Recordar el Festivern',()=>{if(state.flags.fest555Final&&typeof f555Film==='function')f555Film();else dialog('nachito',['Si vuelves al Festivern, que nadie enchufe mi alambique a los altavoces.','El pase de backstage ya es tuyo.'])}],
    ['Seguir explorando',backWorld]
  ]);
}
// Circuito iniciado desde cada gimnasio: no teleporta al jugador ni duplica su medalla.
function v557Challenge(id,boost=6){
 const leader=V557_LEADERS.find(l=>l.id===id),g=GYMS[id];
 if(!leader||!g)return backWorld();
 if(!state.badges.includes(g.i))return dialog(id,['Primero supera mi desafío original. Las revanchas son para quien ya tiene mi medalla.']);
 if(!state.flags.starter||!state.party.some(p=>p.hp>0))return dialog('alfaro',['Necesitas al menos un Pokémon en condiciones para comenzar.']);
 backWorld();healAll();
 const original=g.team;
 const scaled=original.map(([mon,lvl])=>[mon,Math.min(80,lvl+boost)]);
 try{
   g.team=scaled;
   startBattle(scaled[0][0],scaled[0][1],false,'gym:'+id);
   if(battle?.gymId===id){battle.v557Circuit=id;battle.v557Boost=boost;}
 }finally{g.team=original;}
}
const v557PriorGym=gymChallenge;
gymChallenge=function(id){
 const l=V557_LEADERS.find(x=>x.id===id),g=GYMS[id];
 if(!l||!g||!state.badges.includes(g.i))return v557PriorGym(id);
 return choiceScreen('CIRCUITO · '+l.place,
  `${l.title}. Ya tienes la medalla. En el circuito puedes repetir el combate contra un equipo reforzado. ${v557Has('won_'+id)?'Sello conseguido; puedes seguir entrenando.':'Gana para conseguir el sello y 150 monedas de recompensa única.'} Sella los siete para desbloquear el homenaje final.`,[
    ['REVANCHA · +6 NIVELES',()=>v557Challenge(id,6)],
    ['MODO EXPERTO · +12 NIVELES',()=>v557Challenge(id,12)],
    ['Otras actividades del gimnasio',()=>v557PriorGym(id)],
    ['Pasaporte del circuito',v557Passport],
    ['Seguir explorando',backWorld]
  ]);
};
// Registrar sellos exclusivamente al vencer en un combate que haya sido iniciado por este circuito.
const v557PriorWin=winBattle;
winBattle=function(){
 const id=battle?.v557Circuit;
 const newWin=id&&V557_LEADERS.some(l=>l.id===id)&&!v557Has('won_'+id);
 // Esta marca se escribe antes de los cierres de batalla, ya que los wrappers anteriores
 // reemplazan battle por null. No existe si el jugador pierde, huye o abandona el juego.
 if(newWin){v557WinReward(id)}
 return v557PriorWin();
};
// Botón en START, sin reemplazar entradas ya existentes.
const v557PriorStart=openStart29;
openStart29=function(){v557PriorStart();if(state.screen!=='start'||!state.flags?.starter)return;
 const host=$('startMenu29');if(!host)return;
 let b=host.querySelector('#v557Start');
 if(!b){b=document.createElement('button');b.type='button';b.id='v557Start';b.className='start-row29';host.append(b)}
 b.textContent='★ CIRCUITO · '+v557Count()+'/7';
 b.onclick=()=>{closeStart29();v557Passport()};
};
// Si el jugador vuelve al escenario del Festivern después de completarlo,
// ofrece también el homenaje. No modifica la cinemática original.
const v557PriorStage=f555Stage;
f555Stage=function(){
 if(!v557Has('complete')||!state.flags.fest555Final)return v557PriorStage();
 return choiceScreen('Festivern · Pase de backstage',
 'El concierto terminó, pero has regresado con los siete sellos del Circuito. Marshall ya ha reservado el escenario para la celebración.',[
  ['Homenaje al Circuito de los Siete',v557Epilogue],
  ['Repetir el final del Festivern',()=>f555Film()],
  ['Pasaporte',v557Passport],['Explorar',backWorld]
 ]);
};
const v557PriorObjective=updateObjective;
updateObjective=function(){v557PriorObjective();if(!state.flags?.starter)return;
 if(state.scene==='festivern532'&&v557Has('complete')&&state.flags.fest555Final)$('objective').textContent='FESTIVERN · Pase de backstage: vuelve al escenario para el homenaje del circuito.';
};
const v557PriorSave=serializeState;
serializeState=function(){const s=v557PriorSave();s.edition=PREVIA557_VERSION;return s};
const v557CSS=document.createElement('style');
v557CSS.textContent=`.v557-passport h2{font-size:clamp(18px,4vw,27px);margin:5px 0;color:#27364b}.v557-passport p{line-height:1.35;font-size:14px}.v557-progress{height:12px;border:2px solid #52627b;background:#d9dce9;border-radius:8px;overflow:hidden;margin:10px 0}.v557-progress i{height:100%;display:block;background:linear-gradient(90deg,#66a5aa,#f1ca70)}.v557-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin:12px 0}.v557-leader{background:#eaeef4;border:1px solid #aebacb;border-radius:7px;padding:8px;display:flex;flex-direction:column;gap:2px}.v557-leader.earned{background:#f4edd2;border-color:#d6af54}.v557-leader b{font-size:13px;color:#203f54}.v557-leader small{font-size:11px;color:#56667c}.v557-leader span{font-size:10px;font-weight:700;color:#54766c}.v557-hint{padding:9px;background:#fff3d8;border-left:3px solid #c89641;color:#473e2d}.v557-passport .modal-actions{display:flex;flex-wrap:wrap;gap:7px}.modal-card:has(.v557-passport){max-height:calc(100dvh - 22px);overflow-y:auto}@media(max-width:520px){.v557-grid{grid-template-columns:1fr}}@media(orientation:landscape) and (max-height:520px){.v557-passport h2{font-size:17px}.v557-passport p{font-size:12px;margin:4px 0}.v557-grid{grid-template-columns:repeat(4,minmax(0,1fr));margin:5px 0;gap:4px}.v557-leader{padding:4px}.v557-leader b{font-size:11px}.v557-leader small{display:none}.v557-leader span{font-size:9px}.v557-hint{padding:5px}.modal-card:has(.v557-passport){padding:10px 13px}}`;
document.head.appendChild(v557CSS);
if(window.__PREVIA_QA)Object.assign(window.__PREVIA_QA,{version557:PREVIA557_VERSION,v557:{leaders:V557_LEADERS,passport:v557Passport,challenge:v557Challenge,winReward:v557WinReward,count:v557Count,epilogue:v557Epilogue,state:()=>state,started:()=>battle,challengeMenu:id=>gymChallenge(id),start:()=>openStart29(),win:()=>winBattle(),team:(id)=>GYMS[id].team,serialize:()=>serializeState(),apply:(data)=>applySaveData(data),scene:(v)=>{state.scene=v;},screen:()=>state.screen,stage:()=>f555Stage()}});

/* Pokémon Edición La Previa 5.58 · El mundo responde
 * Mejora aditiva: 3 historias de campo, 9 hallazgos, cuaderno y paso secreto.
 * No cambia el orden de medallas ni la clave/esquema de guardados.
 */
const PREVIA558_VERSION='5.58';
const V558_ARCS=[
 {id:'borxeta',title:'El mapa que nunca estaba bien',who:'borxeta',desc:'Borxeta ha perdido las tres partes de su mapa. Parece que ha marcado tres sitios distintos como «ESTIC BÉ ACÍ????».',reward:'200 monedas y dos Poké Balls',spots:[
  {id:'v558_beni',scene:'benifaio',x:18.5,y:23.5,label:'Un mapa bajo el banco',hint:'Benifaió · en el paseo al sur de la fuente',text:['Al levantar el banco aparece una hoja doblada. «Primer mapa oficial de Borxeta».','Hay una flecha hacia Albal. Debajo: «¿ESTIC BÉ ACÍ????».']},
  {id:'v558_camino',scene:'ruta',x:21.5,y:19.5,label:'Papel entre naranjos',hint:'Camí d’Albal · desvío hacia el sur del sendero',text:['Entre las matas hay una segunda hoja con un dibujo de Blas levantando la voz.','Un aviso en rojo: «NO AWELO NO». Debe de ser el mapa de Borxeta.']},
  {id:'v558_albal',scene:'albal',x:23.5,y:20.5,label:'Plano detrás de un cartel',hint:'Albal · al sur del Burger L’Horta',text:['La tercera parte estaba detrás de un cartel. Borxeta dibujó el Burger en medio del mar.','Una nota: «Con estas tres partes por fin sabré dónde estoy». No parece muy seguro.']}
 ]},
 {id:'plata',title:'La ruta de los 87 recursos',who:'plata',desc:'Plata está preparando un atajo que ahorre tiempo a todo el grupo. Necesita tres referencias de camino antes de señalizarlo.',reward:'250 monedas, dos pociones y paso secreto',spots:[
  {id:'v558_rec_albal',scene:'albal',x:29.5,y:21.5,label:'Comparativa junto a la plaza',hint:'Albal · cerca del borde sur de la plaza',text:['En una carpeta hay 87 tablas comparando dos rutas.','Plata ha subrayado la opción B. Al margen: «La opción A también está bien, la verdad».']},
  {id:'v558_rec_naranjos',scene:'ruta2',x:30.8,y:22.8,label:'Cinta en el mirador',hint:'Senda dels Tarongers · mirador del sur',text:['Una cinta naranja señala el viejo paso entre dos sendas.','Plata ha puesto tres flechas, aunque las tres apuntan a direcciones distintas.']},
  {id:'v558_rec_rio',scene:'ruta3',x:18.2,y:23.5,label:'Baliza junto al río',hint:'Bosc del Riu · claro al oeste del puente',text:['Una baliza amarilla indica un antiguo paso al huerto.','Ahora sí: las tres pistas forman una ruta real entre los naranjos y el río.']}
 ]},
 {id:'jueves',title:'Ecos de los jueves',who:'blas',desc:'En las rutas han quedado tres recuerdos de La Previa. Descúbrelos para reconstruir una historia del grupo que termina en el Festivern.',reward:'350 monedas y un Revivir',spots:[
  {id:'v558_jue_rio',scene:'ruta3',x:11.2,y:19.4,label:'Una fotografía doblada',hint:'Bosc del Riu · sendero secundario del oeste',text:['Una foto muestra a Marshall con un altavoz más grande que su mochila.','Al dorso: «Esto no es una fiesta hasta que alguien pida que bajemos la música».']},
  {id:'v558_jue_sueca',scene:'sueca',x:8.5,y:20.5,label:'Entrada de una presentación',hint:'Sueca · junto al paseo de la plaza',text:['Una entrada de una charla pone: «El cinco por ciento lo explica todo».','Horte había preparado 47 diapositivas para anunciar un concierto. Nadie llegó a la segunda.']},
  {id:'v558_jue_marjal',scene:'ruta4',x:11.1,y:19.1,label:'Pulsera del Festivern',hint:'Camí de la Marjal · apartadero sur del sendero',text:['En el suelo brilla una pulsera del Festivern, junto a una lata vacía.','Escrito con rotulador: «LA MESA NUNCA SE CANCELA».']}
 ]}
];
const V558_EXTRA=[
 {id:'v558_secret_refuge',scene:'refugio_ruta',x:12.4,y:9.1,label:'Nota en la cocina',hint:'Refugi del Camí · rincón de la cocina',text:['Hay una receta de Javi: «Lo importante es compartir la comida».','Debajo, Blas ha añadido: «Y RECOGER LA MESA, POR FAVOR».'],reward:'potion'},
 {id:'v558_secret_cabin',scene:'caseta31',x:5.4,y:8.6,label:'Postal olvidada',hint:'La caseta del bosque · estantería oeste',text:['Una postal de Javi Grau: «He venido a buscar la tranquilidad».','La última línea dice: «Apareció Nachito con un altavoz».'],reward:'ball'}
];
const V558_SPOTS=V558_ARCS.flatMap(a=>a.spots.map(p=>({...p,arc:a.id}))).concat(V558_EXTRA.map(p=>({...p,arc:null})));
const v558Seen=id=>!!state.flags['v558_found_'+id];
const v558Count=id=>V558_SPOTS.filter(p=>p.arc===id&&v558Seen(p.id)).length;
const v558Total=()=>V558_SPOTS.filter(p=>v558Seen(p.id)).length;
const v558ArcDone=id=>!!state.flags['v558_done_'+id];
const v558CanShort=()=>v558ArcDone('plata')&&state.badges.includes(2);
QUEST_NOTES.v558_borxeta=['El mapa de Borxeta','Recogiste el mapa en tres pueblos. Borxeta todavía pregunta «ESTIC BÉ ACÍ????».'];
QUEST_NOTES.v558_plata=['El atajo de Plata','Las tres señales permitieron abrir un paso opcional entre la Senda dels Tarongers y el Bosc del Riu.'];
QUEST_NOTES.v558_jueves=['Ecos de los jueves','La fotografía, la entrada y la pulsera cuentan cómo los jueves acabaron llegando al Festivern.'];
QUEST_NOTES.v558_secret=['Rincones que cuentan historias','Has empezado a encontrar detalles escondidos fuera de las misiones principales.'];
for(const p of V558_SPOTS){
 const list=LORE_POINTS[p.scene]||(LORE_POINTS[p.scene]=[]);
 if(!list.some(q=>q.id===p.id))list.push({id:p.id,x:p.x,y:p.y,label:p.label});
}
function v558RewardArc(id){
 if(v558ArcDone(id))return false;
 const arc=V558_ARCS.find(a=>a.id===id);if(!arc||v558Count(id)!==3)return false;
 state.flags['v558_done_'+id]=true;normalizeExtras();
 if(id==='borxeta'){state.money=(Number(state.money)||0)+200;state.balls+=2;}
 if(id==='plata'){state.money=(Number(state.money)||0)+250;state.bag.potion=(Number(state.bag.potion)||0)+2;}
 if(id==='jueves'){state.money=(Number(state.money)||0)+350;state.bag.revive=(Number(state.bag.revive)||0)+1;}
 noteQuest('v558_'+id);save();return true;
}
function v558Discover(id){
 const p=V558_SPOTS.find(x=>x.id===id);if(!p)return false;
 if(!state.flags.starter){dialog('alfaro',['Visita antes mi laboratorio para empezar la aventura. Después podrás explorar los rincones de la región.']);return false}
 const wasSeen=v558Seen(id);let complete=false;
 if(!wasSeen){state.flags['v558_found_'+id]=true;
  if(!p.arc){normalizeExtras();if(id==='v558_secret_refuge')state.bag.potion=(Number(state.bag.potion)||0)+1;else state.balls+=1;noteQuest('v558_secret');}
  else complete=v558RewardArc(p.arc);
  save();
 }
 const end=complete?
  p.arc==='borxeta'?'¡Mapa recompuesto! Borxeta recibe su plano. +200 monedas y dos Poké Balls. Aun así pregunta «ESTIC BÉ ACÍ????».':
  p.arc==='plata'?'¡Ruta señalizada! +250 monedas y dos pociones. Se abre un paso secreto entre la Senda dels Tarongers y el Bosc del Riu (con la tercera medalla).':
  '¡Historia completa! +350 monedas y un Revivir. Un recuerdo más de La Previa, rumbo al Festivern.':
  p.arc?`Pistas encontradas: ${v558Count(p.arc)}/3. ${wasSeen?'Ya conocías este rincón.':'Busca las otras señales caminando por las rutas.'}`:
  wasSeen?'Este escondite ya está registrado.':'¡Objeto encontrado! '+(p.reward==='potion'?'Una poción.':'Una Poké Ball.');
 dialog(p.arc?V558_ARCS.find(a=>a.id===p.arc).who:null,[...p.text,end]);
 return true;
}
const v558PrevLandmark=landmarkTalk;
landmarkTalk=function(p){
 if(p?.id?.startsWith('v558_'))return v558Discover(p.id);
 if(p?.id==='portal'&&p.portal?.v558Shortcut){
  if(!state.flags.starter)return dialog('alfaro',['Primero debes conseguir tu Pokémon.']);
  if(!state.badges.includes(2))return dialog('plata',['El sendero es peligroso sin tres medallas. Vuelve cuando hayas superado la pista de L’Alqueria.']);
  if(!v558ArcDone('plata'))return dialog('plata',[`Plata: «Este paso ahorra tiempo. Solo necesito mis tres señales».`,`Pistas de la ruta: ${v558Count('plata')}/3. Mira en Albal, los naranjos y el Bosc del Riu.`]);
  changeScene(p.portal.to,p.portal.spawn);return;
 }
 return v558PrevLandmark(p);
};
