QUEST_NOTES.beni563_recado=['La comanda que dio la vuelta a la plaza','Vicent busca una comanda extraviada en la Plaça Major. Pregunta a Manolo y a Amadeo antes de volver a Vins & Gins.'];
QUEST_NOTES.beni563_fin=['La comanda de Vins & Gins','Has recuperado el papel perdido y ayudado a Vicent. La terraza de Benifaió sigue abierta.'];
function b563Order(){return Number(state.flags.beni563_order)||0}
function b563MedalTier(){return state.badges.length>=6?2:state.badges.length>=3?1:0}
function b563AdvanceWalk(){
 const now=performance.now();const dt=Math.min(0.06,(now-(b563AdvanceWalk.last||now))/1000);b563AdvanceWalk.last=now;
 if(state.screen!=='world'||state.scene!=='beni_plaza562')return;
 const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
 if(reduce)return;
 for(const n of B563_PEDESTRIANS){
  if(n.wait>0){n.wait=Math.max(0,n.wait-dt);n.walking=false;continue}
  const [tx,ty]=n.route[n.routeIndex],dx=tx-n.x,dy=ty-n.y,d=Math.hypot(dx,dy),step=Math.min(d,n.speed*dt);
  if(d<0.06){n.x=tx;n.y=ty;n.routeIndex=(n.routeIndex+1)%n.route.length;n.wait=n.stop;n.walking=false;continue}
  n.x+=dx/d*step;n.y+=dy/d*step;n.walking=true;
  n.walkDir=Math.abs(dx)>Math.abs(dy)?(dx>0?2:1):(dy>0?0:3);
 }
}
const b563PriorWorld=renderWorld;
renderWorld=function(){
 b563AdvanceWalk();b563PriorWorld();
 if(state.scene!=='beni_plaza562')return;
 const s=B562.beni_plaza562,cx=clamp(camera.x,0,Math.max(0,s.w*TILE-W)),cy=clamp(camera.y,0,Math.max(0,s.h*TILE-H));
 ctx.save();ctx.translate(-Math.floor(cx),-Math.floor(cy));
 const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches,phase=reduce?0:elapsed;
 // Soft moving highlights: fountain and terrace, no expensive image effects.
 const fx=24.5*TILE,fy=20.55*TILE;ctx.strokeStyle='rgba(201,248,255,.25)';ctx.lineWidth=1.8;
 for(let j=0;j<2;j++){ctx.beginPath();ctx.ellipse(fx,fy+8,20+7*j+Math.sin(phase*2+j)*2,7+2*j,0,0,Math.PI*2);ctx.stroke()}
 if(b563MedalTier()>=2){
  // The town acknowledges the seven-medal journey with small hanging festival pennants.
  ctx.strokeStyle='#9a6155';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(13*TILE,15.45*TILE);ctx.lineTo(23*TILE,15.8*TILE);ctx.stroke();
  for(let i=0;i<12;i++){ctx.fillStyle=i%3===0?'#bf473d':i%3===1?'#e8b75a':'#427b7b';let x=(13+i*.83)*TILE,y=(15.45+i*.029)*TILE;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+14,y+1);ctx.lineTo(x+7,y+13);ctx.closePath();ctx.fill()}
 }
 ctx.restore();
};
// Existing 5.62 draw routine now honors walkDir/walking; it is patched at packaging time.
const b563PreviousTalk=npcTalk;
npcTalk=function(n){
 if(n.id==='beni562_vicent'){
  const stage=b563Order();
  if(stage===0){state.flags.beni563_order=1;noteQuest('beni563_recado');save();return dialog('vicent562',['¡Menuda mañana! He perdido una comanda de la terraza y no pienso echarle la culpa al camarero.','He visto a Manolo cerca de los bancos. A lo mejor sabe por dónde ha pasado el papel.','Si la encuentras, vuelve por aquí. No hace falta correr como si fuera la final de la Minicopa.']);}
  if(stage===1)return dialog('vicent562',['Manolo suele verlo todo desde el banco, pero finge que no. Habla con él y seguimos buscando.']);
  if(stage===2)return dialog('vicent562',['¡Eso es! Si el aire se llevó la comanda, Amadeo puede haberla recogido junto a los periódicos.']);
  if(stage===3){state.flags.beni563_order=4;state.money+=120;state.bag.potion=(Number(state.bag.potion)||0)+1;noteQuest('beni563_fin');save();return dialog('vicent562',['¡Esa es nuestra comanda! Estaba entre los periódicos de Amadeo.','Por las molestias, toma 120 monedas y una Poción. Siéntate cuando quieras.','Y dile a Marshall que no organice la terraza como si fuera un bloqueo directo.']);}
  return dialog('vicent562',b563MedalTier()===2?['Con tantas medallas ya te conoce media plaza. A ver si ahora Blas deja de discutir con el camarero.','La comanda, al menos, no la hemos vuelto a perder.']:['La terraza sigue llena. Ya hemos aprendido a numerar las comandas. Gracias por el favor.']);
 }
 if(n.id==='beni562_manolo'){
  if(b563Order()===1){state.flags.beni563_order=2;save();return dialog('manolo562',['La comanda de Vicent ha salido volando por delante de la fuente.','La vi aterrizar cerca del kiosco. Pregunta a Amadeo, que ese hombre se fija en todo.']);}
  const t=b563MedalTier();return dialog('manolo562',t===2?['Antes jugabas por aquí sin medallas y ahora vienes de Zaragoza.','Aun así, nadie te libra de sentarte a escuchar mis historias de la plaza.']:t===1?['Cada vez hay más visitantes preguntando por el laboratorio de Alfaro.','No saben que lo difícil es que Borxeta encuentre la puerta correcta.']:['Me siento en esta plaza desde antes de que Marshall aprendiera a llegar puntual.','O sea, desde siempre.']);
 }
 if(n.id==='beni562_amadeo'){
  if(b563Order()===2){state.flags.beni563_order=3;save();return dialog('amadeo562',['¡Anda! ¿Buscabas este papel? Se me mezcló con los periódicos.','Dame un momento, que hoy la mano está algo torpe. Aquí lo tienes, sin prisa.','Llévaselo a Vicent. Y si quieres chuches, aquí estoy.']);}
  return dialog('amadeo562',b563MedalTier()===2?['¡Mira quién vuelve con tantas medallas! Guardo tus caramelos favoritos.','No tengo prisa. Las buenas conversaciones duran más que cualquier combate.']:['Periódicos, cromos, chuches... y buenas conversaciones.','Con las monedas voy despacito, pero te atiendo encantado.']);
 }
 if(n.id==='beni562_lucia')return dialog('lucia562',b563MedalTier()===2?['Dicen que los siete gimnasios son impresionantes. Yo sigo prefiriendo esta plaza.','Ayer Borxeta vino a preguntar por la Torre Mussa. Terminó en el Ayuntamiento.']:['Hoy hay más gente que ayer. Algunas caras no las había visto nunca.','Si buscas calma, detrás de la iglesia suele haber un rincón tranquilo.']);
 if(n.id==='beni562_marta'||n.id==='beni562_funcionaria')return dialog('marta562',b563MedalTier()===2?['Veo que vuelves con siete medallas. Excelente publicidad para el municipio.','Eso sí, para una celebración oficial hay que presentar una solicitud. Mi agenda está bastante llena.']:['La Plaça Major debe estar impecable. Es una cuestión de imagen.','Si necesitas algo urgente, habla primero con recepción. Yo tengo reuniones.']);
 if(n.id==='beni563_paseante1')return dialog('lucia562',['Voy de camino a la iglesia, pero me he entretenido viendo la terraza.','Esta plaza nunca está completamente vacía.']);
 if(n.id==='beni563_paseante2')return dialog('raul562',['Estoy buscando el ángulo perfecto para fotografiar la Torre de la Plaça.','Es distinta de la Torre Mussa. Hay gente que las confunde.']);
 if(n.id==='beni563_paseante3')return dialog('manolo562',['Una vuelta, otra vuelta... me siento cinco minutos y seguimos.','Si alguien encuentra a Borxeta, que le diga dónde está.']);
 if(n.id==='beni563_paseante4')return dialog('vicent562',['Voy a pedir un café en Vins & Gins. Después me quedo de tertulia.','¡Qué bien se está en Benifaió!']);
 return b563PreviousTalk(n);
};
const b563OldLandmark=landmarkTalk;
landmarkTalk=function(p){
 if(p.id==='beni562_iglesia'&&b563MedalTier()>=6)return dialog('Narrador',['Las campanas de San Pedro celebran el regreso de un entrenador con siete medallas.','Desde la plaza parece que toda La Previa se prepara para una última noche juntos.']);
 return b563OldLandmark(p);
};
