const s571RoomOldBase=roomBase50;
roomBase50=function(id,s){
 if(!s571RoomArt[id])return s571RoomOldBase(id,s);
 const img=asset(s571RoomArt[id]);
 if(img.complete&&img.naturalWidth){
  if(s571RoomCanvases[id])return s571RoomCanvases[id];
  const c=document.createElement('canvas');c.width=s.w*TILE;c.height=s.h*TILE;
  const g=c.getContext('2d');g.imageSmoothingEnabled=false;
  g.drawImage(img,0,0,c.width,c.height);c.dataset.polished51='1';
  return (s571RoomCanvases[id]=c);
 }
 // Never call the old room base while art is loading: on 5.70 it could crash
 // because these three new rooms had no palette or cached generated floor.
 if(!s571FallbackCanvases[id]){
  const c=document.createElement('canvas');c.width=s.w*TILE;c.height=s.h*TILE;
  const g=c.getContext('2d');g.fillStyle='#d2bc9d';g.fillRect(0,0,c.width,c.height);
  g.strokeStyle='#aa8f70';g.lineWidth=1;
  for(let x=0;x<c.width;x+=TILE)for(let y=0;y<c.height;y+=TILE)g.strokeRect(x,y,TILE,TILE);
  g.fillStyle='#3e5361';g.fillRect(0,0,c.width,TILE*3);
  g.fillStyle='#f9e8c7';g.font='bold 20px monospace';
  g.textAlign='center';g.fillText(ROOMS50[id].title,c.width/2,TILE*2);
  s571FallbackCanvases[id]=c;
 }
 return s571FallbackCanvases[id];
};
