// Fondo único y estático para cada mapa: ningún overlay ni decoración ajena que se desplace mal.
const cu572OldRender=renderWorld;
function cu572Render(){
 const m=cu572Map();if(!m)return cu572OldRender();
 const fullW=m.w*TILE,fullH=m.h*TILE;
 const cx=clamp(camera.x,0,Math.max(0,fullW-W));
 const cy=clamp(camera.y,0,Math.max(0,fullH-H));
 ctx.fillStyle=m===CU572_MAPS.cucu_jardin?'#4b6643':'#18151c';ctx.fillRect(0,0,W,H);
 ctx.save();ctx.translate(-Math.floor(cx),-Math.floor(cy));
 const im=asset(m.bg);
 if(im.complete&&im.naturalWidth){ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,fullW,fullH)}
 else {ctx.fillStyle='#c9c2a4';ctx.fillRect(0,0,fullW,fullH)}
 // One small interaction indicator, visible only when the player is nearby.
 const near=getNearby();
 if(near){const tx=near.kind==='npc'?near.npc.x:near.point.id==='cu572_exit'?near.point.exit.at[0]:near.point.object.x,
  ty=near.kind==='npc'?near.npc.y:near.point.id==='cu572_exit'?near.point.exit.at[1]:near.point.object.y;
  const x=(tx+.5)*TILE,y=(ty+.5)*TILE;
  ctx.save();ctx.fillStyle='#ffe6a6';ctx.strokeStyle='#22332bdd';ctx.lineWidth=3;
  ctx.beginPath();ctx.arc(x,y-36,7+Math.sin(elapsed*4)*1.4,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();
 }
 for(const n of m.npcs){
  const x=(n.x+.5)*TILE,y=(n.y+1)*TILE;
  if(n.who.startsWith('cucu_')){
   const img=asset(n.who+'_hi');ctx.fillStyle='#10121a66';ctx.fillRect(x-15,y-5,30,5);
   if(img.complete&&img.naturalWidth)ctx.drawImage(img,0,0,64,96,x-22,y-70,44,66);
   else drawCharacter('awelo',x,y,0,0);
  }else drawCharacter(n.who,x,y,0,0);
 }
 const p=state.player;drawCharacter(p.chosen,p.x*TILE,(p.y+.42)*TILE,p.dir,p.anim);
 ctx.restore();
}
