function cu573Altar(){
 if(cu573Done())return cu573Sequence([
  ['cucu_monaguillo',['El museo de los Santos Cojones sigue abierto, pero ahora pone «réplicas».']],
  ['awelo',['Y que no se olvide lo del cinco por ciento.']]
 ]);
 if(!cu573Ready())return cSay('cucu_monaguillo',['Antes de venerar las bolas, investiga la fuente y la pérgola del jardín.']);
 if(!cu573Won())return cSay('cucu_monaguillo',['Fray Pañuelo no deja tocar los huevos del altar. Habla con él y derrótalo primero.']);
 // Completado persistente. Si ya cobró en 5.72, no se duplican monedas ni objetos.
 const rewarded=!!state.flags.cucu_recompensa_cobrada;
 state.flags.cu573_final=true;
 state.flags.cu573_certificado=true;
 if(!rewarded){
  state.money=Math.min(9999999,(state.money||0)+500);
  state.bag=state.bag||{};state.bag.revive=(state.bag.revive||0)+2;
 }
 for(const k of ['cucu_reliquias_recuperadas','cucu_reliquias_devuelta','cucu_recompensa_cobrada','cucu_amuleto_santo_par'])state.flags[k]=true;
 noteQuest('cu573_certificado');save();updateObjective();
 cu573Sequence([
  ['cucu_fray_panuelo',['Lo confieso. Eran dos bolas doradas de decoración compradas por internet. ¡Las reliquias nunca fueron del Awelo!']],
  ['awelo',['¡PERO SI ERAN MÁS GRANDES QUE MI CABEZA! ¡QUITAD MI NOMBRE DE ESTA CAPILLA!']],
  ['marshall',['Ya está arreglado. También hemos encontrado una placa: «El hombre mejor dotado de la Ribera».']],
  ['awelo',['A ver... tampoco hace falta quitarlo TODO. Eso que quede como patrimonio cultural.']],
  ['cucu_monaguillo',['Recibes el CERTIFICADO OFICIAL DE COJONES. La Iglesia no garantiza el tamaño.'+(rewarded?' La recompensa de monedas ya estaba cobrada.':' También recibes 500 monedas y 2 Revivir.')]],
  ['cucu_fray_panuelo',['Desde mañana habrá fotos con las réplicas por diez euros. Y el Awelo se lleva un cinco por ciento.']],
  ['awelo',['¿EL CINCO POR CIENTO? Vale. Entonces sí: San Cucufato es patrimonio de La Previa.']]
 ],()=>toast('Misión completada · Certificado Oficial de Cojones'));
}

const cu573OldLandmark=landmarkTalk;
