 const id=p.object.id;
 if(id==='cu572_fuente'){
  if(cu573Has('fuente'))return cSay('marshall',['La fuente ya está investigada. Ahora falta la factura de la pérgola.']);
  cu573Set('fuente');
  return cu573Sequence([
   ['marshall',['Una placa: «Quien toque esta agua recibirá la fuerza reproductiva del Awelo». Y un ticket: FOTO CON LOS TESTÍCULOS, 5 €.']],
   ['awelo',['¡QUE DEJÉIS MIS HUEVOS EN PAZ! ¡Y COMO MÍNIMO PEDIDME PERMISO PARA EL NEGOCIO!']],
   ['cucu_peregrino',['Mi mujer y yo vinimos ayer a pedir un milagro... y hoy tenemos un Seat León.']],
   ['marshall',['Eso demuestra que hay una estafa. La otra pista está en la pérgola.']]
  ]);
 }
 if(id==='cu572_cinta'){
  if(cu573Has('pergola'))return cSay('awelo',['Ya encontramos la factura del aumento de tamaño. ¡No la enseñéis mucho!']);
  cu573Set('pergola');
  return cu573Sequence([
   ['marshall',['Encontré una factura escondida: «Ampliación de las reliquias: 300 %. Motivo: atraer turismo».']],
   ['awelo',['¡Un trescientos por ciento! Bueno... a ver... tampoco hace falta desmentirlo TODO.']],
   ['marshall',['Ya tenemos las dos pruebas. Fray Pañuelo nos espera dentro de la capilla.']]
  ]);
 }
 if(id==='cu572_mirador')return cu573Sequence([
  ['marshall',['Libro de los milagros, número 47: «El Awelo encontró aparcamiento en Valencia a la primera».']],
  ['awelo',['¡Eso sí que es imposible, hostia! ¡Borradlo que nadie se lo cree!']]
 ]);
 if(id==='cu572_velas')return cSay('cucu_monaguillo',['San Cucufato, San Cucufato, los cojones te ato; hasta que aparezcan los del Awelo, no te los desato.','Se recomienda rezar sin tocar las reliquias.']);
 if(id==='cu572_bancos')return cu573Sequence([
  ['cucu_monaguillo',['Los peregrinos vienen a tocar las bolas para tener suerte.']],
  ['awelo',['Pues que no se acostumbren. ¡La próxima vez cobro yo!']]
 ]);
 if(id==='cu572_altar')return cu573Altar();
