// Unas pocas chispas de cera/luz procedimentales en la hornacina; no añaden
// ninguna imagen, ninguna colisión ni capas desajustadas con el suelo.
const cu575OldRender=renderWorld;
renderWorld=function(){
 const ret=cu575OldRender();
 if(state.scene!=='cucu_capilla'||state.screen!=='world')return ret;
 const m=CU575_CHAPEL,fullW=m.w*TILE,fullH=m.h*TILE;
 const cx=clamp(camera.x,0,Math.max(0,fullW-W)),cy=clamp(camera.y,0,Math.max(0,fullH-H));
 ctx.save();ctx.translate(-Math.floor(cx),-Math.floor(cy));
 const bright=0.40+0.20*Math.sin(elapsed*2.3);
 for(let i=0;i<7;i++){
  const t=elapsed*(0.45+i*0.07)+i*1.91;
  const x=(13.4+(i%4)*1.65)*TILE+Math.sin(t*1.7)*3;
  const y=(4.1+(i%3)*0.72)*TILE+Math.cos(t)*4;
  ctx.globalAlpha=bright*(.54+.46*Math.sin(t)**2);
  ctx.fillStyle=i%2===0?'#fff7c1':'#ffe58e';ctx.fillRect(Math.round(x),Math.round(y),4,4);
 }
 ctx.restore();return ret;
};
