function pv576Coords(site){
 if(PV576_POS[site.id])return PV576_POS[site.id];
 const scene=SCENES[site.id],prev=state.scene,blocked=[];
 state.scene=site.id;
 try{
  const walk=(x,y)=>x>=1&&x<scene.w-1&&y>=1&&y<scene.h-1&&!collision(x+.5,y+.5);
  const seed=scene.spawn||[3,12],q=[],seen=new Set();
  function push(x,y){const k=x+','+y;if(seen.has(k)||!walk(x,y))return;seen.add(k);q.push([x,y]);}
  push(Math.floor(seed[0]),Math.floor(seed[1]));
  // En mapas cuyas apariciones antiguas caen en una casilla ocupada,
  // la alternativa sigue siendo un punto cercano al spawn, jamás un salto arbitrario.
  if(!q.length)for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)push(seed[0]+dx,seed[1]+dy);
  const reachable=[];
  for(let i=0;i<q.length;i++){
    const [x,y]=q[i];reachable.push([x,y]);
    for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]])push(x+dx,y+dy);
  }
  const portals=PORTALS[site.id]||[],npcs=getSceneNpcs(site.id),lore=LORE_POINTS[site.id]||[];
  const safe=reachable.filter(([x,y])=>{
    const px=x+.5,py=y+.5;
    if(portals.some(p=>Math.hypot(p.x-px,p.y-py)<2.25))return false;
    if(npcs.some(n=>Math.hypot(n.x+.5-px,n.y+.5-py)<2))return false;
    if(lore.some(p=>Math.hypot(p.x-px,p.y-py)<1.9))return false;
    return true;
  });
  const choices=safe.length?safe:reachable;
  choices.sort((a,b)=>Math.hypot(a[0]-site.x,a[1]-site.y)-Math.hypot(b[0]-site.x,b[1]-site.y));
  if(choices.length){const [x,y]=choices[0];PV576_POS[site.id]={x:x+.5,y:y+.5,reachable:reachable.length};PV576_REACH[site.id]=reachable;}
  return PV576_POS[site.id]||null;
 }finally{state.scene=prev;}
}
