 state.flags['postal576_'+site.id]=true;
 const done=pv576Count()===PV576_SITES.length;
 if(done&&!state.flags.postales576Premio){state.flags.postales576Premio=true;state.money=(Number(state.money)||0)+900;state.balls=(Number(state.balls)||0)+4;normalizeExtras();state.bag.potion=(Number(state.bag.potion)||0)+2;}
