 ctx.fillStyle='#f6efe1';ctx.fillRect(x+5,y+5,6,3);ctx.fillStyle='#2b4b4a';ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText(pv576Done(site.id)?'✓':'!',x,y+3);
 ctx.globalAlpha=1;
