 if(near){const t=pv576Done(site.id)?'POSTAL ARCHIVADA':'POSTAL PERDIDA';ctx.font='bold 11px monospace';const w=Math.ceil(ctx.measureText(t).width+14);ctx.fillStyle='#233b3de5';ctx.fillRect(x-w/2,y-35,w,17);ctx.fillStyle='#fff0bf';ctx.fillText(t,x,y-22);}
 ctx.restore();return ret;
