const RALLY577_POINTS={};
const rally577Stage=()=>Math.max(0,Math.min(7,Math.floor(Number(state.flags.rally577Paso)||0)));
const rally577Active=()=>!state.flags.rally577Premio&&rally577Stage()<7;
function rally577Locate(scene){
 if(RALLY577_POINTS[scene])return RALLY577_POINTS[scene];
 const base=RALLY577_ACTS.find(a=>a.scene===scene);if(!base)return null;
 const site=PV576_BY_SCENE[scene];if(!site)return null;
 const postal=pv576Coords(site);if(!postal)return null;
 const cells=PV576_REACH[scene]||[],sc=SCENES[scene];
 const other=PORTALS[scene]||[],npcs=getSceneNpcs(scene),lore=LORE_POINTS[scene]||[];
 const camp=PV576_REST[scene]?pv576CampPos(scene):null;
 const available=cells.filter(([x,y])=>{
  const xx=x+.5,yy=y+.5;
  if(Math.hypot(xx-postal.x,yy-postal.y)<3.6)return false;
  if(camp&&Math.hypot(xx-camp.x,yy-camp.y)<3)return false;
  if(other.some(p=>Math.hypot(xx-p.x,yy-p.y)<2.8))return false;
  if(npcs.some(n=>Math.hypot(xx-(n.x+.5),yy-(n.y+.5))<2.1))return false;
  if(lore.some(p=>Math.hypot(xx-p.x,yy-p.y)<2))return false;
  return true;
 });
 const choices=available.length?available:cells;
 choices.sort((p,q)=>Math.hypot(p[0]-base.x,p[1]-base.y)-Math.hypot(q[0]-base.x,q[1]-base.y));
 if(!choices.length)return null;
 return RALLY577_POINTS[scene]={x:choices[0][0]+.5,y:choices[0][1]+.5};
}
function rally577Summary(){
 const step=rally577Stage(),done=!rally577Active();
 return done?'Rally completado · Trofeo de la Mesa en tu colección':step===0?'Empieza en Benifaió: Marshall espera junto a la plaza.':`Sigue el encargo en ${RALLY577_ACTS[step].scene==='ruta4'?'Camí de la Marjal':RALLY577_ACTS[step].scene.toUpperCase()}: ${RALLY577_ACTS[step].name}.`;
}
function rally577Event(){
 const step=rally577Stage();if(step>=7||state.flags.rally577Premio)
  return dialog('marshall',['¡La Mesa Definitiva ya es patrimonio de la cuadrilla!','Tu trofeo, las monedas y los suministros ya se entregaron. Una vez; no somos una máquina tragaperras.']);
 const act=RALLY577_ACTS[step];
 if(state.scene!==act.scene)return dialog('marshall',[`Ahora toca ir a ${act.scene.toUpperCase()}.`,`Consulta el diario del rally para localizar la siguiente prueba.`]);
 if(!state.flags.starter)return dialog('alfaro',['Primero elige compañero en el laboratorio. Un rally sin Pokémon es un paseo demasiado caro.']);
 dialog(act.who,act.start,()=>rally577Challenge(step));
}
function rally577Challenge(step){
 const act=RALLY577_ACTS[step];
 choiceScreen('RALLY · '+act.name,act.prompt,act.opts.map((label,i)=>[label,()=>{
  if(step!==rally577Stage()){return backWorld();}
  if(i!==act.correct){state.flags.rally577Fallos=(Number(state.flags.rally577Fallos)||0)+1;save();return dialog(act.who,act.fail);}
  state.flags.rally577Paso=step+1;
  if(step===6&&!state.flags.rally577Premio){
   state.flags.rally577Premio=true;state.flags.rally577Trofeo=true;
   state.money=(Number(state.money)||0)+1200;state.balls=(Number(state.balls)||0)+6;
   normalizeExtras();state.bag.potion=(Number(state.bag.potion)||0)+3;
   noteQuest('rally577');
  }
  save();updateObjective();
  dialog(act.who,act.good,()=>{if(step===6)toast('★ Trofeo de la Mesa obtenido. ¡Rally completado!');else toast(`✓ Sello ${step+1}/6 · siguiente parada`);});
 }]));
}
function rally577Journal(){
 const step=rally577Stage();
 const rows=RALLY577_ACTS.map((a,i)=>{
  const completed=i<step,active=i===step&&step<7;
  const loc=a.scene==='ruta4'?'LA MARJAL':a.scene.toUpperCase();
  const icon=completed?'✓':active?'◆':'·';
  return `<div style="display:flex;gap:10px;align-items:center;justify-content:space-between;padding:9px;border-bottom:1px solid #adb9a23b;${active?'background:#6d8c6a24':''}"><div><b>${icon} ${i+1}. ${a.name}</b><div style="font-size:12px;opacity:.8">${loc}</div></div><span>${completed?'SUPERADO':active?'OBJETIVO':'PENDIENTE'}</span></div>`;
 }).join('');
 state.screen='menu';
 showModal(`<div class="eyebrow">LA PREVIA · RALLY 5.77</div><h2>El Rally de la Mesa del Jueves</h2><p>${rally577Summary()}</p><p>Ayuda a Marshall a conseguir las autorizaciones. Las pruebas se pueden repetir y no consumen objetos. Las rutas conservan sus medallas y accesos habituales.</p><div style="max-height:40vh;overflow:auto">${rows}</div><p><small>Decisiones fallidas: ${Number(state.flags.rally577Fallos)||0}. ${state.flags.rally577Trofeo?'★ Trofeo de la Mesa conseguido.':''}</small></p><div class="modal-actions"><button class="primary" id="rally577Explore">VER MAPA LOCAL</button><button class="secondary" id="rally577Back">VOLVER AL JUEGO</button></div>`,'menu');
 $('rally577Explore').onclick=rally577Map;
 $('rally577Back').onclick=backWorld;
}
function rally577Map(){
 const scene=SCENES[state.scene],stage=rally577Stage(),here=RALLY577_ACTS[stage]?.scene===state.scene;
 const entries=(PORTALS[state.scene]||[]).map(p=>`<span style="display:inline-block;padding:3px 6px;margin:2px;border-radius:5px;background:#24383e;color:#f1e0ab">${p.label||p.to}</span>`).join('');
 state.screen='menu';
 showModal(`<div class="eyebrow">LA PREVIA · GUÍA LOCAL</div><h2>${scene.name}</h2><p>Azul: zonas transitables · oscuro: obstáculos · amarillo: salidas · rosa: tu ubicación · verde: postal · naranja: objetivo del rally.</p><canvas id="rally577Canvas" width="480" height="290" style="max-width:100%;height:auto;border:2px solid #73867b;background:#1b2b32;image-rendering:pixelated;border-radius:10px"></canvas><p>${here?'◆ El encargo activo del rally está en este mapa.':rally577Summary()}</p><div style="font-size:12px;line-height:1.7">${entries}</div><div class="modal-actions"><button class="primary" id="rally577GoJournal">VER RALLY</button><button class="secondary" id="rally577Close">VOLVER AL JUEGO</button></div>`,'menu');
 $('rally577GoJournal').onclick=rally577Journal;
 $('rally577Close').onclick=backWorld;
 const canvas=$('rally577Canvas'),g=canvas.getContext('2d');
 const scale=Math.max(4,Math.floor(Math.min(454/scene.w,250/scene.h))),ox=Math.floor((480-scene.w*scale)/2),oy=Math.floor((290-scene.h*scale)/2);
 const previousScene=state.scene;
 g.fillStyle='#1b2b32';g.fillRect(0,0,480,290);
 for(let y=0;y<scene.h;y++)for(let x=0;x<scene.w;x++){
  let blocked=false;
  try{blocked=collision(x+.5,y+.5)}catch{blocked=true}
  g.fillStyle=blocked?'#334f51':'#7eaba0';g.fillRect(ox+x*scale,oy+y*scale,scale-1,scale-1);
 }
 const mark=(x,y,color,size=1)=>{const sx=ox+Math.round(x*scale),sy=oy+Math.round(y*scale);g.fillStyle='#152931';g.fillRect(sx-scale*size/2-1,sy-scale*size/2-1,scale*size+2,scale*size+2);g.fillStyle=color;g.fillRect(sx-scale*size/2,sy-scale*size/2,scale*size,scale*size)};
 for(const p of PORTALS[previousScene]||[])mark(p.x,p.y,'#ffdb77',1);
 if(PV576_BY_SCENE[previousScene]){const pos=pv576Coords(PV576_BY_SCENE[previousScene]);if(pos)mark(pos.x,pos.y,'#9deabc',1)}
 if(PV576_REST[previousScene]){const pos=pv576CampPos(previousScene);if(pos)mark(pos.x,pos.y,'#67ecdd',1)}
 if(here){const pos=rally577Locate(previousScene);if(pos)mark(pos.x,pos.y,'#ff9b50',1.25)}
 mark(state.player.x,state.player.y,'#fb8aab',1.25);
}
const rally577PrevGetNearby=getNearby;
getNearby=function(){
 const previous=rally577PrevGetNearby();
 if(state.screen!=='world'||!rally577Active())return previous;
 const a=RALLY577_ACTS[rally577Stage()];if(state.scene!==a.scene)return previous;
 const p=rally577Locate(state.scene);if(!p)return previous;
 const distance=Math.hypot(state.player.x-p.x,state.player.y-p.y);
 if(distance<1.85&&(!previous||distance+.06<previous.dist))return {kind:'lore',point:{id:'rally577',label:'RALLY · '+a.name},dist:distance};
 return previous;
};
const rally577BeforeLore=landmarkTalk;
landmarkTalk=function(p){if(p?.id==='rally577')return rally577Event();return rally577BeforeLore(p)};
const rally577BeforeRender=renderWorld;
renderWorld=function(){
 const ret=rally577BeforeRender();if(state.screen!=='world'||!rally577Active())return ret;
 const a=RALLY577_ACTS[rally577Stage()];if(a.scene!==state.scene)return ret;
 const p=rally577Locate(state.scene);if(!p)return ret;
 const scene=SCENES[state.scene],v=OUTDOORS53?.[state.scene]?outsideView53(scene):{cx:clamp(camera.x,0,Math.max(0,scene.w*TILE-W)),cy:clamp(camera.y,0,Math.max(0,scene.h*TILE-H))};
 const x=Math.round(p.x*TILE-v.cx),y=Math.round(p.y*TILE-v.cy);if(x<-50||y<-60||x>W+50||y>H+50)return ret;
 ctx.save();ctx.imageSmoothingEnabled=false;
 const t=Math.sin(elapsed*2.4)*2;
 ctx.fillStyle='#1c3638';ctx.fillRect(x-14,y-23+t,29,27);
 ctx.fillStyle='#e49a59';ctx.fillRect(x-12,y-21+t,25,22);
 ctx.fillStyle='#f5e0a7';ctx.fillRect(x-9,y-19+t,19,15);
 ctx.fillStyle='#38494d';ctx.font='bold 19px sans-serif';ctx.textAlign='center';ctx.fillText(a.icon,x,y-5+t);
 ctx.fillStyle='#543a2f';ctx.fillRect(x-8,y+4+t,16,4);
 if(Math.hypot(state.player.x-p.x,state.player.y-p.y)<3.6){let label='A · '+a.name.toUpperCase();ctx.font='bold 11px monospace';const w=ctx.measureText(label).width+18;ctx.fillStyle='#162d35ee';ctx.fillRect(x-w/2,y-45+t,w,18);ctx.fillStyle='#fff0c4';ctx.fillText(label,x,y-32+t)}
 ctx.restore();return ret;
};
