// 5.79 · Landmark-specific visual assets, mapped onto the existing solid buildings.
// Preserve special CB Silla, Burger L'Horta, Vinted and San Cucufato facades.
const S579_FACADES={
 benifaio:{'25,5,house':'s579_benifaio_casa','28,19,shop':'s579_benifaio_tienda'},
 silla:{'25,5,house':'s579_silla_oficina'},
 alqueria:{'12,3,gym':'s579_alqueria_gym','25,5,house':'s579_alqueria_taller'},
 sueca:{'25,5,house':'s579_sueca_biblioteca'}
};
const s579BeforeBuilding=drawBuilding;
drawBuilding=function(b){
 const key=`${b.x},${b.y},${b.type}`;
 const a=S579_FACADES[state.scene]?.[key];
 if(a){const im=asset(a);if(im.complete&&im.naturalWidth){
  const x=b.x*TILE,y=b.y*TILE,w=b.w*TILE,h=b.h*TILE;
  ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(im,Math.round(x),Math.round(y),Math.round(w),Math.round(h));ctx.restore();
  return;
 }}
 return s579BeforeBuilding(b);
};
for(const sceneAssets of Object.values(S579_FACADES))for(const name of Object.values(sceneAssets))asset(name);
if(window.__PREVIA_QA){Object.assign(window.__PREVIA_QA,{
 s579:{version:'5.79',facades:S579_FACADES,assets:()=>Object.values(S579_FACADES).flatMap(x=>Object.values(x)).map(x=>({name:x,loaded:asset(x).naturalWidth>0})),
  portals:()=>Object.fromEntries(['silla','alqueria','sueca','benifaio'].map(id=>[id,(PORTALS[id]||[]).map(p=>({x:p.x,y:p.y,to:p.to}))]))}
});}
