// 5.80: material-first redesign for Silla and L'Alqueria.
// Every new image is a floor texture or a court-floor illustration. No fake
// paths, walls, shops, props or collision rectangles are overlaid on the map.
const S580_VERSION='5.80';
const S580_TOWNS={silla:'s580_silla_stone_',alqueria:'s580_alqueria_stone_'};
const s580BeforeBase=baseGround53,s580FloorCache=new Map();
baseGround53=function(id){
 const floor=s580BeforeBase(id);
 if(!S580_TOWNS[id])return floor;
 if(s580FloorCache.has(id))return s580FloorCache.get(id);
 const tiles=Array.from({length:4},(_,i)=>asset(S580_TOWNS[id]+i));
 if(tiles.some(im=>!im.complete||!im.naturalWidth))return floor;
 const s=SCENES[id],c=document.createElement('canvas');c.width=s.w*TILE;c.height=s.h*TILE;
 const g=c.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(floor,0,0);
 for(let y=0;y<s.h;y++)for(let x=0;x<s.w;x++){
  const mat=material53(id,x+.5,y+.5);
  if(mat!=='stone'&&mat!=='plaza')continue;
  const im=tiles[((x*3+y*5+(x*y)%3)&3)];
  g.globalAlpha=mat==='plaza'?.83:.71;g.drawImage(im,x*TILE,y*TILE,TILE,TILE);
 }
 g.globalAlpha=1;
 // A pavement inlay beneath existing gameplay objects, independent of collision.
 const crest=asset('s580_mosaico_basket');
 if(crest.complete&&crest.naturalWidth){
  const px=id==='silla'?18:25,py=id==='silla'?21:21;
  if(material53(id,px,py)==='stone'||material53(id,px,py)==='plaza'){
   g.globalAlpha=.70;g.drawImage(crest,(px-1)*TILE,(py-1)*TILE,2*TILE,2*TILE);g.globalAlpha=1;
  }
 }
 s580FloorCache.set(id,c);return c;
};
const s580BeforeProp=drawOutdoorProp53;
drawOutdoorProp53=function(o){
 if(state.scene==='alqueria'&&o.type==='court'){
  const im=asset('s580_alqueria_court');
  if(im.complete&&im.naturalWidth){
   const x=o.x*TILE,y=o.y*TILE,w=o.w*TILE,h=o.h*TILE;
   ctx.save();ctx.imageSmoothingEnabled=false;
   ctx.fillStyle='#3d5d51';ctx.fillRect(x-6,y-6,w+12,h+12);
   ctx.drawImage(im,x,y,w,h);ctx.restore();return;
  }
 }
 return s580BeforeProp(o);
};
// The images are embedded in the HTML. Invalidate floor caches when loading
// completes, so even a first-frame entrance cannot leave an untextured map.
for(const name of [...Object.values(S580_TOWNS).flatMap(prefix=>Array.from({length:4},(_,i)=>prefix+i)),
 's580_mosaico_basket','s580_alqueria_court']){
 const im=asset(name);
 im.addEventListener('load',()=>{s580FloorCache.clear();outsideGroundCache53.delete('silla');outsideGroundCache53.delete('alqueria')});
}
