serializeState=function(){const stateData=s581OldSave();stateData.edition=S581_VERSION;return stateData;};
if(window.__PREVIA_QA)window.__PREVIA_QA.s581={
 version:S581_VERSION, scenes:['sueca','picassent'],
 texturesReady:()=>S581_NAMES.every(n=>asset(n).complete&&asset(n).naturalWidth>0),
 floor:(id)=>baseGround53(id),
 doors:()=>Object.fromEntries(['sueca','picassent'].map(id=>[id,(PORTALS[id]||[]).map(p=>({x:p.x,y:p.y,to:p.to}))])),
 collisionAt:(id,x,y)=>{const prev=state.scene;state.scene=id;try{return collision(x,y)}finally{state.scene=prev;}}
};

/* ===========================================================
   5.82 · LOS CAMINOS CON SEGUNDAS INTENCIONES
   Adds walkable loops to the existing trail spline, preserving
   town portals, NPCs, saved games and older quest triggers.
   No illustration is painted over a playable map.
   =========================================================== */
const R582_VERSION='5.82';
const R582_LOOPS={
 ruta:[
  [[10,8],[8,5],[14,4],[20,6],[22,11],[21,14]],
  [[21,14],[18,20],[22,22],[30,22],[33,14]]
 ],
 ruta2:[
  [[13,8],[14,4],[21,4],[27,7],[30,13],[35,16]],
  [[9,11],[6,18],[9,24],[17,25],[24,22],[30,19]],
  [[35,16],[39,23],[44,23],[44,20]]
 ],
 ruta3:[
  [[13,8],[8,5],[6,11],[7,21],[14,24],[20,15]],
  [[30,15],[32,7],[39,5],[43,7],[41,10]],
  [[18,11],[15,15],[18,22]]
 ],
 ruta4:[
  [[10,11],[7,7],[12,5],[19,7],[24,17]],
  [[24,17],[28,20],[34,20],[39,20],[42,21],[45,12]],
  [[34,13],[34,8],[37,8],[44,9],[45,12]]
 ]
};
// Existing paths remain the spine. New closed circuits are optional.
for(const [id,loops] of Object.entries(R582_LOOPS)){
 ROUTE_WORLDS30[id].branches.push(...loops);
}
// Older versions placed trees in areas that used to be inaccessible. Only
// remove procedural vegetation intersecting a newly drawn detour. Never
// remove rice fields, bridge rails, quest props, doors or event markers.
const R582_OPENED={};
for(const [id,loops] of Object.entries(R582_LOOPS)){
 const prev=outsideProps53[id]||[];
 outsideProps53[id]=prev.filter(o=>!(
  ['tree','rock','orange','reeds','bush'].includes(o.type) &&
  loops.some(line=>closeToLine(o.x+o.w/2,o.y+o.h/2,line,1.6))
 ));
 R582_OPENED[id]=prev.length-outsideProps53[id].length;
}
// A dry clearing makes the secret visible without covering rice fields.
const R582_SPOTS={
 ruta:[{id:'brujula',x:13.5,y:4.6,who:'blas',label:'Hito del monte',lines:['Una flecha pintada en una piedra apunta hacia el norte.','Blas escribió debajo: «Si os perdéis otra vez, os quedáis a dormir aquí, panda de inútiles».']},
       {id:'alijo',x:29.5,y:22.5,who:'marshall',label:'Mochila olvidada',lines:['Una mochila debajo del banco. Dentro hay un silbato y dos Poké Balls.','Marshall: «Llevamos tres partidos buscándola. Desde luego, sois de traca».']}],
 ruta2:[{id:'brujula',x:20.5,y:4.5,who:'nachito',label:'Naranjo señalado',lines:['Una naranja lleva dibujada una rosa de los vientos.','Nachito: «Quería inventar un GPS cítrico. Ha explotado el prototipo, pero el árbol sigue entero».']},
       {id:'alijo',x:10.5,y:24.5,who:'plata',label:'Caja bajo el bancal',lines:['Una caja escondida junto a una acequia seca.','Plata ha comparado 87 escondites. El peor era debajo del mismo cartel que dice «TESORO».']}],
 ruta3:[{id:'brujula',x:38.5,y:5.5,who:'flavio',label:'Roca del vigía',lines:['La roca tiene una flecha que señala hacia el puente del río.','Flavio: «Mamma mia, ¡hasta las piedras te piden que cambies de ritmo!»']},
       {id:'alijo',x:13.5,y:24.5,who:'raquel',label:'Cofre del claro',lines:['Entre raíces, una caja con un par de pociones intactas.','Una nota dice: «No lo subáis a Vinted. Raquel ya lo ha tasado».']}],
 ruta4:[{id:'brujula',x:11.5,y:5.5,who:'horte',label:'Estaca de la marjal',lines:['Una estaca antigua marca el sendero firme entre los arrozales.','Horte: «De cada cien posibilidades, cinco llevan a Picassent. Las otras noventa y cinco llevan a escucharme».']},
       {id:'alijo',x:43.5,y:22.5,who:'awelo',label:'Fardo entre los juncos',lines:['Una bolsa está escondida en la orilla de un sendero seco.','Awelo: «¡Que os he dicho que el atajo era por aquí, coño! Ahora dame mi silla».']}]
};
for(const [id,spots] of Object.entries(R582_SPOTS)){
 for(const p of spots){
  const key='ruta582_'+id+'_'+p.id;
  p.key=key;
  // Existing landmarks, portals and NPCs take priority at their coordinates.
  // Find a nearby collision-free tile if an older version placed a rock here.
  let candidate=null,score=Infinity;
  for(let radius=0;radius<=5;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){
   if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;
   const xx=Math.floor(p.x)+dx+.5,yy=Math.floor(p.y)+dy+.5;
   const scene=SCENES[id];if(xx<=2.5||xx>=scene.w-2.5||yy<=2.5||yy>=scene.h-2.5)continue;
   if(water53(id,xx,yy)||!routeNear30(id,xx,yy,1.55))continue;
   const oldScene=state.scene;state.scene=id;
   let blocked=true;try{blocked=collision(xx,yy)}finally{state.scene=oldScene}
   if(blocked)continue;
   if((PORTALS[id]||[]).some(q=>Math.hypot(q.x-xx,q.y-yy)<2.5))continue;
   if((LORE_POINTS[id]||[]).some(q=>Math.hypot(q.x-xx,q.y-yy)<2.4))continue;
   if((SCENES[id].npcs||[]).some(q=>Math.hypot(q.x+.5-xx,q.y+.5-yy)<2))continue;
   const rank=Math.hypot(xx-p.x,yy-p.y);
   if(rank<score){score=rank;candidate=[xx,yy]}
  }
  if(candidate){p.x=candidate[0];p.y=candidate[1];(LORE_POINTS[id]||(LORE_POINTS[id]=[])).push({id:key,x:p.x,y:p.y,label:p.label});}
 }
}
// Add a few impassable cliffs/hedges in unused terrain. The main route
// and the new loops remain free; same collision and rendering as old props.
const R582_STONES={
 ruta:[[5,5],[17,23],[36,5]],
 ruta2:[[3,6],[26,11],[37,26]],
 ruta3:[[5,25],[18,5],[43,24]],
 ruta4:[[5,5],[29,5],[47,24]]
};
const R582_ADDED=[];
for(const [id,coords] of Object.entries(R582_STONES))for(const [x,y] of coords){
 if(routeNear30(id,x+.5,y+.5,2.0)||water53(id,x+.5,y+.5))continue;
 const o=addOutdoor53(id,id==='ruta2'?'orange':id==='ruta4'?'reeds':'rock',x,y,.9,.65);
 if(o)R582_ADDED.push([id,x,y]);
}
// Invalidate only affected cached route floors; new loops now paint real paths.
for(const id of Object.keys(R582_LOOPS)){
 outsideGroundCache53.delete(id);
 terrainCache[id] && delete terrainCache[id];
}
const r582PrevLandmark=landmarkTalk;
landmarkTalk=function(p){
 if(!p?.id?.startsWith('ruta582_'))return r582PrevLandmark(p);
 const found=Object.values(R582_SPOTS).flat().find(o=>o.key===p.id);
 if(!found)return r582PrevLandmark(p);
 if(!state.flags.starter)return dialog('alfaro',['Primero elige tu compañero Pokémon, luego podrás explorar estas rutas.']);
 const first=!state.flags[p.id];
 if(first){
  state.flags[p.id]=true;
  if(found.id==='alijo'){
   normalizeExtras();
   if(p.id.includes('_ruta3_'))state.bag.potion=(state.bag.potion||0)+2;
   else state.balls=(state.balls||0)+2;
  }
  if(found.id==='brujula'){
   const count=Object.keys(R582_SPOTS).reduce((n,id)=>n+Number(!!state.flags['ruta582_'+id+'_brujula']),0);
   if(count===4&&!state.flags.ruta582_trofeo){
    state.flags.ruta582_trofeo=true;
    state.money=(Number(state.money)||0)+600;
    state.balls=(Number(state.balls)||0)+3;
    noteQuest('ruta582_trofeo');
   }
  }
  save();
 }
 const count=Object.keys(R582_SPOTS).reduce((n,id)=>n+Number(!!state.flags['ruta582_'+id+'_brujula']),0);
 const ending=first&&found.id==='brujula'&&count===4?'¡CUATRO HITOS! Marshall entrega 600 monedas y tres Poké Balls por completar la brújula.':
  first?(found.id==='alijo'?'¡Has encontrado una recompensa! Solo se puede reclamar una vez.':`Hito registrado: ${count}/4. Busca los demás desvíos.`):'Ya habías encontrado este rincón. No se repiten los premios.';
 dialog(found.who,[...found.lines,ending]);
};
QUEST_NOTES.ruta582_trofeo=['La Brújula del Jueves','Recorriste los cuatro hitos secretos de los caminos. El Awelo dice que siguen sin saber llegar a cenar.'];
// Markers are part of the landscape, not a full-screen image. The bright
// rim indicates a walkable object (player talks from the adjacent tile).
const r582PriorProps=drawTownProps;
drawTownProps=function(s){
 r582PriorProps(s);
 const landmarks=R582_SPOTS[state.scene];if(!landmarks)return;
 for(const p of landmarks){
  if(!p.key)continue;
  const px=p.x*TILE,py=p.y*TILE;
  ctx.save();
  ctx.fillStyle=p.id==='alijo'?'#79513e':'#54745c';
  ctx.fillRect(px-12,py-9,24,18);
  ctx.fillStyle=p.id==='alijo'?'#d6a15d':'#d9c794';
  ctx.fillRect(px-9,py-12,18,15);
  ctx.fillStyle='#293e40';ctx.fillRect(px-3,py-10,6,11);
  ctx.fillStyle='#fff4b9';ctx.font='bold 16px monospace';ctx.textAlign='center';
  ctx.fillText(p.id==='alijo'?'?':'✦',px,py-19);
  ctx.restore();
 }
};
