// and the extra markers do not replace the existing albums or Rally.
const r582PrevNpcTalk=npcTalk;
npcTalk=function(n){
 if(n?.id==='caminoRaquel30'&&state.flags.ruta582_ruta3_brujula){
  return dialog('raquel',['¿Has encontrado la roca del vigía? Bien. Desde allí se ve el sendero del otro margen.','No te metas en el agua, que luego me toca tasarte las zapatillas mojadas.']);
 }
 if(n?.id==='caminoRamon30'&&state.flags.ruta582_ruta4_alijo){
  return dialog('ramon_manises',['Así que encontraste la bolsa entre los juncos.','Como premio te dejo una frase: nunca hagas un atajo que termine en la acequia.']);
 }
 return r582PrevNpcTalk(n);
};
