const MG583_SCENE_SPOTS={burger:[[5,7],[13,7]],lab:[[5,8]],albal:[[9,19]],gym_sergio:[[4,10]],taller32:[[4,9]],cucu_capilla:[[16,17]],ruta2:[[14,19]],z534_tubo:[[10,12]],picassent:[[12,17]]};
function mg583PlaceMarker(g,desired){
 const old=state.scene;state.scene=g.scene;
 try{
  const sc=SCENES[g.scene],points=LORE_POINTS[g.scene]||(LORE_POINTS[g.scene]=[]);
  if(!sc)return false;
  const ok=(x,y)=>x>=2&&y>=3&&x<sc.w-2&&y<sc.h-2&&!collision(x+.5,y+.5);
  let startX=Math.floor(sc.spawn[0]),startY=Math.floor(sc.spawn[1]);
  if(!ok(startX,startY)){
   const alternatives=[];for(let y=2;y<sc.h-2;y++)for(let x=2;x<sc.w-2;x++)if(ok(x,y))alternatives.push([x,y]);
   alternatives.sort((a,b)=>Math.hypot(a[0]-startX,a[1]-startY)-Math.hypot(b[0]-startX,b[1]-startY));
   if(!alternatives.length)return false;
   [startX,startY]=alternatives[0];
  }
  const seen=new Set([startX+','+startY]),queue=[[startX,startY]],reachable=[];
  for(let i=0;i<queue.length;i++){
   const [x,y]=queue[i];reachable.push([x,y]);
   for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){
    const nx=x+dx,ny=y+dy,k=nx+','+ny;if(!seen.has(k)&&ok(nx,ny)){seen.add(k);queue.push([nx,ny]);}
   }
  }
  const npcs=getSceneNpcs(g.scene)||[],portals=PORTALS[g.scene]||[];
  const dist=(x,y,a,b)=>Math.hypot(x-a,y-b);
  for(const margin of [3,2.3,1.6,.8]){
   const cand=reachable.filter(([x,y])=>{
    const X=x+.5,Y=y+.5;
    if(dist(X,Y,startX+.5,startY+.5)<2.5)return false;
    if(portals.some(t=>dist(X,Y,t.x,t.y)<margin))return false;
    if(npcs.some(t=>dist(X,Y,t.x+.5,t.y+.5)<margin))return false;
    if(points.some(t=>dist(X,Y,t.x,t.y)<margin))return false;
    return true;
   });
   if(cand.length){cand.sort((a,b)=>dist(a[0]+.5,a[1]+.5,...desired)-dist(b[0]+.5,b[1]+.5,...desired));const [x,y]=cand[0];points.push({id:'mg583_'+g.id,x:x+.5,y:y+.5,label:'🎮 '+g.title});return true;}
  }
  return false;
 }finally{state.scene=old;}
}
