if(ART22?.characters?.rober) ART22.characters.aw588_team_cierre=ART22.characters.rober;
QUEST_NOTES.aw588_road=['La excusa de los 87 camiones','Has ayudado al Awelo a llegar a la cena, aunque tarde como siempre.'];
QUEST_NOTES.aw588_mew=['El Mew del camión','Después de derrotar al Team Cierre has capturado a Mew tras el remolque.'];
if(LORE_POINTS.albal&&!LORE_POINTS.albal.some(p=>p.id==='aw588_camiones')){
  LORE_POINTS.albal.push({id:'aw588_camiones',x:20.5,y:20.5,label:'Tráfico del Awelo · Misión'});
}
const aw588PriorLandmark=landmarkTalk;
landmarkTalk=function(p){if(p?.id==='aw588_camiones')return aw588Entry();return aw588PriorLandmark(p)};
function aw588InstallButton(){if($('aw588Top'))return;const b=document.createElement('button');b.id='aw588Top';b.type='button';b.textContent='🚚 CAMIONES';b.title='La excusa de los camiones del Awelo';(document.querySelector('.topactions')||document.querySelector('.topbar')||$('app')).appendChild(b);b.onclick=()=>{if(state.screen!=='world'){toast('Vuelve al mapa para abrir el evento.');return}aw588Entry()};}
aw588InstallButton();
function aw588Row(){
  const t=Math.random();if(t<.14)return [false,false,false];
  if(t<.40)return [true,false,true];
  const row=[false,false,false];row[Math.floor(Math.random()*3)]=true;return row;
}
function aw588Reset(){AW588.lane=1;AW588.step=0;AW588.delay=61;AW588.collisions=0;AW588.rows=Array.from({length:4},aw588Row);AW588.screen='road';}
function aw588RoadGrid(){
 const rows=AW588.rows.slice().reverse();let html='';
 rows.forEach((r,j)=>r.forEach((blocked,k)=>{html+=`<div class="aw588Cell ${blocked?'truck':''} ${j===3?'':'future'}" title="${blocked?'Camión':'Carril libre'}">${blocked?'🚚':'·'}</div>`}));
 for(let c=0;c<3;c++)html+=`<div class="aw588Cell ${c===AW588.lane?'player':''}">${c===AW588.lane?'🚗':'·'}</div>`;
 return html;
}
function aw588RoadShow(message='Awelo: «Llego en cinco minutos. Como mucho seis o cuarenta».'){
 AW588.screen='road';state.screen='menu';
 showModal(`<div class="aw588Wrap"><div class="eyebrow">EVENTO SECUNDARIO · LA PREVIA</div><h2>La excusa de los 87 camiones</h2><p class="subtle">Adelanta camiones sin chocarte. Cada tramo limpio reduce el retraso. Esquiva los camiones de la fila inferior.</p><img id="aw588RoadArt" class="aw588Art" alt="Carretera mediterránea pixel art, arte ambiental"/><div class="aw588Stats"><div><b>${AW588.step}/${AW588.goal}</b><small>TRAMOS</small></div><div><b>${AW588.delay} min</b><small>RETRASO</small></div><div><b>${AW588.collisions}/4</b><small>CHOQUES</small></div></div><div id="aw588Grid" class="aw588Road">${aw588RoadGrid()}</div><p class="aw588Help">⬅ / ➡ cambian de carril y avanzan · ⬆ sigue recto · teclas o botones táctiles</p><div class="aw588Message" id="aw588Msg">${message}</div><div class="aw588Buttons"><button id="aw588Left">⬅ IZQUIERDA</button><button id="aw588Straight" class="primary">⬆ RECTO</button><button id="aw588Right">➡ DERECHA</button></div><div class="aw588Buttons"><button id="aw588Retry" class="secondary">REINICIAR</button><button id="aw588Exit" class="secondary">SALIR</button></div></div>`);
 aw588Img('aw588RoadArt','aw588_road.webp');
 $('aw588Left').onclick=()=>aw588Move(-1);$('aw588Straight').onclick=()=>aw588Move(0);$('aw588Right').onclick=()=>aw588Move(1);$('aw588Retry').onclick=()=>{aw588Reset();aw588RoadShow('Awelo ha dado media vuelta. Dice que esta salida es buena de verdad.')};$('aw588Exit').onclick=()=>{AW588.screen='';backWorld()};
}
function aw588Move(delta){if(AW588.screen!=='road')return;
 const next=clamp(AW588.lane+delta,0,2),blocked=!!AW588.rows[0][next];AW588.lane=next;AW588.step++;
 if(blocked){AW588.collisions++;AW588.delay+=8;}else AW588.delay=Math.max(1,AW588.delay-3);
 AW588.rows.shift();AW588.rows.push(aw588Row());
 if(AW588.collisions>=4){AW588.screen='fail';return choiceScreen('¡Cuatro camiones y un atasco!',`Awelo: «¡OS JURO QUE NO SON EXCUSAS! He perdido ${AW588.delay} minutos». Blas: «No Awelo, no...».`,[['Reintentar',()=>{aw588Reset();aw588RoadShow()}],['Salir',()=>{AW588.screen='';backWorld()}]])}
 if(AW588.step>=AW588.goal)return aw588RoadWin();
 const jokes=AW588.lines;aw588RoadShow(blocked?'¡PUM! Un camión se ha cerrado. Awelo ya está redactando la excusa para el grupo.':jokes[(AW588.step-1)%jokes.length]);
}
function aw588RoadWin(){AW588.screen='';state.flags.aw588_roadDone=true;const last=Number(state.flags.aw588_bestDelay||9999);state.flags.aw588_bestDelay=Math.min(last,AW588.delay);noteQuest('aw588_road');save();
 dialog('awelo',[`Awelo: «¿Ves? ¡Solo ${AW588.delay} minutos tarde! ¡Y había camiones de verdad!».`,'Marshall: «No has llegado pronto ni esquivando el código de circulación».','Blas: «Venga, sube ya... Espera. ¿QUÉ COJONES ES ESE CAMIÓN EN LA PUERTA?»'],aw588TruckScene);
}
function aw588Intro(){return aw588Flag('mewCaught')?['El Awelo sigue enseñando la fotografía del camión y jurando que jamás llegó tarde sin motivo.','Puedes repetir la carretera, pero Mew ya fue capturado y el premio no se repite.']:['Awelo vuelve a llegar tarde al jueves. Esta vez asegura que había más camiones que clientes en el Burger.','Blas: «No Awelo no. ¡Demuestra que no te lo inventas!»','Esquiva el tráfico y llega a la mesa. Alguien ha aparcado un camión todavía peor delante del local.'];}
function aw588Entry(){if(state.screen!=='world')return;if(!state.flags.starter){toast('Primero elige tu Pokémon con Alfaro.');return}
 if(aw588Flag('roadDone'))return aw588ChooseStage();
 return dialog('awelo',aw588Intro(),()=>{aw588Reset();aw588RoadShow()});
}
function aw588ChooseStage(){state.screen='menu';choiceScreen('La excusa de los camiones','El Awelo sigue culpando al tráfico de su tardanza. ¿Qué quieres hacer?',[['Ir al camión que bloquea la entrada',aw588TruckScene],['Repetir la carretera',()=>{aw588Reset();aw588RoadShow()}],['Volver al mapa',backWorld]])}
function aw588TruckScene(){AW588.screen='truck';state.screen='menu';const boss=aw588Flag('bossWon'),caught=aw588Flag('mewCaught');
 const stage=caught?'El misterio está resuelto. Mew se ha quedado contigo. El Awelo todavía utiliza la foto del camión como justificante.':boss?'El Team Cierre ha sido derrotado. Detrás del remolque sale una luz rosa muy sospechosa.':'Un camión gigantesco corta la entrada. El conductor del Team Cierre exige un permiso de acceso que ni él sabe rellenar.';
 showModal(`<div class="aw588Wrap"><div class="eyebrow">ACTO FINAL · ENTRADA BLOQUEADA</div><h2>El último puto camión</h2><p class="subtle">${stage}</p><img id="aw588TruckArt" class="aw588Art" alt="Camión bloqueando la entrada y brillo rosa de Mew"/><div class="aw588Message">Awelo: «¿LO VEIS? ¡QUE HABÍA CAMIONES!»<br/>Blas: «Sí, gilipollas, y este encima lo has traído a la puerta».</div><div class="aw588Buttons"><button id="aw588Talk">HABLAR CON EL CAMIONERO</button>${caught?'<button id="aw588Again" class="primary">REPETIR RUTA</button>':boss?'<button id="aw588FindMew" class="primary">BUSCAR A MEW</button>':'<button id="aw588Fight" class="primary">COMBATIR TEAM CIERRE</button>'}<button id="aw588Back">VOLVER</button></div></div>`);
 aw588Img('aw588TruckArt','aw588_truck.webp');
 $('aw588Talk').onclick=()=>dialog('aw588_team_cierre',boss?['Camionero: «Me habéis tumbado. Si estáis buscando un Pokémon rosa, se ha metido detrás de la lona».']:['Camionero: «Por orden del Team Cierre, este local permanece cerrado por atasco administrativo».','Blas: «Pues te voy a tramitar una victoria por la vía rápida».'],aw588TruckScene);
 if($('aw588Fight'))$('aw588Fight').onclick=aw588BossStart;
 if($('aw588FindMew'))$('aw588FindMew').onclick=aw588MewStart;
 if($('aw588Again'))$('aw588Again').onclick=()=>{aw588Reset();aw588RoadShow()};
 $('aw588Back').onclick=()=>{AW588.screen='';backWorld()};
}
function aw588BossStart(){if(!state.party.some(p=>p.hp>0))return toast('Antes de combatir necesitas un Pokémon con PS.');
 AW588.screen='battleBoss';backWorld();const l=Math.min(28,Math.max(12,12+state.badges.length*3));startBattle('Koffing',l,false,'aw588_team_cierre');
 if(battle){battle.roster=[['Koffing',l],['Snorlax',l+1]];updateBattle()}else AW588.screen='';
}
function aw588MewStart(){if(aw588Flag('mewCaught'))return aw588TruckScene();if(!aw588Flag('bossWon'))return aw588TruckScene();if(!state.party.some(p=>p.hp>0))return toast('Recupera primero los PS del equipo.');
 AW588.screen='mewIntro';
 dialog('awelo',['Al abrir el remolque, una pequeña figura rosa flota entre las cajas de naranjas.','Awelo: «No me jodas. ¡Encima un Mew! Ahora sí que tengo excusa para dos jueves».','Mew te observa, da una vuelta en el aire y se prepara para combatir.'],()=>{aw588Set('mewActive',true);AW588.screen='battleMew';startBattle('Mew',30,true,'aw588_team_cierre');if(!battle){aw588Set('mewActive',false);AW588.screen='';}});
}
// A Team Cierre victory is not the gym progression/Blas quest; the original engine has a dedicated exemption.
const aw588OriginalWin=winBattle;
winBattle=function(){
 const boss=!!(battle&&!battle.wild&&battle.trainerId==='aw588_team_cierre');
 const mewKO=!!(battle&&battle.wild&&battle.enemy?.name==='Mew'&&aw588Flag('mewActive'));
 if(boss){aw588Set('bossWon',true);if(!aw588Flag('bossGift')){aw588Set('bossGift',true);state.balls=Math.min(9999,state.balls+3);save()}AW588.pendingVictory='boss';}
 if(mewKO){aw588Set('mewActive',false);AW588.pendingVictory='mewKO';}
 return aw588OriginalWin();
};
const aw588OriginalDialog=dialog;
dialog=function(who,lines,onEnd=()=>{}){
 const first=String(Array.isArray(lines)?lines[0]||'':'');
 if(AW588.pendingVictory&&first.startsWith('¡Victoria!')){
  const stage=AW588.pendingVictory;AW588.pendingVictory='';
  return aw588OriginalDialog(who,lines,()=>{onEnd();
   if(stage==='boss')return aw588OriginalDialog('aw588_team_cierre',['Camionero: «Vale, vale, fuera del camión. ¡Que nadie me paga horas extra por esta mierda!»','Blas: «Hemos ganado. Ahora aparta el remolque».','Camionero: «Antes mirad detrás... Hay algo rosa que no consta en el albarán».' ],aw588TruckScene);
   if(stage==='mewKO')return aw588OriginalDialog('awelo',['Mew ha desaparecido detrás de las cajas. ¡Pero su escondite sigue ahí!','Podrás regresar y volver a intentar capturarlo cuando quieras.'],aw588TruckScene);
  });
 }
 if(aw588Flag('mewActive')&&first.startsWith('¡Mew capturado!')){
  aw588Set('mewActive',false);aw588Set('mewCaught',true);noteQuest('aw588_mew');
  if(!aw588Flag('mewReward')){aw588Set('mewReward',true);state.money=Math.min(9999999,state.money+350);state.balls=Math.min(9999,state.balls+2);save()}
  return aw588OriginalDialog(who,lines,()=>{onEnd();aw588OriginalDialog('awelo',['Awelo: «¡EN LA PUTA VIDA HE LLEGADO TARDE SIN MOTIVO! ¡Ahora traigo un Mew como prueba!»','Blas: «Sí, y además te llevas 350 monedas y dos Poké Balls. Pero el jueves que viene llega a la hora».','La excusa de los 87 camiones queda registrada en el diario.'],()=>{AW588.screen='';backWorld()})});
 }
 return aw588OriginalDialog(who,lines,onEnd);
};
const aw588OriginalRun=runAway;
runAway=function(){if(battle?.wild&&battle.enemy?.name==='Mew'&&aw588Flag('mewActive')){aw588Set('mewActive',false);AW588.screen='';}return aw588OriginalRun()};
const aw588OriginalLose=loseBattle;
loseBattle=function(){if(AW588.screen==='battleMew'&&aw588Flag('mewActive'))aw588Set('mewActive',false);AW588.screen='';return aw588OriginalLose()};
window.addEventListener('keydown',ev=>{if(AW588.screen!=='road'||state.screen!=='menu')return;const d={'ArrowLeft':-1,'ArrowRight':1,'ArrowUp':0};if(Object.prototype.hasOwnProperty.call(d,ev.key)){ev.preventDefault();ev.stopImmediatePropagation();aw588Move(d[ev.key])}},true);
const aw588Serializer=serializeState;serializeState=function(){const data=aw588Serializer();data.edition='5.88';return data};
if(window.__PREVIA_QA){window.__PREVIA_QA.aw588={start:aw588Entry,road:()=>{aw588Reset();aw588RoadShow()},step:aw588Move,game:()=>({...AW588,rows:AW588.rows.map(r=>[...r])}),truck:aw588TruckScene,boss:aw588BossStart,mew:aw588MewStart,caught:()=>aw588Flag('mewCaught'),flag:aw588Flag,battle:()=>battle,valid:()=>validSave(serializeState()),win:()=>winBattle(),catch:()=>throwBall(),run:()=>runAway()};}

