document.head.appendChild(mg589Style);
function mg589Meta(id){return MG589_META[id]||{icon:'🎮',tag:'La Previa',tip:'Juega con calma.',boost:'Disfruta del reto.'}}
function mg589ProgressData(id,s){
 if(!s)return {step:0,total:1};
 if(s.done)return {step:1,total:1};
 if(id===2||id===3||id===14)return {step:(s.step||0),total:3};
 if(id===6)return {step:(s.order||0),total:5};
 if(id===9)return {step:(s.step||0),total:12};
 if(id===11)return {step:(s.step||0),total:8};
 if(id===17)return {step:(s.step||0),total:10};
 if(id===21)return {step:(s.level||0),total:3};
 if(id===27)return {step:Math.min(1,(s.moves||0)>0?0.35:0),total:1};
 if(id===30)return {step:(s.round||0),total:6};
 return {step:0,total:1};
}
function mg589ProgressPercent(id,s){const p=mg589ProgressData(id,s);return Math.max(0,Math.min(100,Math.round((p.step/p.total)*100)))}
function mg589Header(id,g,s,desc){const m=mg589Meta(id),best=mg583Best(id),done=mg583Done(id),pct=mg589ProgressPercent(id,s);return `
<div class="mg589Shell"><div class="mg589Head"><div class="mg589Art">${window.__PREVIA_MG_ART?.[id]?`<img class="mg589ArtImage" src="${window.__PREVIA_MG_ART[id]}" alt="Escenario del minijuego ${mg583Escape(g.title)}">`:`<strong>${m.icon}</strong>`}<small>${m.tag}</small></div><div class="mg589HeadText"><div class="eyebrow">LA PREVIA · MINIJUEGO 2.0 · Nº ${g.id}</div><h2>${mg583Escape(g.title)}</h2><p class="subtle">${mg583Escape(g.where)}</p><p>${desc}</p><div class="mg589Scorebar"><div><span>Completado</span><b>${done?'Sí':'No'}</b></div><div><span>Mejor marca</span><b>${best||0}</b></div><div><span>Progreso</span><b>${pct}%</b></div></div></div></div>`}
