function mg589Tip(id,extra=''){const m=mg589Meta(id);return `<div class="mg589Tip"><strong>Consejo:</strong> ${mg583Escape(m.tip)}${extra?`<br><strong>Clave:</strong> ${mg583Escape(extra)}`:''}</div>`}
function mg589StatusPills(arr){return `<div class="mg589PadLabel">${arr.map(v=>`<span>${v}</span>`).join('')}</div>`}
function mg589Legend(items){return `<div class="mg589Legend">${items.map(v=>`<span>${v}</span>`).join('')}</div>`}
