mg583Render=function(){const id=mg583Active,g=MG583_BY_ID[id],s=mg583Session;if(!g||!s||s.done)return;let body='';
 if(id===2){const r=MG583_SEATS[s.step];body=mg589Header(id,g,s,`Ronda ${s.step+1}/3. ${r.clue}`)+mg589Tip(id,mg589Meta(id).boost)+`<div class="mg583Grid">${r.options.map((v,i)=>`<button class="mg583Item" data-mg583="seat:${i}"><strong>${i+1}. ${mg583Escape(v)}</strong><small>Prueba esta posición del Burger.</small></button>`).join('')}</div>`+mg589StatusPills([`Errores: ${s.mistakes}`,`Frase: ¿ESTIC BÉ ACÍ????`]);}
 else if(id===3){const r=MG583_MAYO[s.step],options=[['Aceite de oliva','Ajo','Pepinillo'],['Fría','Templada','Caliente'],['Suave','Normal','Laboratorio']];body=mg589Header(id,g,s,`${r.label} · Experimento ${s.step+1}/3`)+mg589Tip(id,mg589Meta(id).boost)+`<div class="mg589Path">Pista de Alfaro: ${mg583Escape(r.hint)}</div>`+options.map((a,j)=>`<strong>${['Ingrediente','Temperatura','Batido'][j]}</strong>${mg583Buttons(a.map((v,k)=>[v,`mayo:${j}:${k}`,s.parts[j]===k?'class="sel"':'']))}`).join('')+mg583Buttons([['🧪 MEZCLAR','mix']])+mg589StatusPills([`Explosiones: ${s.mistakes}`,`Selección: ${s.parts.map(v=>v<0?'—':v+1).join(' / ')}`]);}
 else if(id===6){const order=MG583_BURGERS[s.order],row=MG583_BURGER_CHOICES[s.part];body=mg589Header(id,g,s,`Pedido ${s.order+1}/${MG583_BURGERS.length}. Turno de ${['base del pan','proteína','complemento'][s.part]}.`)+mg589Tip(id,mg589Meta(id).boost)+`<div class="mg589Path">Comanda completa: ${order.join(' + ')}.</div>`+mg583Buttons(row.map(v=>[v,'burger:'+v]))+mg589StatusPills([`Paso: ${s.part+1}/3`,`Errores: ${s.mistakes}`]);}
 else if(id===9||id===11||id===17){const name=id===9?'patinete de Patri':id===11?'sigilo del Temporero':'procesión del Santo Par';const limit=id===9?12:id===11?8:10;body=mg589Header(id,g,s,`Tramo ${s.step+1}/${limit} del ${name}. Cambia de carril y avanza.`)+mg589Tip(id,mg589Meta(id).boost)+mg583Buttons([['⬅ Izquierda','lane:L'],['➡ Derecha','lane:R'],['⬆ AVANZAR','advance']])+mg583Lane(id,s)+mg589StatusPills([id===9?`❤️ Vidas: ${s.hearts}`:id===11?`🔊 Ruido: ${s.noise}/4`:`🥚 Reliquias intactas: ${s.eggs}/2`,`Teclas: ← → ↑`]);}
 else if(id===14){const o=MG583_OFFERS[s.step];body=mg589Header(id,g,s,`Comparativa ${s.step+1}/3. ${o.task}`)+mg589Tip(id,mg589Meta(id).boost)+`<div class="mg583Grid">${o.choices.map((v,i)=>`<button data-mg583="offer:${i}" class="mg583Item"><b>${mg583Escape(v[0])}</b><small>Precio: ${v[1]} € · Durabilidad: ${v[2]}/6</small></button>`).join('')}</div>`+mg589StatusPills([`Errores: ${s.mistakes}`,`Plata sigue abriendo pestañas...`]);}
 else if(id===21){body=mg589Header(id,g,s,`Puzzle ${s.level+1}/3. Empuja la caja 📦 hasta la estrella ✦.`)+mg589Tip(id,mg589Meta(id).boost)+mg583Pad(false,true)+mg583GridBoard(s)+mg589StatusPills([`Movimientos nivel: ${s.moves}`,`Total: ${(s.totalMoves||0)+s.moves}`,`Teclas: flechas + Z deshacer + R reiniciar`]);}
 else if(id===27){body=mg589Header(id,g,s,'La puerta ocupa dos casillas. Gírala y llévala hasta la estrella del callejón.')+mg589Tip(id,mg589Meta(id).boost)+mg583Pad(true,true)+mg583GridBoard(s,true)+mg589StatusPills([`Movimientos: ${s.moves}`,`Orientación: ${s.vert?'vertical':'horizontal'}`,`Teclas: flechas + X girar + Z deshacer`]);}
 else if(id===30){const names=['Marshall','Plata','Awelo'],shots=['Bandeja','Triple','Tiro medio'];const preferred=['bandeja','tiro medio','triple'];const needle=((performance.now()-s.started)/1200)%2;const meter=Math.round((needle<=1?needle:2-needle)*100);body=mg589Header(id,g,s,`Posesión ${s.round+1}/6 · La Previa ${s.pts} - Rival ${s.rival}.`) + mg589Tip(id,mg589Meta(id).boost)+ mg583Buttons(names.map((v,k)=>[v,`player:${k}`,s.player===k?'class="sel"':'']))+ mg583Buttons(shots.map((v,k)=>[v,`shot:${k}`,s.shot===k?'class="sel"':'']))+`<div class="mg589MeterInfo"><span>Jugador ideal: <strong>${names[s.player]}</strong></span><span>Tiro ideal: <strong>${preferred[s.player]}</strong></span><span>Apunta al centro de la barra</span></div><div class="mg583Meter"><div class="mg583Needle"></div></div>`+mg583Buttons([['🏀 LANZAR','shoot']])+mg589StatusPills([`Marcador: ${s.pts}-${s.rival}`,`Teclas: 1/2/3 jugador · Q/W/E tiro · espacio lanzar`]);}
 const current=id===21?(s.level||0):id===27?Math.min(1,(s.moves||0)/20):id===30?(s.round||0):([2,3,14].includes(id)?s.step:id===6?s.order:s.step);
 const limit=id===21?3:id===27?1:id===30?6:id===6?5:id===9?12:id===11?8:id===17?10:3;
 const progress=id===27?Math.min(100,Math.round(current*100)):Math.min(100,Math.max(0,Math.round(current/limit*100)));
 body+=`<div class="mg584Progress" role="progressbar" aria-label="Progreso del minijuego" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div><p class="mg584ProgressLabel">Progreso ${progress}% · Si sales, tu aventura principal no se rompe.</p>`;
 body+=`<div class="mg589FooterBtns">${mg583Buttons([['Catálogo','catalog'],['Salir sin terminar','close']])}</div>`;
 body=mg589Bottom(body);
 mg583Show(body);
}

mg583Win=function(score,ending){const id=mg583Active,g=MG583_BY_ID[id],flags=mg583Flags(),first=!mg583Done(id);flags['mg583_done_'+id]=true;const oldBest=mg583Best(id);flags['mg583_best_'+id]=Math.max(oldBest,score);if(first){state.money=Math.min(9999999,Number(state.money||0)+g.reward);state.balls=Math.min(9999,Number(state.balls||0)+g.balls);if(g.potions){state.bag=state.bag||{};state.bag.potion=Math.min(9999,Number(state.bag.potion||0)+g.potions);}}save();mg583Session={done:true,score};mg583Show(`${mg589Bottom(mg589Header(id,g,{step:0},'¡Desafío superado!'))}<div class="mg589Win">${ending}</div><p><strong>Marca: ${score} puntos.</strong> Mejor marca: ${mg583Best(id)}.</p><p>${first?`🏆 Premio: ${g.reward} monedas${g.balls?', '+g.balls+' Poké Ball(s)':''}${g.potions?', '+g.potions+' poción(es)':''}.`:(score>oldBest?'🏅 ¡Nuevo récord! El premio único ya estaba cobrado.':'La recompensa ya estaba cobrada. Puedes volver a intentarlo.')}</p><div class="mg589FooterBtns">${mg583Buttons([['Volver a jugar','retry'],['Catálogo','catalog'],['Salir','close']])}</div>`)};
mg584Fail=function(reason,summary){const g=MG583_BY_ID[mg583Active],id=mg583Active;mg583Session={done:true,failed:true};mg583Show(`${mg589Bottom(mg589Header(id,g,{step:0},'Esta vez no ha podido ser.'))}<div class="mg589Failure">${mg583Escape(reason)}</div><p>${mg583Escape(summary)}</p><p>El progreso de la aventura y tus recompensas anteriores siguen intactos.</p><div class="mg589FooterBtns">${mg583Buttons([['↻ Reintentar','retry'],['Catálogo','catalog'],['Salir','close']])}</div>`)};
const mg589DispatchBase=mg583Dispatch;
mg583Dispatch=function(cmd){
 const prevId=mg583Active;
 const prev=mg583Session?JSON.parse(JSON.stringify({round:mg583Session.round,pts:mg583Session.pts,rival:mg583Session.rival,step:mg583Session.step,level:mg583Session.level,moves:mg583Session.moves,hearts:mg583Session.hearts,noise:mg583Session.noise,eggs:mg583Session.eggs})):null;
 mg589DispatchBase(cmd);
 const s=mg583Session;
 if(prevId===30 && cmd==='shoot' && s && !s.done && prev){
   const deltaPts=(s.pts||0)-(prev.pts||0), deltaR=(s.rival||0)-(prev.rival||0);
   toast(deltaPts>0?`¡Canasta! La Previa suma ${deltaPts} punto${deltaPts>1?'s':''}.`:`¡Fallaste! El rival aprovecha y anota ${deltaR||0}.`);
 }
 if(prevId===21 && cmd.startsWith('move:') && s && !s.done && prev && (s.moves||0)!==(prev.moves||0) && (s.moves||0)%8===0) toast('Piensa la siguiente empujada antes de cerrar el pasillo.');
 if(prevId===27 && cmd==='rotate' && s && !s.done) toast('Girar a tiempo suele abrir el callejón.');
};
window.addEventListener('keydown',function(ev){
 if(document.getElementById('mg618Overlay'))return;
 if(typeof mg583Active!=='number'||state.screen!=='menu'||!mg583Session||mg583Session.done)return;
 const id=mg583Active;
 let cmd=null;
 if(id===21){
   const extra={z:'undo',Z:'undo',r:'reset',R:'reset',x:'rotate',X:'rotate'};
   cmd=extra[ev.key]||null;
   if(id===21&&cmd==='rotate')cmd=null;
 }else if([9,11,17].includes(id)){
   if(ev.key===' ')cmd='advance';
 }else if(id===30){
   const keymap={'1':'player:0','2':'player:1','3':'player:2',q:'shot:0',Q:'shot:0',w:'shot:1',W:'shot:1',e:'shot:2',E:'shot:2',' ':'shoot'};
   cmd=keymap[ev.key]||null;
 }
 if(cmd){ev.preventDefault();ev.stopImmediatePropagation();mg583Dispatch(cmd);}
},true);
function mg589PlaceLore(scene,id,label,desired){
 const old=state.scene;state.scene=scene;
 try{
  const sc=SCENES[scene],points=LORE_POINTS[scene]||(LORE_POINTS[scene]=[]); if(!sc) return false;
  const ok=(x,y)=>x>=2&&y>=3&&x<sc.w-2&&y<sc.h-2&&!collision(x+.5,y+.5);
  let sx=Math.floor(sc.spawn[0]), sy=Math.floor(sc.spawn[1]);
  if(!ok(sx,sy)){
   const al=[];for(let y=2;y<sc.h-2;y++)for(let x=2;x<sc.w-2;x++) if(ok(x,y)) al.push([x,y]);
   al.sort((a,b)=>Math.hypot(a[0]-sx,a[1]-sy)-Math.hypot(b[0]-sx,b[1]-sy)); if(!al.length) return false; [sx,sy]=al[0];
  }
  const seen=new Set([sx+','+sy]),q=[[sx,sy]],reach=[];
  for(let i=0;i<q.length;i++){const [x,y]=q[i];reach.push([x,y]); for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=nx+','+ny; if(!seen.has(k)&&ok(nx,ny)){seen.add(k);q.push([nx,ny]);}}}
  const portals=PORTALS[scene]||[], npcs=getSceneNpcs(scene)||[];
  const dist=(x,y,a,b)=>Math.hypot(x-a,y-b);
  let cand=reach.filter(([x,y])=>{
    const X=x+.5,Y=y+.5; if(dist(X,Y,sx+.5,sy+.5)<2.5) return false;
    if(portals.some(t=>dist(X,Y,t.x,t.y)<2.2)) return false;
    if(npcs.some(t=>dist(X,Y,t.x+.5,t.y+.5)<2.2)) return false;
    if(points.some(t=>dist(X,Y,t.x,t.y)<1.8)) return false;
    return true;
  });
  if(!cand.length) return false; cand.sort((a,b)=>dist(a[0]+.5,a[1]+.5,desired[0],desired[1])-dist(b[0]+.5,b[1]+.5,desired[0],desired[1]));
  const [x,y]=cand[0]; points.push({id,x:x+.5,y:y+.5,label}); return true;
 } finally { state.scene=old; }
}
