 function routePoint590(route,t){
  if(!route||!route.length)return {x:1,y:1};
  if(route.length===1)return {x:route[0][0],y:route[0][1]};
  const pts=route.concat(route.slice(0,-1).reverse());
  const lens=[]; let total=0;
  for(let i=1;i<pts.length;i++){ const dx=pts[i][0]-pts[i-1][0], dy=pts[i][1]-pts[i-1][1]; const len=Math.hypot(dx,dy)||1; lens.push(len); total+=len; }
  let d=((t%total)+total)%total;
  for(let i=1;i<pts.length;i++){
   const len=lens[i-1];
   if(d<=len){ const a=pts[i-1], b=pts[i], r=d/len; return {x:a[0]+(b[0]-a[0])*r, y:a[1]+(b[1]-a[1])*r}; }
   d-=len;
  }
  const last=pts[pts.length-1]; return {x:last[0],y:last[1]};
 }
