 function safariAction593(action){
  const a=SAFARI593.current;
  if(!a||state.scene!==ID593)return;
  const e=a.entity;
  if(action==='back')return safariFlee593('Te retiras sin molestar al '+e.name+'.',8);
  if(action==='bait'){
   if(f593('baits')<=0)return safariPanel593('Ya no quedan cebos para atraerlo.');
   setf593('baits',f593('baits')-1);a.bait=Math.min(2,a.bait+1);a.mood++;
   save();
   if(Math.random()<.05+.04*a.mood)return safariFlee593('El '+e.name+' olisquea la comida y se marcha tranquilamente.');
   return safariPanel593('El '+e.name+' acepta la comida y se queda más tranquilo.');
  }
  if(action==='sneak'){
   a.care=Math.min(2,a.care+1);a.mood++;
   if(Math.random()<.12+.04*a.mood)return safariFlee593('Has hecho ruido entre las hojas y '+e.name+' se ha escabullido.');
   return safariPanel593('Das un pequeño paso y el Pokémon sigue observándote.');
  }
  if(action!=='ball')return;
  if(f593('balls')<=0){safariPanel593('No quedan Safari Balls.');return;}
  if(state.party.length>=6&&state.box.length>=300){safariPanel593('El equipo y el PC están llenos. Libera espacio antes de capturar.');return;}
  setf593('balls',f593('balls')-1);a.attempts++;const odds=captureOdds593();
  if(Math.random()<odds){
   const mon=createMon(e.name,e.level),toBox=state.party.length>=6;
   if(toBox)state.box.push(mon);else state.party.push(mon);
   e.absent=true; SAFARI593.sessionCaught++;
   setf593('caught',Math.min(9999,f593('caught')+1));
   const ix=SAFARI_NAMES593.indexOf(e.name);
   if(ix>=0)setf593('speciesMask',f593('speciesMask')|(1<<ix));
   let reward='';
   if(e.unique&&!state.flags.safari593_dragonCaught){
    state.flags.safari593_dragonCaught=true;state.money=Math.min(9999999,(state.money||0)+400);
    state.balls=Math.min(9999,(state.balls||0)+2);noteQuest('safari593_dragon');
    reward=' ¡Encuentro único! +400 monedas y 2 Poké Balls.';
   }
   const pop=f593('speciesMask').toString(2).replace(/0/g,'').length;
   if(pop>=3&&!state.flags.safari593_threeReward){
    state.flags.safari593_threeReward=true;state.money=Math.min(9999999,(state.money||0)+200);
    state.balls=Math.min(9999,(state.balls||0)+2);noteQuest('safari593_three');
    reward+=' ¡Tres especies distintas! +200 monedas y 2 Poké Balls.';
   }
   $('teamCount').textContent=state.party.length+' / 6';
   SAFARI593.current=null;save();hideModal();state.screen='world';
   return dialog('rafa_gorgues',[
    '¡Capturaste a '+e.name+'! '+(toBox?'Se ha enviado al PC.':'Se une a tu equipo Pokémon.'),
    'Tu pase Safari sigue activo. '+f593('balls')+' Safari Balls y '+f593('steps')+' pasos disponibles.'+reward
   ],()=>{if(f593('balls')<=0)finishSafari593('¡Sin Safari Balls! Has terminado esta excursión.')});
  }
  save();
  if(Math.random()<(SAFARI_SPECIES593[e.name]?.flee||.2)+a.attempts*.11-a.bait*.06){return safariFlee593('La Safari Ball ha fallado y el '+e.name+' ha huido entre la vegetación.');}
  return safariPanel593('¡La Safari Ball ha saltado! '+e.name+' sigue frente a ti. Prueba otra táctica.');
 }
