 const IDS595=new Set(['puerta_ocho','mesa_jueves']);
 FRIENDS.borja_fiestas=FRIENDS.borja_fiestas||{name:'Borja Fiestas',tag:'CAMPEÓN · RIVAL FINAL',description:'Siempre aparece cuando la historia parece resuelta. Deja pistas antes de dar la cara.'};
 QUEST_NOTES.camino595=['El Camino de los Ocho','La Liga ya no se alcanza con un simple portal. Has abierto la Puerta de los Ocho.'];
 QUEST_NOTES.mesa595=['La Mesa de los Jueves','Tres recuerdos han reactivado la Mesa de los Jueves. Borja Fiestas ha dejado una nota para el tramo final.'];
 SCENES.puerta_ocho={name:'LA PUERTA DE LOS OCHO',w:W_PUERTA,h:H_PUERTA,spawn:[18,20],buildings:[],npcs:[
  {id:'gate595_alfaro',who:'alfaro',x:18,y:18,label:'Doctor Alfaro'},
  {id:'gate595_rober',who:'rober',x:22,y:18,label:'Rober'}
 ]};
