       area608(px,py,2,7,'#477b4f');area608(px+5,py-3,2,10,'#3b6846');
       if(h>.93){area608(px-1,py-3,5,4,scene==='silla'?'#f9edd2':'#f6d8a4');area608(px+4,py-6,4,4,'#fff4d4')}
