  ctx.fillStyle='#ddb878';ctx.fillRect(x+42,y+181,w-84,2);
  ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='900 14px system-ui';ctx.fillStyle='#fff0c8';
  ctx.fillText('LA FRANQUICIA DELS INÚTILS',x+w/2,y+193,w-90);
  // Subtle basketball mosaic on both sides of the actual door.
  for(const side of [-1,1]){
   const cx=x+w/2+side*110,cy=y+h-40;
   dot612(cx,cy,16,'#c69465');dot612(cx,cy,13,'#dbac70');
   stroke612(cx-11,cy,cx+11,cy,'#765546',2);stroke612(cx,cy-12,cx,cy+12,'#765546',2);
  }
