function p617Distance(x,y,x1,y1,x2,y2){const vx=x2-x1,vy=y2-y1,q=Math.max(0,Math.min(1,((x-x1)*vx+(y-y1)*vy)/(vx*vx+vy*vy||1)));return Math.hypot(x-(x1+vx*q),y-(y1+vy*q));}
