function p617Hud(){if(!P617.overlay)return;P617.overlay.querySelector('#p617Time').textContent=`⏱ ${Math.max(0,Math.ceil(P617.seconds))}s`;P617.overlay.querySelector('#p617Lives').textContent=`${'❤️'.repeat(P617.hearts)}${'♡'.repeat(3-P617.hearts)}`;P617.overlay.querySelector('#p617Check').textContent=`🚩 ${P617.checkpoint}/3`;P617.overlay.querySelector('#p617Pause').textContent=P617.paused?'▶ Seguir':'Ⅱ Pausa';}
function p617SetPause(value){if(!P617.active||P617.ended)return;P617.paused=!!value;P617.steering.clear();P617.overlay?.querySelectorAll('[data-p617-dir]').forEach(b=>b.classList.remove('held'));P617.last=performance.now();p617Hud();}
function p617Cleanup(){P617.active=false;P617.running=false;P617.paused=true;P617.steering.clear();if(P617.raf)cancelAnimationFrame(P617.raf);P617.raf=0;if(P617.overlay){P617.overlay.remove();P617.overlay=null;}P617.canvas=null;P617.ctx=null;}
function p617Return(){p617Cleanup();mg583Active=null;mg583Session=null;backWorld();}
function p617Reset(){P617.x=3;P617.y=18;P617.dir='up';P617.hearts=3;P617.checkpoint=0;P617.seconds=85;P617.invuln=0;P617.running=false;P617.ended=false;P617.reason='';P617.message='';P617.messageT=0;P617.steering.clear();P617.paused=true;if(P617.overlay){P617.overlay.querySelector('.p617Intro').hidden=false;P617.overlay.querySelector('.p617Message').classList.remove('visible');}p617Hud();p617Paint();}
