 line();g.strokeStyle='#3d6249';g.lineWidth=t*3.1;g.stroke();
 line();g.strokeStyle='#e8d6a0';g.lineWidth=t*2.92;g.stroke();
 line();g.strokeStyle='#586c6d';g.lineWidth=t*2.67;g.stroke();
