 const ax=MG619_ALTAR.x*t,ay=MG619_ALTAR.y*t;c.fillStyle='#5c5752';c.fillRect(ax-t*.65,ay-t*.3,t*1.3,t*.75);c.fillStyle='#e9c18b';c.fillRect(ax-t*.55,ay-t*.37,t*1.1,t*.16);c.fillStyle='#b4955e';c.fillRect(ax-t*.2,ay-t*.68,t*.4,t*.43);c.fillStyle='#fff2b6';c.fillRect(ax-t*.07,ay-t*.85,t*.14,t*.6);if(MG619.stop===3){c.strokeStyle='#fff3a2';c.lineWidth=5;c.beginPath();c.arc(ax,ay,t*.7+Math.sin(MG619.walkTime)*3,0,Math.PI*2);c.stroke()}
