for(let i=0;i<MG620_STOPS.length;i++){const g=MG620_STOPS[i],X=g.x*t,Y=g.y*t,visited=i<MG620.stop; c.beginPath();c.arc(X,Y,t*.43,0,Math.PI*2);c.fillStyle=visited?'#7fcbad88':i===MG620.stop?'#ffde9788':'#d4c6a433';c.fill();c.strokeStyle=visited?'#b0edc2':i===MG620.stop?'#ffda7d':'#cebb89';c.lineWidth=3;c.stroke();c.textAlign='center';c.font=`bold ${t*.34}px sans-serif`;c.fillStyle='#23474c';c.fillText(visited?'✓':String(i+1),X,Y+t*.12)}
const gx=MG620_GOAL.x*t,gy=MG620_GOAL.y*t;c.fillStyle='#2c615e';c.fillRect(gx-t*.68,gy-t*.72,t*1.36,t*1.35);c.fillStyle='#f4e9ce';c.fillRect(gx-t*.52,gy-t*.55,t*1.04,t*.86);c.fillStyle='#b45a47';c.fillRect(gx-t*.55,gy-t*.65,t*1.1,t*.17);c.font=`bold ${t*.18}px sans-serif`;c.textAlign='center';c.fillStyle='#184a45';c.fillText('SALIDA',gx,gy+t*.12);if(MG620.stop===3){c.strokeStyle='#f8df93';c.lineWidth=5;c.beginPath();c.arc(gx,gy,t*.80+Math.sin(MG620.anim)*3,0,Math.PI*2);c.stroke()}
