function mg620Frame(now){if(!MG620.active)return;const dt=Math.min(.05,Math.max(0,(now-MG620.last)/1000||0));MG620.last=now;mg620Update(dt);if(MG620.noticeTimer>0){MG620.noticeTimer-=dt;if(MG620.noticeTimer<=0)MG620.overlay?.querySelector('.mg620Notice').classList.remove('on')}if(MG620.active){mg620Paint();MG620.raf=requestAnimationFrame(mg620Frame)}}
function mg620Open(){if(state.scene!=='z534_tubo'){toast('Nachito y la puerta están en El Tubo, Zaragoza.');return}if(!state.flags.starter){toast('Elige primero a tu Pokémon con Alfaro.');return}mg620Cleanup();mg583Active=27;mg583Session={mode:'tubo620',started:performance.now()};hideModal();state.screen='menu';const o=document.createElement('section');o.id='mg620Overlay';o.setAttribute('role','dialog');o.setAttribute('aria-label','Nachito se lleva la puerta: recorrido jugable por El Tubo');o.innerHTML=`<header class="mg620Top"><span><strong>EL TUBO</strong> · ZARAGOZA</span><span id="mg620GoalText">1/3 · PLAZA</span><span id="mg620Hearts">🚪 ♥♥♥</span><span id="mg620Clock">⏱ 145 s</span></header><div class="mg620Scene"><canvas id="mg620Canvas" aria-label="Mapa jugable de las calles de Zaragoza con puerta, peatones, controles y salida"></canvas><div class="mg620Notice" aria-live="polite"></div><div class="mg620Pad" aria-label="Controles de movimiento"><button data-mg620-dir="up" aria-label="Arriba">▲</button><button data-mg620-dir="left" aria-label="Izquierda">◀</button><button data-mg620-dir="down" aria-label="Abajo">▼</button><button data-mg620-dir="right" aria-label="Derecha">▶</button></div><button class="mg620Rotate" id="mg620Rotate">↻ GIRAR<br>PUERTA</button><div class="mg620Intro"><div class="mg620Card"><small>EL TUBO · ZARAGOZA · RETO Nº 27</small><h2>🚪 Nachito se lleva la puerta</h2><p>Nachito ha arrancado una puerta y pretende cruzar Zaragoza con ella. Recorre <strong>tres checkpoints dorados</strong> y llega a la <strong>SALIDA</strong>. Los obstáculos y las calles son sólidos: la puerta <strong>ocupa dos casillas</strong>.</p><p><strong>WASD / flechas / cruceta</strong> para caminar; <strong>R, espacio o GIRAR</strong> para rotar la puerta; <strong>Shift</strong> para moverte con precisión. Evita a Blas, Marshall, Awelo y Plata. Tienes tres golpes y 145 segundos.</p><p><b>Premio histórico: 270 monedas y 1 Poké Ball (una vez).</b></p><button id="mg620Go">¡VENGA, NACHITO!</button></div></div></div><footer class="mg620Tools"><small id="mg620Mode">↻ HORIZONTAL</small><div><button id="mg620Pause">⏸ Pausa</button><button id="mg620Restart">↻ Reiniciar</button><button id="mg620Exit">✕ Salir</button></div></footer>`;gameShell.appendChild(o);MG620.active=true;MG620.overlay=o;MG620.canvas=o.querySelector('canvas');MG620.ctx=MG620.canvas.getContext('2d');MG620.last=performance.now();mg620Reset();o.querySelector('#mg620Go').onclick=mg620Begin;o.querySelector('#mg620Pause').onclick=()=>MG620.running?mg620Pause(!MG620.paused):mg620Begin();o.querySelector('#mg620Restart').onclick=mg620Reset;o.querySelector('#mg620Exit').onclick=mg620Exit;o.querySelector('#mg620Rotate').onclick=mg620Rotate;
for(const b of o.querySelectorAll('[data-mg620-dir]')){const direction=b.dataset.mg620Dir;b.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(!MG620.running||MG620.paused)return;try{b.setPointerCapture(e.pointerId)}catch(_){}MG620.keys.add(direction);b.classList.add('held')});const stop=e=>{e.preventDefault();MG620.keys.delete(direction);b.classList.remove('held')};for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,stop)}MG620.raf=requestAnimationFrame(mg620Frame)}
