 collection.innerHTML='<summary>🎁 Ver los diez Pokémon-regalo y sus niveles</summary><div class="mg623-collection-list">'+MG583_LIST.map(g=>{const d=MG623_GIFTS[g.id];const received=!!state.flags[mg623Flag(g.id)],pending=!!state.flags[mg623Pending(g.id)];return `<div class="mg623-collection-item"><span><b>${mg583Escape(g.title)}</b><small>${mg583Escape(g.where)}</small></span><span><b>${d.name} · Nv. ${d.level}</b><small>${received?'✓ Recibido':pending?'⚠ Pendiente':'Por descubrir'}</small></span></div>`}).join('')+'</div>';
 banner.insertAdjacentElement('afterend',collection);

