function mg624Claim(id){const item=mg624Award(id);if(item)mg624Show(id,item);return item;}
for(const [id,spec]of Object.entries(MG624_STORY))QUEST_NOTES[mg624Chapter(id)]=['Regalo de '+spec.giver,spec.note+' Recibiste a '+spec.name+'.'];
// Blas: solo después de resolver la conspiración de Cierre S. L.
