// Nachito: solo después de rescatar los siete ecos / avance equivalente.
const mg624PriorNpcTalk=npcTalk;
npcTalk=function(n){
 const id=n?.id||'';
 if(id==='burger527Blas'&&mg624Ready('blas')&&!state.flags[mg624GiftFlag('blas')]){
  return dialog('blas',['Has evitado que Rober compre el Burger. Y Javi por fin ha sacado esa hamburguesa sin incendiar la cocina.','Mira, tengo algo para ti. Un Eevee. Yo tengo un Umbreon, así que más te vale cuidarlo.','¡Y NO AWELO NO! ¡Ni se te ocurra darle mayonesa!'],()=>mg624Claim('blas'));
 }
 if((id==='gym_horte'||id==='horteSlides')&&mg624Ready('horte')&&!state.flags[mg624GiftFlag('horte')]){
  return dialog('horte',['¡EL CINCO POR CIENTO! ¡LA REMONTADA FUE REAL, CULORROTOS!','He criado este Magikarp siguiendo las 47 diapositivas de mi método. Está a un nivel de evolucionar.','Confía en el cinco por ciento y acéptalo.'],()=>mg624Claim('horte'));
 }
 if((id==='gym_nachito'||id==='nachitoSchool')&&mg624Ready('nachito')&&!state.flags[mg624GiftFlag('nachito')]){
  return dialog('nachito',['Has recuperado a las siete versiones de mí mismo. No voy a preguntar cómo.','El experimento dejó una bola que flota, suelta humo y parece un Pokémon.','Te la regalo. Por favor, no la enchufes a nada.'],()=>mg624Claim('nachito'));
 }
 // La misión de Raquel tiene tres etapas y aprovecha al Juan Cartero real.
 if(id==='vintedRaquel33'&&!state.flags[mg624GiftFlag('raquel')]){
  const step=Number(state.flags.mg624_raquel_step)||0;
  if(step===0)return choiceScreen('Raquel · El paquete que cambia','«Juan me debe un envío. En el seguimiento aparece como camiseta, como mochila y como una tostadora. ¡NO ENTIENDO NADA!»',[
    ['Ayudar a Raquel',()=>{state.flags.mg624_raquel_step=1;save();dialog('raquel_soriano',['Busca a Juan el Cartero por las rutas de La Previa.','Dile que el paquete número 87 no es una prenda normal. ¡Y que deje de ponerlo en venta!']);}],
    ['Ver mi ropa',()=>mg624PriorNpcTalk(n)],['Ahora no',backWorld]
  ]);
  if(step===1)return choiceScreen('Raquel · En busca de Juan','«El paquete todavía no aparece. Juan el Cartero se mueve por las rutas. ¡Pregúntale por el número 87!»',[
    ['Ver tienda',()=>mg624PriorNpcTalk(n)],['Continuar buscando',backWorld]
  ]);
  if(step===2)return dialog('raquel_soriano',['¡Juan dice que el paquete está aquí!','Revisa la pila de paquetes junto al perchero. Hay uno que cada vez que lo miro cambia de forma.']);
  return dialog('raquel_soriano',['¡Has encontrado el paquete 87!','Se ha convertido en mochila, en camiseta y ahora... en una mancha violeta que sonríe.','Llévatelo tú, cariño, que yo solo vendo ropa. ¡NO ACEPTO DEVOLUCIONES DE POKÉMON!'],()=>mg624Claim('raquel'));
 }
 if(n?.who==='juan_cartero523'&&Number(state.flags.mg624_raquel_step)===1&&!state.flags[mg624GiftFlag('raquel')]){
  state.flags.mg624_raquel_step=2;save();
  return dialog('juan_cartero523',['¡Xe! ¿El paquete 87 de Raquel? Lo traía en esta bolsa.','Primero pesaba como una mochila. Luego parecía una camiseta. Ahora no pesa absolutamente nada.','Dile a Raquel que mire la caja del fondo de Vinted. Y si ves a Dudu, tengo otra entrega para él.'],()=>mg624PriorNpcTalk(n));
 }
 return mg624PriorNpcTalk(n);
};
const mg624PriorLandmarkTalk=landmarkTalk;
landmarkTalk=function(p){
 if(p?.id==='vintedPaquete33'&&Number(state.flags.mg624_raquel_step)===2&&!state.flags[mg624GiftFlag('raquel')]){
  state.flags.mg624_raquel_step=3;save();
  return dialog(null,['PAQUETE 87 · VINTED. La caja tiembla encima de las otras.','Al abrirla hay una camiseta. Al parpadear, una gorra. Después aparece una masa violeta que te sonríe.','No se escapa. Vuelve a hablar con Raquel para preguntarle qué es.']);
 }
 return mg624PriorLandmarkTalk(p);
};
// Mostrar la colección de historia junto al catálogo de los diez minijuegos.
const mg624PriorCatalog=mg583Catalog;
mg583Catalog=function(){const res=mg624PriorCatalog();
 const count=mg624Count(),elt=document.createElement('details');elt.className='mg623-collection mg624-collection';
 const rows=Object.entries(MG624_STORY).map(([id,g])=>{
  const got=!!state.flags[mg624GiftFlag(id)],pending=!!state.flags[mg624PendingFlag(id)];
  const status=got?'✓ Recibido':pending?'⚠ Esperando hueco':mg624Ready(id)?'🎁 Habla con '+g.giver:'🔒 Por descubrir';
  return `<div class="mg623-collection-item"><span><b>${mg583Escape(g.where)}</b><small>${mg583Escape(g.giver)}</small></span><span><b>${got?mg583Escape(g.name)+' · Nv. '+g.level:'Regalo de historia'}</b><small>${mg583Escape(status)}</small></span></div>`;
 }).join('');
 elt.innerHTML=`<summary>🎁 Regalos de la historia: ${count} / 4</summary><div class="mg623-collection-list">${rows}</div>`;
 const existing=modalContent.querySelector('.mg623-collection')||modalContent.querySelector('.mg623-banner');
 if(existing)existing.insertAdjacentElement('afterend',elt);
 return res;
};
