/* 6.25 · OPERACIÓN CIERRE: LA ÚLTIMA COMANDA.
   Side chapter integrated with actual Burger -> Albal -> Silla maps and a new
   bespoke explorable warehouse. Persists flags in old save v:1; no new badge.
   Runs inside the existing motor IIFE; existing NPC, gift, battles stay intact.
*/
const OP625_VERSION='6.25';
const OP625={active:false,running:false,paused:true,ended:false,overlay:null,canvas:null,ctx:null,keys:new Set(),raf:0,last:0,clock:0,player:{x:3.5,y:16.5},hearts:3,inv:0,found:[false,false],guards:[],alert:0,toastUntil:0,msg:'',terminal:false};
const OP625_START={x:3.5,y:16.5},OP625_GATE={x:27.5,y:3.5};
