const OP625_GRID=Array.from({length:20},(_,y)=>Array.from({length:32},(_,x)=>y<2||y>17||x<2||x>29?'#':'.'));
function op625Crate(x,y,w,h){for(let j=y;j<y+h;j++)for(let i=x;i<x+w;i++)OP625_GRID[j][i]='#'}
// Real collision masks: no decorative crates on walkable floor.
for(const r of [[6,4,4,2],[14,4,4,2],[21,4,3,2],[6,8,3,2],[14,8,4,2],[26,9,2,3],[6,14,3,2],[15,13,4,2],[22,13,3,2],[27,15,2,2]])op625Crate(...r);
const OP625_ROWS=OP625_GRID.map(a=>a.join(''));
const OP625_GUARDS=[
 {name:'Inspector del albarán',who:'rober',route:[[11.5,6.5],[20.5,6.5]],speed:1.05,phase:0},
 {name:'Revisor de sillas',who:'sergio',route:[[11.5,11.5],[20.5,11.5]],speed:.9,phase:.9},
 {name:'Becario de las 23:55',who:'plata',route:[[28.5,6.5],[28.5,13.5]],speed:.85,phase:1.8}
];
