 const x=8.5*TILE-cx,y=19.5*TILE-cy;ctx.save();ctx.translate(x,y);ctx.fillStyle='#422f30';ctx.fillRect(-35,-35,70,45);ctx.fillStyle='#ab7b59';ctx.fillRect(-30,-30,60,33);ctx.fillStyle='#172e36';ctx.fillRect(-22,-28,44,30);ctx.strokeStyle='#dcb979';ctx.lineWidth=3;ctx.strokeRect(-22,-28,44,30);ctx.fillStyle='#ffe5a1';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText('CIERRE S. L.',0,-39);ctx.font='16px system-ui';ctx.fillText(op625Stage()>=3?'🔓':'🔒',0,-4);ctx.restore();
