function op625Blocked(x,y){let ix=Math.floor(x),iy=Math.floor(y);return iy<0||iy>=20||ix<0||ix>=32||OP625_ROWS[iy][ix]==='#'}
function op625Pass(x,y){for(const dx of [-.24,.24])for(const dy of [-.24,.24])if(op625Blocked(x+dx,y+dy))return false;return true}
function op625Sight(a,b){const d=Math.hypot(a.x-b.x,a.y-b.y);for(let t=.2;t<d;t+=.24){const r=t/d;if(op625Blocked(a.x+(b.x-a.x)*r,a.y+(b.y-a.y)*r))return false;}return true;}
