 if(dx||dy){const nx=OP625.player.x+dx*speed*dt,ny=OP625.player.y+dy*speed*dt;if(op625Pass(nx,OP625.player.y))OP625.player.x=nx;if(op625Pass(OP625.player.x,ny))OP625.player.y=ny;}
 for(let i=0;i<2;i++){if(OP625.found[i])continue;const a=OP625_ITEMS[i];if(Math.hypot(OP625.player.x-a.x,OP625.player.y-a.y)<.75){OP625.found[i]=true;op625Notice((i?'¡CONTRATO RECUPERADO!':'¡FACTURA DEL 5 % RECUPERADA!')+' '+(i?'Plata: «He comparado 87 contratos...»':'Blas: «¡Que no me cobren las mesas!»'));op625Hud();}}
 if(op625Stage()>=6&&!state.flags.op625_secret&&Math.hypot(OP625.player.x-5.5,OP625.player.y-3.5)<.9){state.flags.op625_secret=true;state.balls=Math.min(9999,state.balls+2);noteQuest('op625_secret');save();op625Notice('¡CAJA SECRETA! +2 Poké Balls. Es la cuenta que Giovanni no revisó.');}
 for(const g of (op625Stage()>=6?[]:OP625_GUARDS)){const gp=op625GuardPos(g,OP625.clock),dist=Math.hypot(gp.x-OP625.player.x,gp.y-OP625.player.y);if(dist< (k.has('quiet')?.68:1.05)&&OP625.inv===0){OP625.hearts--;OP625.inv=3;op625Notice(g.name+': «¡ALTO, QUE NO TENGO TU DNI FISCAL!»');OP625.player={...OP625_START};op625Hud();if(OP625.hearts<=0){OP625.ended=true;OP625.running=false;op625Panel('¡Te han descubierto!','Rober ha archivado tu intento como «incidencia 87». Puedes reintentarlo sin perder el pase ni tu partida.',[['Reintentar',()=>{op625Reset();OP625.running=true;op625Resume()}],['Salir',op625Leave]]);}break;}}
