 for(let y=0;y<20;y++)for(let x=0;x<32;x++){const xx=x*t,yy=y*t,isWall=OP625_ROWS[y][x]==='#';if(!isWall){c.fillStyle=(x+y)%2?'#b09e81':'#b8a68a';c.fillRect(xx,yy,t+.4,t+.4);c.strokeStyle='#867e6b55';c.strokeRect(xx+.5,yy+.5,t-1,t-1);if((x*7+y*11)%19===0){c.fillStyle='#dbceae';c.fillRect(xx+t*.17,yy+t*.70,t*.18,2)}}else{c.fillStyle='#3c4948';c.fillRect(xx,yy,t,t);c.fillStyle='#6e5c49';c.fillRect(xx+t*.1,yy+t*.07,t*.8,t*.83);c.fillStyle='#ad8452';c.fillRect(xx+t*.13,yy+t*.11,t*.73,t*.60);c.strokeStyle='#e0b77b';c.lineWidth=2;c.strokeRect(xx+t*.2,yy+t*.17,t*.6,t*.5);c.beginPath();c.moveTo(xx+t*.22,yy+t*.18);c.lineTo(xx+t*.78,yy+t*.65);c.stroke();}}

 OP628.ground=cvs;OP628.groundTile=t;OP628.groundPaints++;
