 const t=Math.max(29,Math.min(49,w/12.8)),cx=clamp(OP625.player.x*t-w*.5,0,32*t-w),cy=clamp(OP625.player.y*t-h*.52,0,20*t-h);c.fillStyle='#293d43';c.fillRect(0,0,w,h);c.save();c.translate(-cx,-cy);
