const $=id=>panel.querySelector('#'+id),$scene=$('w641_scene'),$dest=$('w641_dest'),
 canvas=$('world641_map'),g=canvas.getContext('2d');
const scenes=NAMES.slice().sort((a,b)=>(SCENES[a].name||a).localeCompare(SCENES[b].name||b));
