const previousLandmark=landmarkTalk;
landmarkTalk=function(point){
 if(state.scene==='albal'&&point?.id==='portal'&&['casa_albal32','quimica56'].includes(point.portal?.to)){
  const options=(PORTALS.albal||[]).filter(x=>['casa_albal32','quimica56'].includes(x.to));
  if(options.length<2)return previousLandmark(point);
  if(!state.flags.starter)return previousLandmark(point);
  state.screen='dialog';
  showModal('<div class="eyebrow">ALBAL · DOS PUERTAS JUNTAS</div><h2>¿Dónde quieres entrar?</h2><p>La casa de la plaza y la sala de química comparten acceso. Elige el interior.</p><div class="modal-actions"><button id="world641_home">Casa de la plaza</button><button id="world641_chem" class="primary">Sala de química</button><button id="world641_cancel">Cancelar</button></div>','dialog');
  const enter=to=>{hideModal();state.screen='world';const p=options.find(o=>o.to===to);if(p)previousLandmark({id:'portal',portal:p})};
  document.getElementById('world641_home').onclick=()=>enter('casa_albal32');
  document.getElementById('world641_chem').onclick=()=>enter('quimica56');
  document.getElementById('world641_cancel').onclick=()=>{hideModal();state.screen='world';};
  return;
 }
 return previousLandmark(point);
};
